local config = {
  ui_story_5046_50460101_1_dialog_content = "PlayerName!",
  ui_story_5046_50460101_2_dialog_content = "Sungguh luar biasa Anda berada di sini untuk upacara penyelesaian Panti Asuhan Umbraton!",
  ui_story_5046_50460101_3_dialog_content = "Sudah lama, Bethel.",
  ui_story_5046_50460101_4_dialog_content = "Saya tidak akan melewatkannya untuk dunia bahkan tanpa undangan dari Shadowlord.",
  ui_story_5046_50460101_5_dialog_content = "Bagaimanapun, kami adalah teman lama.",
  ui_story_5046_50460101_6_dialog_content = "Sejujurnya, saya terpana dengan betapa mewahnya undangan itu.",
  ui_story_5046_50460101_7_dialog_content = "Tentu saja! Kita tidak bisa melewati protokol hanya karena kita berteman baik.",
  ui_story_5046_50460101_8_dialog_content = "Belum lagi banyak bangsawan dari Lumopolis juga hadir, dan Anda tahu betapa berartinya etiket bagi mereka.",
  ui_story_5046_50460101_9_dialog_content = "Mereka akan membuat keributan jika mereka tahu kamu tidak pernah mendapat undangan dari Shadowlord.",
  ui_story_5046_50460101_10_dialog_content = "Jangan pernah meremehkan kekuatan gosip.",
  ui_story_5046_50460101_11_dialog_content = "Itu benar sekali...",
  ui_story_5046_50460101_12_dialog_content = "Ada desas-desus yang beredar bahwa aku adalah monster dengan banyak kepala, cakar, dan taring.",
  ui_story_5046_50460101_13_dialog_content = "Maksudku, bagaimana mungkin itu mungkin?!",
  ui_story_5046_50460101_14_dialog_content = "Itu praktis fitnah, PlayerName. Apakah Anda tidak mempertimbangkan pilihan hukum?",
  ui_story_5046_50460101_15_dialog_content = "Y-Yah, aku hanya menegur orang-orang itu sedikit dan hanya itu.",
  ui_story_5046_50460101_16_dialog_content = "Mustahil! Anda membiarkan mereka lolos terlalu mudah.",
  ui_story_5046_50460101_17_dialog_content = "Anda harus menghukum mereka atau kebohongan semacam itu hanya akan semakin merusak reputasi Anda.",
  ui_story_5046_50460101_18_dialog_content = "Tidak semua orang menghargai untuk mengenal seseorang melalui kontak langsung melalui gosip.",
  ui_story_5046_50460101_19_dialog_content = "Kau benar…",
  ui_story_5046_50460101_20_dialog_content = "Ngomong-ngomong, di mana Vice Dan Carleen? Apakah mereka tidak bersamamu?",
  ui_story_5046_50460101_21_dialog_content = "Mereka terlalu sibuk dengan urusan mereka sendiri untuk berada di sini hari ini.",
  ui_story_5046_50460101_22_dialog_content = "Mereka memang meminta saya untuk meminta maaf atas nama mereka.",
  ui_story_5046_50460101_23_dialog_content = "Tidak apa-apa, itu terjadi... Saya senang Anda berhasil.",
  ui_story_5046_50460101_24_dialog_content = "Tapi aku penasaran, kenapa mengundangku?",
  ui_story_5046_50460101_25_dialog_content = "Saya tidak ada hubungannya dengan panti asuhan di Umbraton, bukankah canggung bagi saya untuk menghadiri upacaranya?",
  ui_story_5046_50460101_26_dialog_content = "Jangan khawatir.",
  ui_story_5046_50460101_27_dialog_content = "Kami mengirim undangan ke banyak tokoh dan kami menyambut semua yang bersedia datang.",
  ui_story_5046_50460101_28_dialog_content = "Upacara ini bukan sekadar cara untuk menunjukkan rasa terima kasih kepada mereka yang telah membantu kami, tetapi juga agar kami dapat mempromosikan fasilitas tersebut kepada masyarakat dan mendapatkan dana tambahan.",
  ui_story_5046_50460101_29_dialog_content = "Memiliki pandangan ke depan untuk merencanakan ke depan seperti itu terdengar seperti Anda, Bethel!",
  ui_story_5046_50460101_30_dialog_content = "Upacara adalah acara yang sangat penting, jadi untuk memastikannya berjalan lancar, kami mengadakan gladi resik hari ini.",
  ui_story_5046_50460101_31_dialog_content = "Apakah Anda ingin bergabung dan membiasakan diri dengan prosesnya?",
  ui_story_5046_50460101_32_dialog_content = "Tentu, bukan masalah!",
  ui_story_5046_50460101_33_dialog_content = "Ikuti aku, kalau begitu.",
  ui_story_5046_50460101_34_dialog_content = "<color=#e8d9bb>Latihan Upacara Penyelesaian Panti Asuhan Umbraton</color>",
  ui_story_5046_50460101_35_dialog_content = "Keamanan ada di tempat, Nona Bethel.",
  ui_story_5046_50460101_36_dialog_content = "Selamat, terima kasih.",
  ui_story_5046_50460101_37_dialog_content = "Izinkan saya memperkenalkan Anda, PlayerName.",
  ui_story_5046_50460101_38_dialog_content = "Ini adalah Zenas, yang bertanggung jawab atas keamanan latihan dan juga kapten pasukan keamanan.",
  ui_story_5046_50460101_39_dialog_content = "Reputasi Anda menghasilkan Anda, Caelestite.",
  ui_story_5046_50460101_40_dialog_content = "Aku tersanjung.",
  ui_story_5046_50460101_41_dialog_content = "(Keduanya tampaknya berasal dari Lumopolis dengan cara berpakaian mereka dan mungkin tinggi dalam hal berdiri juga.)",
  ui_story_5046_50460101_42_dialog_content = "(Mengapa mereka bekerja keamanan?)",
  ui_story_5046_50460101_43_dialog_content = "Dan ini adalah hakim percobaan Kristen dari Lumo Hall of Justice, yang akan membantu Zenas dengan detail keamanan.",
  ui_story_5046_50460101_44_dialog_content = "Halo saya Kristen.",
  ui_story_5046_50460101_45_dialog_content = "Hakim Irridon dan yang lain banyak menyebut Anda dan memuji akal dan keberanian Anda.",
  ui_story_5046_50460101_46_dialog_content = "Hehe, kamu menyanjungku ...",
  ui_story_5046_50460101_47_dialog_content = "Pak Hamell!",
  ui_story_5046_50460101_48_dialog_content = "Merindukan Bethel!",
  ui_story_5046_50460101_49_dialog_content = "Saya tidak menyangka Anda akan berada di sini, Tuan Hamell. Ini hanya latihan hari ini.",
  ui_story_5046_50460101_50_dialog_content = "Lagipula aku tidak ada hubungannya, jadi kupikir aku akan datang memeriksanya.",
  ui_story_5046_50460101_51_dialog_content = "Saya sangat menghargai upaya yang Anda dan Shadowlord lakukan untuk membangun kembali panti asuhan, Nona Bethel.",
  ui_story_5046_50460101_52_dialog_content = "Saya harus menjadi orang yang berterima kasih atas nama anak-anak karena memimpin tanggung jawab untuk membangunnya kembali.",
  ui_story_5046_50460101_53_dialog_content = "Oh, maafkan kekasaran saya. Izinkan saya memperkenalkan Anda kepada PlayerName, Caelestite.",
  ui_story_5046_50460101_54_dialog_content = "PlayerName, ini Tuan Hamell, calon direktur panti asuhan dan pedagang barang antik terkenal di Umbraton.",
  ui_story_5046_50460101_55_dialog_content = "Anda terlihat jauh lebih muda secara pribadi, Caelestite, dan sudah begitu berprestasi di usia seperti itu.",
  ui_story_5046_50460101_56_dialog_content = "Roaming Astra di Colossus Anda, sering bekerja dengan Cloudrover Guild yang terkenal.",
  ui_story_5046_50460101_57_dialog_content = "Kamu adalah bakat yang langka!",
  ui_story_5046_50460101_58_dialog_content = "Aku berhasil melakukannya hanya melalui bantuan orang lain.",
  ui_story_5046_50460101_59_dialog_content = "Hubungan juga merupakan bagian penting dari bisnis!",
  ui_story_5046_50460101_60_dialog_content = "Tidak mudah membangun dan memelihara koneksi seperti yang Anda miliki!",
  ui_story_5046_50460101_61_dialog_content = "Aku senang bahkan di usia tuaku, aku bisa bertemu seseorang sepertimu...",
  ui_story_5046_50460101_62_dialog_content = "Anda melebih-lebihkan, Pak. aku hanya manusia biasa...",
  ui_story_5046_50460101_63_dialog_content = "Kabarnya kau cukup kaya.",
  ui_story_5046_50460101_64_dialog_content = "Apa? Di mana Anda mendengar itu?",
  ui_story_5046_50460101_65_dialog_content = "Biaya untuk merawat Colossus sebesar itu pasti sangat besar.",
  ui_story_5046_50460101_66_dialog_content = "Betul, tapi bukan berarti saya kaya...",
  ui_story_5046_50460101_67_dialog_content = "Rendah hati, saya mengerti!",
  ui_story_5046_50460101_68_dialog_content = "Orang kaya yang terhubung dengan baik dan rendah hati seperti Anda sedikit dan jarang di Astra.",
  ui_story_5046_50460101_69_dialog_content = "Mari kita bahkan tidak memunculkan belas kasih!",
  ui_story_5046_50460101_70_dialog_content = "Apakah Anda tertarik untuk mensponsori panti asuhan jangka panjang?",
  ui_story_5046_50460101_71_dialog_content = "Anu…",
  ui_story_5046_50460101_72_dialog_content = "Ehem.",
  ui_story_5046_50460101_73_dialog_content = "Tolong jangan menempatkan tamu kami di tempat, Tn. Hamell.",
  ui_story_5046_50460101_74_dialog_content = "Kemitraan jangka panjang apa pun harus dibangun di atas rasa saling menghormati dan percaya.",
  ui_story_5046_50460101_75_dialog_content = "Oh, ya, benar...",
  ui_story_5046_50460101_76_dialog_content = "Aku melompat pistol.",
  ui_story_5046_50460101_77_dialog_content = "Tidak apa-apa. Aku tahu kau hanya menjaga anak-anak.",
  ui_story_5046_50460101_78_dialog_content = "Bagaimanapun, hari ini hanya latihan, jadi semua orang bisa mengenal satu sama lain.",
  ui_story_5046_50460101_79_dialog_content = "Kita bisa bicara tentang kemitraan nanti.",
  ui_story_5046_50460101_80_dialog_content = "Kau benar.",
  ui_story_5046_50460101_81_dialog_content = "Permisi, saya harus mengurus detail untuk acara resmi.",
  ui_story_5046_50460101_82_dialog_content = "Saya harus pergi, tetapi jangan ragu untuk berbicara di antara Anda sendiri.",
  ui_story_5046_50460101_83_dialog_content = "Bethel pasti punya banyak hal di piringnya.",
  ui_story_5046_50460101_84_dialog_content = "Ngomong-ngomong, aku bertanya-tanya...",
  ui_story_5046_50460101_85_option_content = "Mengapa Lumopolis menangani keamanan untuk acara di Umbraton?",
  ui_story_5046_50460101_86_dialog_content = "Seperti yang Anda lihat, tamu acara ini termasuk bangsawan tinggi dari Lumopolis.",
  ui_story_5046_50460101_87_dialog_content = "Mereka tidak mempercayai tentara bayaran di Umbraton, jadi mereka meminta perlindungan orang-orang mereka sendiri.",
  ui_story_5046_50460101_88_dialog_content = "Dan mengingat kerusuhan baru-baru ini di Umbraton akibat pembakaran, para bangsawan mengambil tindakan pencegahan ekstra.",
  ui_story_5046_50460101_89_dialog_content = "Itu sebabnya Lumopolis mengirim saya dan Nona Kristen untuk menjaga perdamaian di sini.",
  ui_story_5046_50460101_90_dialog_content = "Pembakaran? Kau tahu, aku melihat poster buronan ketika aku datang ke kota.",
  ui_story_5046_50460101_91_dialog_content = "Meskipun terlalu ramai bagi saya untuk mendekat dan melihat detailnya ...",
  ui_story_5046_50460101_92_dialog_content = "Untungnya, kebetulan saya punya salinannya untuk Anda lihat.",
  ui_story_5046_50460101_93_dialog_content = "\"Diinginkan:\"",
  ui_story_5046_50460101_94_dialog_content = "\"Tersangka bersalah melakukan beberapa kali pembakaran di Umbraton, yang mengakibatkan tiga orang tewas dan banyak yang luka-luka.\"",
  ui_story_5046_50460101_95_dialog_content = "\"200.000 hadiah Nightium untuk setiap informasi yang mengarah pada penangkapan.\"",
  ui_story_5046_50460101_96_dialog_content = "\"Sifat Tersangka: Sangat kuat, cepat, dan buas seperti binatang buas.\"",
  ui_story_5046_50460101_97_dialog_content = "\"Tersangka Alias: Dark Slayer.\"",
  ui_story_5046_50460101_98_dialog_content = "200.000 Nightium? Itu banyak! Kalau saja aku bisa menangkap Dark Slayer ini...",
  ui_story_5046_50460101_99_dialog_content = "Tapi moniker itu terdengar cukup mengerikan bagi saya untuk tidak mengambil risiko.",
  ui_story_5046_50460101_100_dialog_content = "Dan gambar di poster terlalu buram untuk digunakan secara praktis...",
  ui_story_5046_50460101_101_dialog_content = "Sayangnya, belum ada yang bisa melihat jelas tersangka.",
  ui_story_5046_50460101_102_dialog_content = "Beberapa warga Umbraton melihat sosok mirip binatang buas meninggalkan tempat kejadian pada pembakaran pertama, tapi hanya itu.",
  ui_story_5046_50460101_103_dialog_content = "Jadi tersangka kemungkinan adalah setengah manusia.",
  ui_story_5046_50460101_104_dialog_content = "Tolong beri tahu Kapten Zenas atau saya jika Anda melihat seseorang yang mirip dengan gambar itu sesegera mungkin.",
  ui_story_5046_50460101_105_dialog_content = "Tersangka sangat brutal, jadi tolong hindari konfrontasi meskipun hadiah uang terdengar menggoda. Lindungi keselamatan Anda sendiri terlebih dahulu.",
  ui_story_5046_50460101_106_dialog_content = "G-mengerti...",
  ui_story_5046_50460101_107_dialog_content = "Ada pertanyaan lain?",
  ui_story_5046_50460101_108_option_content = "Apakah ada kebakaran di panti asuhan tua?",
  ui_story_5046_50460101_109_dialog_content = "Itu secara tidak sengaja dibakar bertahun-tahun yang lalu, membakar bangunan itu ke tanah. Untungnya, tidak ada anak yang terluka.",
  ui_story_5046_50460101_110_dialog_content = "Syukurlah, Shadowlord yang baik hati membuka salah satu rumahnya dan membiarkan anak-anak malang itu tinggal di sana.",
  ui_story_5046_50460101_111_dialog_content = "Dan mereka sudah ada di sana selama ini.",
  ui_story_5046_50460101_112_dialog_content = "Tapi itu bukan solusi jangka panjang, apalagi masih banyak anak tunawisma yang berkeliaran di jalanan.",
  ui_story_5046_50460101_113_dialog_content = "Saya menghasilkan uang dengan menjual barang antik dalam beberapa tahun terakhir, jadi harapan saya untuk membangun kembali panti asuhan dan memberi mereka rumah.",
  ui_story_5046_50460101_114_dialog_content = "Meski kehilangan orang tua, mereka masih bisa tumbuh bersama teman sebaya dan orang-orang yang baik hati.",
  ui_story_5046_50460101_115_dialog_content = "Anda sangat mengagumkan, Tn. Hamell.",
  ui_story_5046_50460101_116_dialog_content = "Anda sangat mulia, Tuan Hamell.",
  ui_story_5046_50460101_117_dialog_content = "Saya hanya mencoba melakukan sedikit yang saya bisa untuk anak-anak.",
  ui_story_5046_50460101_118_dialog_content = "Mari berharap fasilitas baru akan tetap aman dan sehat.",
  ui_story_5046_50460101_119_dialog_content = "Ada pertanyaan lain?",
  ui_story_5046_50460101_120_option_content = "Tidak ada lagi.",
  ui_story_5046_50460101_121_dialog_content = "Sudah larut, Pak. Kita harus mulai berkeliling.",
  ui_story_5046_50460101_122_dialog_content = "Maafkan saya karena menahan Anda dari pekerjaan Anda!",
  ui_story_5046_50460101_123_dialog_content = "Kamu baik-baik saja. Memastikan keamanan para tamu adalah bagian dari tugas kami.",
  ui_story_5046_50460101_124_dialog_content = "<color=#e8d9bb>Dentang-</color>",
  ui_story_5046_50460101_125_dialog_content = "Hm? Tuan Zenas, Anda menjatuhkan sesuatu.",
  ui_story_5046_50460101_126_dialog_content = "(Liontin yang sangat halus, dan ada kuda poni lucu di atasnya juga.)",
  ui_story_5046_50460101_127_dialog_content = "Ini dia.",
  ui_story_5046_50460101_128_dialog_content = "Terima kasih.",
  ui_story_5046_50460101_129_dialog_content = "Sudah larut, nona. Kita harus memulai putaran kita.",
  ui_story_5046_50460101_130_dialog_content = "Ya pak-",
  ui_story_5046_50460101_131_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5046_50460101_132_dialog_content = "Apa yang terjadi?!",
  ui_story_5046_50460101_133_dialog_content = "Api! Api!",
  ui_story_5046_50460101_134_dialog_content = "Bagaimana api bisa muncul begitu saja?",
  ui_story_5046_50460101_135_dialog_content = "Ini adalah hasil karya Dark Slayer jika Anda bertanya kepada saya!",
  ui_story_5046_50460101_136_dialog_content = "Dark Slayer barbar itu ada di sini?!",
  ui_story_5046_50460101_137_dialog_content = "Jangan panik. Sepertinya api mulai di panti asuhan.",
  ui_story_5046_50460101_138_dialog_content = "Mari kita lihat, nona.",
  ui_story_5046_50460101_139_dialog_content = "Siap, Pak!",
  ui_story_5046_50460101_140_dialog_content = "<color=#e8d9bb>Di dekat sini</color>",
  ui_story_5046_50460101_141_dialog_content = "...",
  ui_story_5046_50460201_1_dialog_content = "PlayerName, Tuan Hamell.",
  ui_story_5046_50460201_2_dialog_content = "Tolong tetap di tempat. Penjaga Lumopolis akan segera tiba untuk melindungi Anda.",
  ui_story_5046_50460201_3_dialog_content = "Saya ingin pergi bersama anda! Saya dapat menentukan orang dengan kemampuan psikis saya!",
  ui_story_5046_50460201_4_dialog_content = "Saya juga. Saya ingin tahu bagaimana api mulai!",
  ui_story_5046_50460201_5_dialog_content = "Baiklah. Ini mendesak, jadi tolong ikuti saya dengan cermat. Saya akan melakukan yang terbaik untuk memastikan Anda aman!",
  ui_story_5046_50460201_6_dialog_content = "*Batuk* Ada begitu banyak asap di sini, saya tidak bisa melihat apa-apa. Kita harus padamkan api sekarang...",
  ui_story_5046_50460201_7_dialog_content = "Arus Radial!",
  ui_story_5046_50460201_8_dialog_content = "Tunggu, Kristen!",
  ui_story_5046_50460201_9_dialog_content = "<color=#e8d9bb>DUAR!</color>",
  ui_story_5046_50460201_10_dialog_content = "Awas!",
  ui_story_5046_50460201_11_dialog_content = "Oh tidak! Apakah Anda baik-baik saja, Pak?",
  ui_story_5046_50460201_12_dialog_content = "*Batuk*... Aku baik-baik saja.",
  ui_story_5046_50460201_13_dialog_content = "Api menyebar di sepanjang minyak di tanah. Cairan yang mudah terbakar ini hanya akan mengapung di atas air dan terus menyala, sehingga tidak dapat dipadamkan dengan air.",
  ui_story_5046_50460201_14_dialog_content = "Maaf, Tuan, karena membuat Anda terluka lagi ...",
  ui_story_5046_50460201_15_dialog_content = "Sekarang bukan waktunya untuk membahas itu.",
  ui_story_5046_50460201_16_dialog_content = "PlayerName, silakan gunakan kemampuan psikis Anda untuk memindai orang yang selamat atau bahkan tanda-tanda Pembunuh Kegelapan!",
  ui_story_5046_50460201_17_dialog_content = "Siap!",
  ui_story_5046_50460201_18_option_content = "Force Boost!",
  ui_story_5046_50460201_19_dialog_content = "*Menangis* Tolong...",
  ui_story_5046_50460201_20_dialog_content = "Ada seorang anak yang terjebak di arah ini!",
  ui_story_5046_50460201_21_dialog_content = "...",
  ui_story_5046_50460201_22_dialog_content = "Ibu...",
  ui_story_5046_50460201_23_dialog_content = "*Batuk* Tenggorokanku, sakit...",
  ui_story_5046_50460201_24_dialog_content = "Dia tidak bisa bertahan lebih lama lagi. Kita harus menyelamatkannya!",
  ui_story_5046_50460201_25_dialog_content = "Terlalu banyak asap, PlayerName. Aku tidak bisa melihatmu!",
  ui_story_5046_50460201_26_dialog_content = "Jangan masuk ke sana! Apinya sangat kuat, terlalu berbahaya!",
  ui_story_5046_50460201_27_dialog_content = "Jangan khawatir, aku di sini untuk mengeluarkanmu!",
  ui_story_5046_50460201_28_dialog_content = "Batuk, batuk... Aku di sini!",
  ui_story_5046_50460201_29_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5046_50460201_30_dialog_content = "Oh tidak, rumah mulai runtuh karena kebakaran.",
  ui_story_5046_50460201_31_dialog_content = "Saya harus menemukan jalan keluar, tetapi asap tebal membuatnya tidak mungkin!",
  ui_story_5046_50460201_32_dialog_content = "Aku takut... *Menangis*",
  ui_story_5046_50460201_33_dialog_content = "Tidak apa-apa, kita akan menemukan jalan keluar!",
  ui_story_5046_50460201_34_dialog_content = "<color=#e8d9bb>Menghancurkan!</color>",
  ui_story_5046_50460201_35_dialog_content = "Ruangan itu runtuh—!",
  ui_story_5046_50460201_36_dialog_content = "Arghhh—!",
  ui_story_5046_50460201_37_dialog_content = "Buka matamu, kau belum mati.",
  ui_story_5046_50460201_38_dialog_content = "Siapa itu?",
  ui_story_5046_50460201_39_dialog_content = "Karena Anda masih hidup, bangun dan pergi.",
  ui_story_5046_50460201_40_dialog_content = "Doggy! *Semburan dan batuk*",
  ui_story_5046_50460201_41_dialog_content = "Seekor anjing besar menyelamatkan kami!",
  ui_story_5046_50460201_42_dialog_content = "B-Bung besar...?",
  ui_story_5046_50460201_43_dialog_content = "Saya pikir itu seorang gadis ... meskipun penampilan maskulinnya.",
  ui_story_5046_50460201_44_dialog_content = "Doggy! Batuk, batuk... Seekor anjing! Seekor anjing yang lucu dan lembut!",
  ui_story_5046_50460201_45_dialog_content = "Sama seperti... uhuk, uhuk... jenis yang menyelamatkan orang dalam cerita...",
  ui_story_5046_50460201_46_dialog_content = "Pendiam dan baik hati... uhuk, uhuk... anjing besar!",
  ui_story_5046_50460201_47_dialog_content = "Berapa lama Anda akan terus menyalak? Saya pergi jika Anda ingin terbakar sampai garing.",
  ui_story_5046_50460201_48_dialog_content = "B-Kenapa api tidak membakarmu?",
  ui_story_5046_50460201_49_dialog_content = "Api ini? Mereka tidak bisa menyakitiku.",
  ui_story_5046_50460201_50_dialog_content = "T-Tunggu! Dimana aku pernah melihatmu sebelumnya...",
  ui_story_5046_50460201_51_dialog_content = "K-Kamu, kamu adalah Dark Slayer!",
  ui_story_5046_50460201_52_dialog_content = "Pembunuh Gelap? Anda salah orang.",
  ui_story_5046_50460201_53_dialog_content = "Nama saya adalah Hati.",
  ui_story_5046_50460201_54_dialog_content = "Oh, dan karena kamu terlihat sangat takut padaku, bagaimana kalau melepaskan tanganku?",
  ui_story_5046_50460201_55_dialog_content = "Kamu ada di mana, PlayerName?",
  ui_story_5046_50460201_56_dialog_content = "*Batuk* Aku membawa bantuan, dan api di luar sana hampir padam!",
  ui_story_5046_50460201_57_dialog_content = "Saya pikir ada seseorang dengan PlayerName!",
  ui_story_5046_50460201_58_dialog_content = "Sepertinya... Pembunuh Kegelapan!",
  ui_story_5046_50460201_59_dialog_content = "Pembunuh Kegelapan?!",
  ui_story_5046_50460201_60_dialog_content = "Arson mencurigai Dark Slayer, saya perintahkan Anda untuk segera melepaskan sandera!",
  ui_story_5046_50460201_61_dialog_content = "Seperti yang saya katakan, saya bukan Pembunuh Kegelapan. Nama saya adalah Hati.",
  ui_story_5046_50460201_62_dialog_content = "Dan apa maksudmu dengan sandera?",
  ui_story_5046_50460201_63_dialog_content = "Kami terbuka untuk persyaratan apa pun selama Anda mengizinkan PlayerName pergi!",
  ui_story_5046_50460201_64_dialog_content = "Ketentuan? Suka memperdagangkan satu hal dengan hal lain?",
  ui_story_5046_50460201_65_dialog_content = "Kukira PlayerName sangat berharga bagimu. Apakah kamu PlayerName?",
  ui_story_5046_50460201_66_dialog_content = "Y-Ya, itu aku. Aku akan menjadi sanderamu, biarkan saja gadis itu pergi.",
  ui_story_5046_50460201_67_dialog_content = "Jangan lakukan hal bodoh, Dark Slayer!",
  ui_story_5046_50460201_68_dialog_content = "Lagi dengan itu? Sangat menjengkelkan!",
  ui_story_5046_50460201_69_dialog_content = "Anjing besar itu jahat...",
  ui_story_5046_50460201_70_dialog_content = "Ugh—!",
  ui_story_5046_50460201_71_dialog_content = "Dark Slayer punya PlayerName!",
  ui_story_5046_50460201_72_dialog_content = "Mendekatlah dan aku akan membunuhnya.",
  ui_story_5046_50460201_73_dialog_content = "Karena yang ini sepertinya sangat penting bagimu, izinkan aku menjaganya untuk sementara waktu.",
  ui_story_5046_50460201_74_dialog_content = "Hei, kemana kamu membawaku? Lepaskan saya!",
  ui_story_5046_50460201_75_dialog_content = "Tolong!",
  ui_story_5046_50460201_76_dialog_content = "Hentikan mereka, penjaga!",
  ui_story_5046_50460201_77_dialog_content = "Jangan biarkan Dark Slayer lolos PlayerName!",
  ui_story_5046_50460202_1_dialog_content = "Para penjaga telah kehilangan Dark Slayer.",
  ui_story_5046_50460202_2_dialog_content = "Maaf pak...",
  ui_story_5046_50460202_3_dialog_content = "Itu bukan salahmu. The Dark Slayer dapat mengendalikan api, yang memberinya keuntungan.",
  ui_story_5046_50460202_4_dialog_content = "Juga, dia bergerak jauh lebih cepat daripada orang biasa.",
  ui_story_5046_50460202_5_dialog_content = "Tidak mengherankan jika Anda tidak bisa mengikutinya.",
  ui_story_5046_50460202_6_dialog_content = "Nah, rencana darurat Anda berguna.",
  ui_story_5046_50460202_7_dialog_content = "Memang masih semrawut, tapi setidaknya para tamu sudah dievakuasi dengan selamat.",
  ui_story_5046_50460202_8_dialog_content = "Tapi bisakah Anda menjelaskan kepada saya caranya PlayerName disandera oleh Dark Slayer?",
  ui_story_5046_50460202_9_dialog_content = "Maaf, kami gagal menjalankan tugas kami.",
  ui_story_5046_50460202_10_dialog_content = "Tidak, itu salahku PlayerName diculik...",
  ui_story_5046_50460202_11_dialog_content = "Kami telah mengidentifikasi tersangkanya, Nona Bethel.",
  ui_story_5046_50460202_12_dialog_content = "Baiklah, bagus sekali.",
  ui_story_5046_50460202_13_dialog_content = "\"Hati, perempuan, usia 18 tahun, tempat lahir tidak diketahui.\"",
  ui_story_5046_50460202_14_dialog_content = "\"Tinggal sebentar di Panti Asuhan Umbraton. Shadowlord membawanya masuk setelah dia menyebabkan kebakaran yang membakar panti asuhan.\"",
  ui_story_5046_50460202_15_dialog_content = "(Ayah...? Itu ide Ayah?)",
  ui_story_5046_50460202_16_dialog_content = "Menyebabkan kebakaran yang membakar panti asuhan? Kedengarannya seperti pelaku berulang.",
  ui_story_5046_50460202_17_dialog_content = "\"Hati berusia 18 tahun dua bulan lalu dan meninggalkan perkebunan setelah evaluasi yang sukses.\"",
  ui_story_5046_50460202_18_dialog_content = "(Lebih baik memberi tahu Ayah tentang ini.)",
  ui_story_5046_50460202_19_dialog_content = "Bagaimana bisa seorang pembakar terkenal seperti itu dibebaskan...?",
  ui_story_5046_50460202_20_dialog_content = "Bagaimanapun, saya akan menyampaikan ini ke Shadowlord dan memberi tahu setiap faksi di Umbraton untuk mencari PlayerNamekeberadaannya.",
  ui_story_5046_50460202_21_dialog_content = "Tapi itu akan membuat publik ...",
  ui_story_5046_50460202_22_dialog_content = "Saya prihatin dengan reaksi di panti asuhan ketika tersiar kabar bahwa seorang VIP diculik selama latihan.",
  ui_story_5046_50460202_23_dialog_content = "Tapi kita bahkan tidak tahu apakah PlayerName masih hidup sekarang!",
  ui_story_5046_50460202_24_dialog_content = "Huh...",
  ui_story_5046_50460202_25_dialog_content = "Merindukan Bethel, Tuan Hamell.",
  ui_story_5046_50460202_26_dialog_content = "Jika Anda bersedia mempercayai saya, tolong pertahankan PlayerNamepenculikan tersembunyi untuk saat ini.",
  ui_story_5046_50460202_27_dialog_content = "Jika kami mempublikasikannya, Dark Slayer mungkin akan mengancam PlayerNamehidup.",
  ui_story_5046_50460202_28_dialog_content = "Saya akan menemukan Dark Slayer dan gratis PlayerName secepat mungkin.",
  ui_story_5046_50460202_29_dialog_content = "...",
  ui_story_5046_50460202_30_dialog_content = "Maafkan aku karena tidak percaya padamu.",
  ui_story_5046_50460202_31_dialog_content = "Jika Anda tidak dapat mempercayai kemampuan kami...",
  ui_story_5046_50460202_32_dialog_content = "Saya bersedia menjamin instruktur saya, Knight Zenas, atas nama Ivan.",
  ui_story_5046_50460202_33_dialog_content = "Anda tidak perlu melakukan ini, nona...",
  ui_story_5046_50460202_34_dialog_content = "Tolong beri kami kesempatan lagi untuk menebus kesalahan kami, Nona Bethel.",
  ui_story_5046_50460202_35_dialog_content = "Saya pernah mendengar cerita tentang Knight Zenas.",
  ui_story_5046_50460202_36_dialog_content = "Sangat mengesankan untuk mencakar jalannya dari keluarga bangsawan yang turun-naik ke tempatnya sekarang.",
  ui_story_5046_50460202_37_dialog_content = "Baiklah, mengingat keluarga Ivan ada di belakangmu, aku akan mempercayaimu untuk saat ini.",
  ui_story_5046_50460202_38_dialog_content = "Namun ketahuilah bahwa Shadowlord akan mendengar tentang ini pada akhirnya.",
  ui_story_5046_50460202_39_dialog_content = "Anda memiliki tiga hari.",
  ui_story_5046_50460202_40_dialog_content = "Saya ingin PlayerName pada upacara, tanpa cedera, tiga hari kemudian.",
  ui_story_5046_50460202_41_dialog_content = "Jika Anda tidak bisa melakukannya, saya akan menanganinya dengan cara Umbraton.",
  ui_story_5046_50460202_42_dialog_content = "Terima kasih saya.",
  ui_story_5046_50460202_43_dialog_content = "Milik saya juga.",
  ui_story_5046_50460202_44_dialog_content = "Oke, begitulah yang akan kita tangani PlayerNamepenculikan untuk saat ini.",
  ui_story_5046_50460202_45_dialog_content = "Sementara itu, kami membutuhkan bantuan Anda untuk menenangkan para tamu, Tn. Hamell.",
  ui_story_5046_50460202_46_dialog_content = "Tentu saja, tentu saja!",
  ui_story_5046_50460202_47_dialog_content = "Lewat sini, Tuan Hamell.",
  ui_story_5046_50460202_48_dialog_content = "Tolong izinkan saya membantu Anda melacak Dark Slayer, Pak.",
  ui_story_5046_50460202_49_dialog_content = "Saya telah menghabiskan banyak upaya mempelajari Luminatics dan keterampilan tempur selama bertahun-tahun supaya saya bisa melindungi Anda suatu hari nanti.",
  ui_story_5046_50460202_50_dialog_content = "Tolong beri saya kesempatan!",
  ui_story_5046_50460202_51_dialog_content = "Tidak.",
  ui_story_5046_50460202_52_dialog_content = "Apakah Anda tidak mempercayai saya karena apa yang terjadi dalam kebakaran itu?",
  ui_story_5046_50460202_53_dialog_content = "Itu semua salah ku. Dan Anda harus menyelamatkan saya dari api lain.",
  ui_story_5046_50460202_54_dialog_content = "Oh, kenapa aku selalu menempatkanmu dalam kesulitan...?",
  ui_story_5046_50460202_55_dialog_content = "Berhentilah menyalahkan dirimu sendiri, nona.",
  ui_story_5046_50460202_56_dialog_content = "Aku akan selalu menyelamatkanmu dari kesalahan, di masa lalu, sekarang, dan masa depan.",
  ui_story_5046_50460202_57_dialog_content = "Jadi kenapa...",
  ui_story_5046_50460202_58_dialog_content = "Anda mampu membedakan petunjuk penting dari laporan kejahatan dan dokumen terkait.",
  ui_story_5046_50460202_59_dialog_content = "Jadi dibandingkan mengejar pelakunya di lapangan, menurut saya menyelidiki TKP dan menyelidiki dokumen lebih cocok untuk Anda.",
  ui_story_5046_50460202_60_dialog_content = "Saya lebih suka tidak melihat Anda memaksakan diri untuk melakukan sesuatu yang tidak Anda kuasai.",
  ui_story_5046_50460202_61_dialog_content = "Saya akan menyebutnya sesuatu yang tidak sering saya lakukan daripada sesuatu yang tidak saya kuasai...",
  ui_story_5046_50460202_62_dialog_content = "Gadisku?",
  ui_story_5046_50460202_63_dialog_content = "T-Tidak ada.",
  ui_story_5046_50460202_64_dialog_content = "Jadi tolong tetap di belakang dan periksa lokasi pembakaran. Saya yakin Anda akan menemukan petunjuk yang berharga.",
  ui_story_5046_50460202_65_dialog_content = "OK saya mengerti!",
  ui_story_5046_50460202_66_dialog_content = "Saya tidak akan meninggalkan kebutuhan bisnis yang terlewat!",
  ui_story_5046_50460202_67_dialog_content = "Ayah, itulah yang terjadi.",
  ui_story_5046_50460202_68_dialog_content = "Apa yang harus kita lakukan selanjutnya?",
  ui_story_5046_50460202_69_dialog_content = "Hmm…",
  ui_story_5046_50460202_70_dialog_content = "Bukan apa-apa sekarang.",
  ui_story_5046_50460202_71_dialog_content = "Tapi bagaimana dengan PlayerName...",
  ui_story_5046_50460202_72_dialog_content = "Jangan khawatir, seseorang akan mengawasi PlayerName.",
  ui_story_5046_50460202_73_dialog_content = "Baik tuan ku.",
  ui_story_5046_50460301_1_dialog_content = "<color=#e8d9bb>Firefly Bar di Umbraton</color>",
  ui_story_5046_50460301_2_dialog_content = "Kamu kembali.",
  ui_story_5046_50460301_3_dialog_content = "(Kemana Dark Slayer membawaku?)",
  ui_story_5046_50460301_4_dialog_content = "Saya pikir Anda pergi ke latihan hari ini? Dan ada apa dengan kucing liar yang kamu bawa pulang?",
  ui_story_5046_50460301_5_dialog_content = "(Sepertinya saya di bar. Saya mungkin harus berpura-pura masih di luar dan mendengarkan apa yang mereka katakan...)",
  ui_story_5046_50460301_6_dialog_content = "Itu cocklebur yang menempel padamu.",
  ui_story_5046_50460301_7_dialog_content = "Haha, maksudmu benih dengan duri tajam yang menempel di bajumu seperti onak?",
  ui_story_5046_50460301_8_dialog_content = "Ya. Ibu biasa membawa mereka ke dalam rumah secara tidak sengaja, dan saya selalu mengambilnya darinya.",
  ui_story_5046_50460301_9_dialog_content = "Oh, apakah Anda mendapatkan barangnya?",
  ui_story_5046_50460301_10_dialog_content = "Tidak. Cocklebur menahan saya, dan kemudian lebih banyak orang muncul, jadi saya tidak bisa bergerak.",
  ui_story_5046_50460301_11_dialog_content = "Cocklebur tampaknya merupakan sosok yang sangat penting. Mereka khawatir.",
  ui_story_5046_50460301_12_dialog_content = "Hei, bukankah ini Caelestite?",
  ui_story_5046_50460301_13_dialog_content = "Tempat apa itu?",
  ui_story_5046_50460301_14_dialog_content = "Anda tidak tahu tentang Caelestite? Oh iya, aku lupa kamu baru dua bulan di dunia.",
  ui_story_5046_50460301_15_dialog_content = "Apakah Caelestites suka berpura-pura sedang tidur?",
  ui_story_5046_50460301_16_dialog_content = "(Apa? Dia tahu aku sedang menguping?!)",
  ui_story_5046_50460301_17_dialog_content = "Aku tidak tahu. Tidak ada tabloid di Umbraton yang menyebutkan hal itu.",
  ui_story_5046_50460301_18_dialog_content = "Hei, bangun.",
  ui_story_5046_50460301_19_dialog_content = "(Dia mengguncang saya dengan kekuatan yang cukup untuk mematahkan tulang saya!)",
  ui_story_5046_50460301_20_dialog_content = "(Saya harus berpura-pura baru saja bangun.)",
  ui_story_5046_50460301_21_dialog_content = "Ugh...",
  ui_story_5046_50460301_22_dialog_content = "Di mana aku?",
  ui_story_5046_50460301_23_dialog_content = "Kenapa kau berpura-pura seperti baru bangun tidur? Anda mengintip di sekitar bar ketika kami masuk.",
  ui_story_5046_50460301_24_dialog_content = "Eh, haha, apa yang kamu bicarakan? Aku jelas baru sadar kembali.",
  ui_story_5046_50460301_25_dialog_content = "Orang baik tidak akan berbohong.",
  ui_story_5046_50460301_26_dialog_content = "Baiklah, jangan menakut-nakuti PlayerName.",
  ui_story_5046_50460301_27_dialog_content = "Bagaimana Anda tahu nama saya?",
  ui_story_5046_50460301_28_dialog_content = "Anda populer di seluruh negeri. Bukan hal yang aneh untuk mengetahui siapa Anda.",
  ui_story_5046_50460301_29_dialog_content = "Yah, itu benar.",
  ui_story_5046_50460301_30_dialog_content = "Jangan gugup. Kami tidak punya niat buruk.",
  ui_story_5046_50460301_31_dialog_content = "Saya Grimme, pelayan Bar Firefly ini.",
  ui_story_5046_50460301_32_dialog_content = "Dia Hati, saat ini bekerja untuk bar.",
  ui_story_5046_50460301_33_dialog_content = "Untuk apa aku baginya... Kau bisa memanggilku walinya.",
  ui_story_5046_50460301_34_dialog_content = "Dia berada dalam perawatanku sejak dia meninggalkan Shadowlord.",
  ui_story_5046_50460301_35_dialog_content = "Jangan tertipu oleh penampilannya. Dia mungkin terlihat dua puluh sesuatu tetapi sebenarnya baru berusia delapan belas tahun!",
  ui_story_5046_50460301_36_dialog_content = "Dan dia baru berada di dunia nyata selama dua bulan, jadi pikirannya lebih mirip dengan anak berusia tujuh atau delapan tahun.",
  ui_story_5046_50460301_37_dialog_content = "Saya tidak yakin mengapa Hati membawamu kembali, tapi percayalah, dia anak yang baik.",
  ui_story_5046_50460301_38_dialog_content = "Kamu pikir menculik seseorang itu baik...?",
  ui_story_5046_50460301_39_dialog_content = "Dia hanya blak-blakan dan lugas tetapi tidak bermaksud jahat.",
  ui_story_5046_50460301_40_dialog_content = "Meskipun dia yang harus disalahkan untuk ini, jadi aku akan membuatnya meminta maaf padamu.",
  ui_story_5046_50460301_41_dialog_content = "Sekarang mengapa saya harus meminta maaf kepada orang itu?",
  ui_story_5046_50460301_42_dialog_content = "Mereka semua memperlakukanku seperti orang jahat, dan terus memanggilku Pembunuh Kegelapan...",
  ui_story_5046_50460301_43_dialog_content = "Terlepas dari apa yang dikatakan kepada Anda, Anda salah menculik siapa pun.",
  ui_story_5046_50460301_44_dialog_content = "Anda harus meminta maaf ketika Anda melakukan sesuatu yang salah.",
  ui_story_5046_50460301_45_dialog_content = "Cih...",
  ui_story_5046_50460301_46_dialog_content = "Maaf.",
  ui_story_5046_50460301_47_dialog_content = "(Aku tidak menyangka seseorang yang begitu galak akan mendengarkan Grimme...)",
  ui_story_5046_50460301_48_dialog_content = "Seharusnya aku tidak melakukannya, PlayerName.",
  ui_story_5046_50460301_49_dialog_content = "(Kedengarannya tulus, dan dia sebenarnya tidak menyakitiku...)",
  ui_story_5046_50460301_50_dialog_content = "T-Tentu, mengingat betapa tulusnya kamu, aku memaafkanmu.",
  ui_story_5046_50460301_51_dialog_content = "Kemudian kalian berdua berjabat tangan dan kita mulai lagi dari awal.",
  ui_story_5046_50460301_52_dialog_content = "...",
  ui_story_5046_50460301_53_dialog_content = "...",
  ui_story_5046_50460301_54_dialog_content = "Haha, kalian berdua bertingkah sama saat berselisih.",
  ui_story_5046_50460301_55_dialog_content = "Jangan samakan aku dengan dia...",
  ui_story_5046_50460301_56_dialog_content = "Oh, saya mendengar Caelestites memiliki kemampuan psikis dan dapat melihat jauh ke dalam ingatan orang lain.",
  ui_story_5046_50460301_57_dialog_content = "Mungkin PlayerName dapat membantu Anda mengingat apa yang terjadi dengan ibu Anda.",
  ui_story_5046_50460301_58_dialog_content = "(Hati tampak sangat muram ketika ibunya disebutkan.)",
  ui_story_5046_50460301_59_dialog_content = "Bukankah kau ingin tahu apa yang terjadi, Hati?",
  ui_story_5046_50460301_60_dialog_content = "Anda pikir orang ini dapat membantu?",
  ui_story_5046_50460301_61_dialog_content = "Apakah Anda memandang rendah saya? Dan mengapa saya harus melakukan itu?",
  ui_story_5046_50460301_62_dialog_content = "Hmm, sepertinya kita mengalami kebingungan.",
  ui_story_5046_50460301_63_dialog_content = "Lalu bagaimana dengan ini? Jika saya membantu Anda dengan kekuatan saya, Anda harus membawa saya kembali.",
  ui_story_5046_50460301_64_dialog_content = "Juga, Hati harus menyerahkan diri untuk semua kejahatan yang dia lakukan!",
  ui_story_5046_50460301_65_dialog_content = "Itu masuk akal. Kita bisa pergi dengan itu.",
  ui_story_5046_50460301_66_dialog_content = "Tetapi Hati tidak melakukan semua hal itu, saya bisa membuktikannya.",
  ui_story_5046_50460301_67_dialog_content = "Jika Anda tertarik untuk memecahkan kasus, Anda dapat mengungkap pelakunya Hati.",
  ui_story_5046_50460301_68_dialog_content = "Bagaimana itu untuk tawar-menawar untuk bantuan Anda?",
  ui_story_5046_50460301_69_dialog_content = "Itu kesepakatan!",
  ui_story_5046_50460301_70_dialog_content = "...",
  ui_story_5046_50460301_71_dialog_content = "Jika Anda benar-benar dapat memulihkan ingatan itu untuk saya ...",
  ui_story_5046_50460301_72_dialog_content = "Saya tidak keberatan Anda menyerahkan saya untuk hadiah 200.000 Nightium.",
  ui_story_5046_50460301_73_dialog_content = "Tenang, jika Anda tidak melakukannya, saya tidak akan menukar Anda dengan uang itu.",
  ui_story_5046_50460301_74_dialog_content = "Meskipun 200.000 banyak, saya tidak akan pernah melakukannya karena keserakahan.",
  ui_story_5046_50460301_75_dialog_content = "Itu tidak penting bagi saya.",
  ui_story_5046_50460301_76_dialog_content = "B-Baiklah, kalau begitu bantu aku mencari tahu apa yang harus dilakukan.",
  ui_story_5046_50460301_77_dialog_content = "Anda harus sedetail mungkin dengan ceritanya agar saya dapat memaksimalkan hasilnya.",
  ui_story_5046_50460301_78_dialog_content = "Saya ingin menemukan ibu saya.",
  ui_story_5046_50460301_79_dialog_content = "Saya tinggal bersamanya ketika saya masih kecil. Dia tidak baik atau buruk bagiku.",
  ui_story_5046_50460301_80_dialog_content = "Hingga suatu hari, kami berpisah karena alasan yang tidak diketahui.",
  ui_story_5046_50460301_81_dialog_content = "Hal berikutnya yang saya tahu, saya berada di panti asuhan.",
  ui_story_5046_50460301_82_dialog_content = "Jadi maksudmu ada bagian yang hilang dalam ingatanmu.",
  ui_story_5046_50460301_83_dialog_content = "Jika kita bisa memulihkannya, kita bisa menemukan ibumu.",
  ui_story_5046_50460301_84_dialog_content = "Benar.",
  ui_story_5046_50460301_85_dialog_content = "Apakah hanya itu yang harus Anda lakukan?",
  ui_story_5046_50460301_86_dialog_content = "Ya.",
  ui_story_5046_50460301_87_dialog_content = "Oke. Saya bisa mengerti Anda tidak percaya saya atau kemampuan psikis saya.",
  ui_story_5046_50460301_88_dialog_content = "Tapi saya akan mencoba yang terbaik untuk melakukan apa yang saya janjikan.",
  ui_story_5046_50460301_89_dialog_content = "...",
  ui_story_5046_50460301_90_dialog_content = "Maaf, PlayerName, anak itu baru mengenal dunia dan tidak akan terbuka dengan mudah.",
  ui_story_5046_50460301_91_dialog_content = "Tidak apa-apa. Saya hanya berharap Anda akan melakukan apa yang dijanjikan dan membiarkan saya pergi sesudahnya.",
  ui_story_5046_50460301_92_dialog_content = "Hati, Saya ingin Anda fokus mengingat hal terakhir yang Anda lihat sebelum ingatan itu terputus.",
  ui_story_5046_50460301_93_dialog_content = "Beri tahu saya jika Anda sudah siap.",
  ui_story_5046_50460301_94_dialog_content = "Aku siap.",
  ui_story_5046_50460301_95_dialog_content = "Ambil napas dalam-dalam, Hati, dan santai.",
  ui_story_5046_50460301_96_dialog_content = "Mari mulai.",
  ui_story_5046_50460301_97_option_content = "Force Boost!",
  ui_story_5046_50460301_98_dialog_content = "...",
  ui_story_5046_50460301_99_dialog_content = "(Di mana saya? Sepertinya rumah biasa.)",
  ui_story_5046_50460301_100_dialog_content = "(Ini dimana Hati hidup?)",
  ui_story_5046_50460301_101_dialog_content = "(PlayerName?)",
  ui_story_5046_50460301_102_dialog_content = "(Anda dapat melihat ke dalam ingatan saya.)",
  ui_story_5046_50460301_103_dialog_content = "(Sekarang kamu percaya padaku?)",
  ui_story_5046_50460301_104_dialog_content = "<color=#e8d9bb>Pitter derai...</color>",
  ui_story_5046_50460301_105_dialog_content = "(Saya mendengar langkah kaki dan mereka semakin dekat.)",
  ui_story_5046_50460301_106_dialog_content = "Di mana Anda lari ke saat ini, Hati?",
  ui_story_5046_50460301_107_dialog_content = "(Siapa ini?)",
  ui_story_5046_50460301_108_dialog_content = "(Mama...)",
  ui_story_5046_50460301_109_dialog_content = "Huh...",
  ui_story_5046_50460301_110_dialog_content = "Semakin sulit untuk mengontrol kekuatan anak itu, dan aku khawatir...",
  ui_story_5046_50460301_111_dialog_content = "Tidak hanya itu, dia mulai merindukan dunia luar.",
  ui_story_5046_50460301_112_dialog_content = "Tapi aku tidak boleh membiarkan dia keluar...",
  ui_story_5046_50460301_113_dialog_content = "(Mengapa dia tidak membiarkan Hati keluar?)",
  ui_story_5046_50460301_114_dialog_content = "(Karena dia takut akan kekuatanku, takut akan... apiku.)",
  ui_story_5046_50460301_115_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5046_50460301_116_dialog_content = "Groar!",
  ui_story_5046_50460301_117_dialog_content = "(Whoa—!)",
  ui_story_5046_50460301_118_dialog_content = "(Apakah itu anjing atau serigala? Besar sekali!!!)",
  ui_story_5046_50460301_119_dialog_content = "(Dan agak mirip Hati...)",
  ui_story_5046_50460301_120_dialog_content = "(Ini iblis batin saya, perwujudan dari ketakutan dan kebencian terhadap kekuatan saya sendiri.)",
  ui_story_5046_50460301_121_dialog_content = "(Itu menjaga ingatan yang hilang dan tidak membiarkanku mendekat.)",
  ui_story_5046_50460301_122_dialog_content = "(Urgh—! Kepalaku sakit!)",
  ui_story_5046_50460301_123_dialog_content = "(Ada apa? Kamu tidak terlihat sehat.)",
  ui_story_5046_50460301_124_dialog_content = "Kamu membenciku...? Tapi aku... kau...",
  ui_story_5046_50460301_125_dialog_content = "(Rasanya tidak benar. Saya harus mengakhiri sesi ini di sini!)",
  ui_story_5046_50460301_126_dialog_content = "Anda bisa melihat ingatan saya, PlayerName, dan bahkan setan batinku...",
  ui_story_5046_50460301_127_dialog_content = "Kekuatan Caelestite benar-benar luar biasa.",
  ui_story_5046_50460301_128_dialog_content = "Kami membuat kemajuan dengan kemampuan psikis Caelestite, begitu.",
  ui_story_5046_50460301_129_dialog_content = "Indah sekali, Hati.",
  ui_story_5046_50460301_130_dialog_content = "Hati menjadi sangat emosional ketika setan batin muncul, jadi saya mengakhiri sesi.",
  ui_story_5046_50460301_131_dialog_content = "Kami tidak mendapatkan apa-apa lagi dari itu.",
  ui_story_5046_50460301_132_dialog_content = "Semakin banyak Anda tahu, semakin mudah bagi Anda untuk membantu saya mengingat, bukan?",
  ui_story_5046_50460301_133_dialog_content = "Hah?",
  ui_story_5046_50460301_134_dialog_content = "Y-Ya, itu benar...",
  ui_story_5046_50460301_135_dialog_content = "Jadi jika saya memberi tahu Anda lebih banyak, dapatkah Anda menggunakan kekuatan itu lagi?",
  ui_story_5046_50460301_136_dialog_content = "Ya saya bisa...",
  ui_story_5046_50460301_137_dialog_content = "Tapi kau harus melepaskanku seperti yang kau janjikan.",
  ui_story_5046_50460301_138_dialog_content = "Sepakat.",
  ui_story_5046_50460401_1_dialog_content = "Ini adalah laporan tentang kebakaran panti asuhan untuk Anda teliti, Hakim Kristen.",
  ui_story_5046_50460401_2_dialog_content = "Terima kasih. Saya hanya magang sekarang, jadi panggil saja saya Kristen.",
  ui_story_5046_50460401_3_dialog_content = "Sumbernya adalah bahan bakar yang mudah terbakar, dan disimpan di gudang bersama sisa bahan konstruksi lainnya.",
  ui_story_5046_50460401_4_dialog_content = "Semua orang terlalu sibuk dengan upacara untuk memperhatikan bahan bakar ekstra di gudang.",
  ui_story_5046_50460401_5_dialog_content = "Bahan bakarnya identik dengan yang ditemukan di lokasi pembakaran dalam dua bulan terakhir, jadi orang yang sama harus bertanggung jawab.",
  ui_story_5046_50460401_6_dialog_content = "Ya, itu kesimpulan yang logis.",
  ui_story_5046_50460401_7_dialog_content = "Tapi tidak pernah ada penculikan dalam kasus-kasus sebelumnya, dan Caelestite tertangkap kali ini...",
  ui_story_5046_50460401_8_dialog_content = "Itu sepertinya tidak sesuai dengan polanya. Dan apa motif tersangka?",
  ui_story_5046_50460401_9_dialog_content = "Menurut laporan saksi mata, tersangka adalah seorang demi-human bernama Aurorian Hati.",
  ui_story_5046_50460401_10_dialog_content = "Hati telah tinggal di rumah Shadowlord sampai dua bulan yang lalu. Ini berkasnya.",
  ui_story_5046_50460401_11_dialog_content = "Hmm…",
  ui_story_5046_50460401_12_dialog_content = "“Menurut saksi mata, Hati melepaskan api Lumina besar-besaran pada malam kebakaran panti asuhan dan menyebabkan kobaran api yang besar.\"",
  ui_story_5046_50460401_13_dialog_content = "Semua petunjuk saat ini menunjuk ke nama demi-human Hati.",
  ui_story_5046_50460401_14_dialog_content = "Dan semua pembakaran terjadi setelah dia meninggalkan rumah Shadowlord. Namun, apa motifnya?",
  ui_story_5046_50460401_15_dialog_content = "Oh, dan gadis kecil yang baru saja kita selamatkan...",
  ui_story_5046_50460401_16_dialog_content = "Kami menempatkannya di asrama panti asuhan di bawah pengawasan pengasuh.",
  ui_story_5046_50460401_17_dialog_content = "Biarkan aku pergi bertanya padanya apa yang terjadi.",
  ui_story_5046_50460401_18_dialog_content = "Halo saya Kristen, seorang hakim percobaan dari Lumopolis.",
  ui_story_5046_50460401_19_dialog_content = "Saya ingin bertanya kepada anak ini tentang api.",
  ui_story_5046_50460401_20_dialog_content = "Seorang wanita bangsawan dari Lumopolis, begitu. Saya tidak dapat menolak permintaan Anda, tetapi ketahuilah bahwa anak itu akhirnya tenang beberapa saat yang lalu.",
  ui_story_5046_50460401_21_dialog_content = "Anda harus membuatnya cepat, karena saya harus meminta Anda pergi jika anak itu membuat ulah lagi.",
  ui_story_5046_50460401_22_dialog_content = "Terima kasih atas pemikirannya. Saya akan menyelesaikannya secepat mungkin.",
  ui_story_5046_50460401_23_dialog_content = "Halo, si kecil.",
  ui_story_5046_50460401_24_dialog_content = "Hei, kau wanita dari sebelumnya!",
  ui_story_5046_50460401_25_dialog_content = "Apakah anjing besar dan pria lembut yang menyelamatkanku juga ada di sini?",
  ui_story_5046_50460401_26_dialog_content = "Oh, mereka tidak ada di sini. Apakah Anda tahu keduanya?",
  ui_story_5046_50460401_27_dialog_content = "Tidak. Tapi yang lembut melindungiku dari api jadi dia orang yang baik!",
  ui_story_5046_50460401_28_dialog_content = "Dan ketika balok jatuh, anjing besar itu muncul dan menyelamatkan kami!",
  ui_story_5046_50460401_29_dialog_content = "(Hati menyelamatkan mereka?)",
  ui_story_5046_50460401_30_dialog_content = "Bisakah Anda memberi tahu saya mengapa Anda ada di sana?",
  ui_story_5046_50460401_31_dialog_content = "Menangis...",
  ui_story_5046_50460401_32_dialog_content = "Ada apa?",
  ui_story_5046_50460401_33_dialog_content = "Apakah kamu mau permen, si kecil?",
  ui_story_5046_50460401_34_dialog_content = "Ya!",
  ui_story_5046_50460401_35_dialog_content = "*Mengunyah* Jadi, aku sedang bermain petak umpet dan bersembunyi di dalam rumah itu.",
  ui_story_5046_50460401_36_dialog_content = "Ada banyak tong di dalamnya dan sebuah kotak kecil yang aneh.",
  ui_story_5046_50460401_37_dialog_content = "Kotak kecil yang aneh?",
  ui_story_5046_50460401_38_dialog_content = "Saya menyenggolnya secara tidak sengaja ke tanah, dan mulai terbakar!",
  ui_story_5046_50460401_39_dialog_content = "Saya mencoba lari, tetapi ada api di sekeliling, itu menakutkan.",
  ui_story_5046_50460401_40_dialog_content = "Boo-hoo... Aku tidak bermaksud membakar rumah...",
  ui_story_5046_50460401_41_dialog_content = "Wah!",
  ui_story_5046_50460401_42_dialog_content = "Api itu sangat menakutkan!",
  ui_story_5046_50460401_43_dialog_content = "Baiklah, kau membuatnya menangis lagi. Waktu habis, Anda harus pergi sekarang.",
  ui_story_5046_50460401_44_dialog_content = "Maaf... Sekarang, si kecil, lain kali jangan pergi ke tempat asing.",
  ui_story_5046_50460401_45_dialog_content = "Boo-hoo... aku mengerti...",
  ui_story_5046_50460401_46_dialog_content = "<color=#e8d9bb>Firefly Bar di Umbraton</color>",
  ui_story_5046_50460401_47_dialog_content = "Tidak, masih tidak ingat ...",
  ui_story_5046_50460401_48_dialog_content = "Bahkan dengan semua detailnya, kekuatanmu masih tidak bisa memulihkan ingatan yang hilang untukku?",
  ui_story_5046_50460401_49_dialog_content = "Maaf aku tidak bisa membantu...",
  ui_story_5046_50460401_50_dialog_content = "Anda sangat baik untuk tidak menyalahkannya karena menculik Anda dan bahkan mencoba membantunya dengan kemampuan psikis Anda.",
  ui_story_5046_50460401_51_dialog_content = "Harus ada cara lain!",
  ui_story_5046_50460401_52_dialog_content = "Liontin! Ya, liontin itu!",
  ui_story_5046_50460401_53_dialog_content = "Liontin itu?",
  ui_story_5046_50460401_54_dialog_content = "Saya menculiknya untuk menukar liontin itu dengan pria bertopeng itu.",
  ui_story_5046_50460401_55_dialog_content = "Liontin itu sangat berarti bagiku, sama seperti kamu sangat berarti bagi pria bertopeng itu.",
  ui_story_5046_50460401_56_dialog_content = "Ini perdagangan yang adil.",
  ui_story_5046_50460401_57_dialog_content = "Tukarkan aku dengan liontin? Betapa kasarnya Anda mengusulkan itu!",
  ui_story_5046_50460401_58_dialog_content = "Tidak ada pengetahuan sosial sama sekali!",
  ui_story_5046_50460401_59_dialog_content = "Apa kau tidak punya sesuatu untuk dikatakan sebagai walinya, Grimme?",
  ui_story_5046_50460401_60_dialog_content = "Itu blak-blakan, tapi saya tidak melihat ada yang salah dengan apa yang dia katakan.",
  ui_story_5046_50460401_61_dialog_content = "Anda dapat kembali, dan Hati mendapatkan apa yang diinginkannya dengan melakukan perdagangan.",
  ui_story_5046_50460401_62_dialog_content = "Bukankah itu masuk akal?",
  ui_story_5046_50460401_63_dialog_content = "I-Itu masuk akal...",
  ui_story_5046_50460401_64_dialog_content = "Tunggu sebentar, bukankah kamu berjanji akan melepaskanku jika aku membantu?",
  ui_story_5046_50460401_65_dialog_content = "Mengapa saya menjadi alat tawar-menawar sekarang ?! Anda sedang welas asih!",
  ui_story_5046_50460401_66_dialog_content = "Tetapi Hati tidak mengembalikan ingatannya.",
  ui_story_5046_50460401_67_dialog_content = "Orang-orang di Umbraton semuanya licik, begitu.",
  ui_story_5046_50460401_68_dialog_content = "(Rasanya tidak enak diperlakukan sebagai chip, meski aku tidak terluka sebaliknya...)",
  ui_story_5046_50460401_69_dialog_content = "(Mungkin saya bisa menyelinap keluar saat mereka tidak melihat, temukan Bethel dan beri tahu dia bahwa ...)",
  ui_story_5046_50460401_70_dialog_content = "Kita hanya perlu mencari cara untuk membuat kesepakatan dengan pria bertopeng itu.",
  ui_story_5046_50460401_71_dialog_content = "Ada poster buronanmu di seluruh kota, Hati. Jika Anda menunjukkan diri, Anda akan ditangkap sebelum sampai ke meja perundingan.",
  ui_story_5046_50460401_72_dialog_content = "Mari kita lakukan. Anda menulis pesan, Hati, dan saya akan mengirimkannya kepada pria itu.",
  ui_story_5046_50460401_73_dialog_content = "Minta dia untuk datang sendiri ke suatu tempat di luar Umbraton.",
  ui_story_5046_50460401_74_dialog_content = "Oke.",
  ui_story_5046_50460401_75_dialog_content = "Awasi pria itu dengan cermat, Grimme, jadi tidak ada jalan keluar.",
  ui_story_5046_50460401_76_dialog_content = "Cobalah lari, matikan lampunya, seperti bagaimana aku menyeret tubuh masuk.",
  ui_story_5046_50460401_77_dialog_content = "Apa?",
  ui_story_5046_50460401_78_dialog_content = "Mau minum? Anda dapat kembali setelah kesepakatan selesai.",
  ui_story_5046_50460401_79_dialog_content = "Maka Anda tidak akan mendapatkan kesempatan untuk menikmati putaran.",
  ui_story_5046_50460401_80_dialog_content = "Bagaimana ceritanya dengan liontin itu?",
  ui_story_5046_50460401_81_dialog_content = "Kenapa Hati sangat menginginkannya?",
  ui_story_5046_50460401_82_dialog_content = "Yah, aku bisa menceritakan kisahnya sekarang Hati tidak ada.",
  ui_story_5046_50460401_83_dialog_content = "Aku ingat suatu hari, Hati berlari kembali dan memberitahuku dia melihat liontin ibunya pada pria bertopeng.",
  ui_story_5046_50460401_84_dialog_content = "Pria bertopeng? Itu pasti Kapten Zenas. Dia satu-satunya yang memakai topeng.",
  ui_story_5046_50460401_85_dialog_content = "Dia mendekatinya sebelumnya, tetapi dia tampak sangat terkejut melihatnya dan tidak mau menyerahkan liontin itu untuk apa pun.",
  ui_story_5046_50460401_86_dialog_content = "Jadi dia sudah merencanakan untuk mendapatkan liontin itu darinya sejak saat itu.",
  ui_story_5046_50460401_87_dialog_content = "Itu merupakan kejahatan!",
  ui_story_5046_50460401_88_dialog_content = "Dan mengapa Hati jadi pasti liontin Zenas yang dia cari?",
  ui_story_5046_50460401_89_dialog_content = "Dia mengatakan itu membuatnya pusing saat pertama kali dia melihat liontin itu di Zenas.",
  ui_story_5046_50460401_90_dialog_content = "Dia bilang dia ingat dengan sangat jelas bahwa polanya sama persis dengan yang ada pada ibunya.",
  ui_story_5046_50460401_91_dialog_content = "Dia juga mengatakan mendapatkan liontin itu akan membuatnya memulihkan lebih banyak ingatan yang hilang.",
  ui_story_5046_50460401_92_dialog_content = "Apakah yang Anda maksud: motif kuda poni kecil",
  ui_story_5046_50460401_93_dialog_content = "Saya mendengar setiap keluarga bangsawan di Lumopolis memiliki lambang mereka sendiri, jadi apakah ibu Zenas dan Hati berasal dari garis keturunan yang sama?",
  ui_story_5046_50460401_94_dialog_content = "Aku tidak tahu.",
  ui_story_5046_50460401_95_dialog_content = "Pesan sudah siap.",
  ui_story_5046_50460401_96_dialog_content = "<color=#e8d9bb>Knock-knock, knock, knock-knock</color>",
  ui_story_5046_50460401_97_dialog_content = "Tepat waktu. Masuklah.",
  ui_story_5046_50460401_98_dialog_content = "Bos.",
  ui_story_5046_50460401_99_dialog_content = "Ya, benar, Hati Dan PlayerName keren.",
  ui_story_5046_50460401_100_dialog_content = "Tidak ada apa-apa dengan faksi Umbraton sejauh ini. Ksatria dari Lumopolis sedang dalam perjalanan ke bar bersama orang-orang sekarang.",
  ui_story_5046_50460401_101_dialog_content = "Mereka harus berada di sini kapan saja.",
  ui_story_5046_50460401_102_dialog_content = "Benarkah itu? Waktu yang tepat.",
  ui_story_5046_50460401_103_dialog_content = "Kerja bagus. Ini gajimu.",
  ui_story_5046_50460401_104_dialog_content = "Terima kasih bos!",
  ui_story_5046_50460401_105_dialog_content = "Aku akan pergi sekarang.",
  ui_story_5046_50460401_106_dialog_content = "(Anak itu adalah informan Grimme? Siapa sebenarnya Grimme...?)",
  ui_story_5046_50460401_107_dialog_content = "Saya akan menyampaikan pesan, Hati. Anda menuju tempat pertemuan.",
  ui_story_5046_50460401_108_dialog_content = "Oke. Ayo pergi, PlayerName.",
  ui_story_5046_50460401_109_dialog_content = "Lebih baik kau datang diam-diam dan jangan mencoba meminta bantuan, atau...",
  ui_story_5046_50460401_110_dialog_content = "Atau Anda akan menjatuhkan saya, kan?",
  ui_story_5046_50460401_111_dialog_content = "Saya harap Anda melakukan apa yang Anda janjikan kali ini — biarkan saya pergi begitu Anda memiliki liontin itu.",
  ui_story_5046_50460401_112_dialog_content = "Penjaga Lumopolis ada di dekatnya, jadi berhati-hatilah saat Anda pergi.",
  ui_story_5046_50460401_113_dialog_content = "Aku hanya akan menjatuhkan mereka diam-diam.",
  ui_story_5046_50460402_1_dialog_content = "<color=#e8d9bb>ding—</color>",
  ui_story_5046_50460402_2_dialog_content = "Selamat datang. Anda mau minum apa?",
  ui_story_5046_50460402_3_dialog_content = "Oh, itu pejabat dari Lumopolis. Apa yang membawa Anda ke bar Umbraton kecil saya, bolehkah saya bertanya?",
  ui_story_5046_50460402_4_dialog_content = "Kami di sini bukan untuk mengobrol, hanya mengajukan beberapa pertanyaan.",
  ui_story_5046_50460402_5_dialog_content = "Mengapa Anda tidak tinggal dan minum? Aku akan memberitahumu semua yang aku tahu.",
  ui_story_5046_50460402_6_dialog_content = "Tidak perlu berterima kasih.",
  ui_story_5046_50460402_7_dialog_content = "Saksi mata mengklaim pelaku pembakaran saat latihan adalah teman Anda Hati.",
  ui_story_5046_50460402_8_dialog_content = "Menilai dari rute pelariannya, kami yakin dia melarikan diri ke bar ini.",
  ui_story_5046_50460402_9_dialog_content = "Kami berharap Anda akan bekerja sama dengan penyelidikan kami.",
  ui_story_5046_50460402_10_dialog_content = "Saya ingin sekali, tapi saya harap Anda bisa memberikan bukti nyata itu Hati adalah pembakar.",
  ui_story_5046_50460402_11_dialog_content = "Atau aku tidak bisa membantumu.",
  ui_story_5046_50460402_12_dialog_content = "Maka kita harus mencari dengan paksa.",
  ui_story_5046_50460402_13_dialog_content = "Hati memiliki Caelestite.",
  ui_story_5046_50460402_14_dialog_content = "!",
  ui_story_5046_50460402_15_dialog_content = "Keamanan Lumopolis datang ke Umbraton hanya untuk kehilangan seorang VIP.",
  ui_story_5046_50460402_16_dialog_content = "Merindukan Bethel tidak beralih ke faksi Umbraton mana pun tetapi memungkinkan Anda untuk menyelidiki secara diam-diam.",
  ui_story_5046_50460402_17_dialog_content = "Dugaan saya adalah dia tidak ingin itu keluar di depan umum.",
  ui_story_5046_50460402_18_dialog_content = "Anda juga tidak ingin saya menyebarkannya, bukan?",
  ui_story_5046_50460402_19_dialog_content = "Huh, jadi Anda tahu di mana Hati adalah? Serahkan dia dan Anda mungkin mendapatkan sesuatu dari Lumopolis dan Umbraton.",
  ui_story_5046_50460402_20_dialog_content = "Ya, kita bisa membicarakannya saat kita sendirian.",
  ui_story_5046_50460402_21_dialog_content = "Tinggalkan kami, kalian semua.",
  ui_story_5046_50460402_22_dialog_content = "Tapi Kapten—",
  ui_story_5046_50460402_23_dialog_content = "Tunggu aku di luar.",
  ui_story_5046_50460402_24_dialog_content = "Siap, Pak.",
  ui_story_5046_50460402_25_dialog_content = "Ada alasan mengapa Anda berhasil sampai ke tempat Anda hari ini.",
  ui_story_5046_50460402_26_dialog_content = "Nah, ini adalah pesan itu Hati ingin saya untuk menyampaikan.",
  ui_story_5046_50460402_27_dialog_content = "\"Untuk Pria Bertopeng:\"",
  ui_story_5046_50460402_28_dialog_content = "\"Bawa liontin itu dan temui aku di bawah pohon mapel tertinggi di sisi timur Umbraton sebelum matahari terbenam. Kamu menukarnya dengan Caelestite.\"",
  ui_story_5046_50460402_29_dialog_content = "\"Pastikan kamu datang sendiri dan jangan bilang siapa-siapa. Jangan coba-coba trik apapun juga.\"",
  ui_story_5046_50460402_30_dialog_content = "\"Hati\"",
  ui_story_5046_50460402_31_dialog_content = "...",
  ui_story_5046_50460402_32_dialog_content = "Dapatkah Anda menjamin bahwa Caelestite aman?",
  ui_story_5046_50460402_33_dialog_content = "Yakinlah. Caelestite benar-benar aman. Plus, waktunya tidak ada di pihak Anda dan itu satu-satunya pilihan Anda.",
  ui_story_5046_50460402_34_dialog_content = "Tidak ada yang mengancam saya.",
  ui_story_5046_50460402_35_dialog_content = "Tenang saja. Tetap untuk minum waktu berikutnya.",
  ui_story_5046_50460402_36_dialog_content = "...",
  ui_story_5046_50460402_37_dialog_content = "Bos.",
  ui_story_5046_50460402_38_dialog_content = "Perhatikan bar. Aku harus pergi.",
  ui_story_5046_50460402_39_dialog_content = "Kapten!",
  ui_story_5046_50460402_40_dialog_content = "Aku harus memeriksa sesuatu sendirian.",
  ui_story_5046_50460402_41_dialog_content = "Kalian tetap tinggal dan menyisir setiap inci tempat itu.",
  ui_story_5046_50460402_42_dialog_content = "Jika Anda melihat tersangka dan Caelestite, bawa mereka kembali selama keamanannya terjamin.",
  ui_story_5046_50460402_43_dialog_content = "Siap, Pak!",
  ui_story_5046_50460402_44_dialog_content = "<color=#e8d9bb>Arsip Umbraton</color>",
  ui_story_5046_50460402_45_dialog_content = "Segala sesuatu tentang kebakaran dalam dua bulan terakhir ada di sini.",
  ui_story_5046_50460402_46_dialog_content = "Terima kasih. Aku akan memeriksa mereka sendiri.",
  ui_story_5046_50460402_47_dialog_content = "Kebakaran terjadi terlalu sering dalam jangka waktu tersebut, namun hanya tiga yang meninggal.",
  ui_story_5046_50460402_48_dialog_content = "Andre, laki-laki, 36 tahun, korban kebakaran pertama, bekerja paruh waktu dan seorang pecandu alkohol.",
  ui_story_5046_50460402_49_dialog_content = "Fairmont, laki-laki, 42, korban kebakaran kedua, seorang pedagang yang menjalankan bisnis suam-suam kuku.",
  ui_story_5046_50460402_50_dialog_content = "Carlotta, perempuan, 31 tahun, korban kebakaran ketiga, seorang tukang cuci biasa.",
  ui_story_5046_50460402_51_dialog_content = "Ketiganya pernah bekerja di panti asuhan. Andre adalah seorang akuntan, Fairmont seorang pengantar barang, dan Carlotta seorang wanita pembersih.",
  ui_story_5046_50460402_52_dialog_content = "Dan penyebut yang sama yang mereka bagi Hati adalah panti asuhan.",
  ui_story_5046_50460402_53_dialog_content = "Jadi, dulu Hati diintimidasi oleh mereka di panti asuhan dan membunuh mereka karena dendam?",
  ui_story_5046_50460402_54_dialog_content = "Saya harus menggali lebih dalam tentang personel panti asuhan yang lama.",
  ui_story_5046_50460402_55_dialog_content = "Namun, masing-masing dari mereka berpencar setelah kebakaran. Hampir tidak mungkin menemukan orang untuk diajak bicara.",
  ui_story_5046_50460402_56_dialog_content = "Apa yang akan aku lakukan?",
  ui_story_5046_50460402_57_dialog_content = "\"Tuan Hamell telah lama menyumbang ke panti asuhan, dan secara teratur menyelenggarakan acara amal untuk mengumpulkan dana untuk fasilitas tersebut...\"",
  ui_story_5046_50460402_58_dialog_content = "Pak Hamell?!",
  ui_story_5046_50460402_59_dialog_content = "<color=#e8d9bb>Di dalam Panti Asuhan</color>",
  ui_story_5046_50460402_60_dialog_content = "Bisakah saya mengambil beberapa menit dari waktu Anda, Tn. Hamell?",
  ui_story_5046_50460402_61_dialog_content = "Merindukan Kristen! Anda menemukan Caelestite, kan? Betapa indahnya!",
  ui_story_5046_50460402_62_dialog_content = "Masih belum ada tanda-tanda Caelestite, sayangnya, tapi aku punya beberapa pertanyaan tentang Dark Slayer yang ingin kutanyakan padamu.",
  ui_story_5046_50460402_63_dialog_content = "Pembakar itu?",
  ui_story_5046_50460402_64_dialog_content = "Hati adalah tersangka utama dalam kasus ini, dan dia mungkin telah menyalakan api sebagai balas dendam terhadap pekerja panti asuhan tua yang dia dendam.",
  ui_story_5046_50460402_65_dialog_content = "Anda telah lama mendanai dan menjalankan amal untuk fasilitas tersebut, jadi Anda harus mengetahui situasinya dengan baik.",
  ui_story_5046_50460402_66_dialog_content = "Jadi saya ingin meminta pendapat Anda.",
  ui_story_5046_50460402_67_dialog_content = "Memang benar aku mendanai dan menjalankan amal untuk panti asuhan.",
  ui_story_5046_50460402_68_dialog_content = "Tapi direktur dan personel benar-benar menangani secara spesifik. Saya hanya harus menunjukkan wajah saya di acara tersebut.",
  ui_story_5046_50460402_69_dialog_content = "Panti asuhan akan menyajikan laporan keuangan secara teratur kepada saya, tetapi selain itu, saya tidak tahu apa-apa lagi.",
  ui_story_5046_50460402_70_dialog_content = "Tapi Anda adalah direktur panti asuhan baru dan sangat dekat dengan fasilitas lama.",
  ui_story_5046_50460402_71_dialog_content = "Jadi jika tersangka benar-benar mengincar mantan personel panti asuhan untuk balas dendam, Anda bisa menjadi target berikutnya.",
  ui_story_5046_50460402_72_dialog_content = "Saya harap Anda dapat mengingat lebih detail. Itu akan membantu kita menangkap tersangka.",
  ui_story_5046_50460402_73_dialog_content = "Juga, saya harap Anda dapat tinggal sementara di lokasi yang dilindungi oleh Penjaga Lumo.",
  ui_story_5046_50460402_74_dialog_content = "Tersangka dapat menyerang dan mengancam hidup Anda kapan saja, dan Penjaga Lumo dapat menjaga Anda tetap aman.",
  ui_story_5046_50460402_75_dialog_content = "Merindukan Kristen, semua yang Anda katakan adalah dugaan.",
  ui_story_5046_50460402_76_dialog_content = "Perlu diketahui, dulu panti asuhan ini adalah yang terbesar di Umbraton. Terlalu banyak orang yang memiliki koneksi ke sana.",
  ui_story_5046_50460402_77_dialog_content = "Anda dapat bertanya kepada siapa pun di sini dan mereka mungkin ada hubungannya dengan fasilitas tersebut.",
  ui_story_5046_50460402_78_dialog_content = "Pekerja konstruksi, petugas kebersihan, bahkan pedagang kaki lima di luar panti asuhan...",
  ui_story_5046_50460402_79_dialog_content = "Apakah Anda memberi tahu saya bahwa tersangka ingin melepaskan mereka juga?",
  ui_story_5046_50460402_80_dialog_content = "Anu…",
  ui_story_5046_50460402_81_dialog_content = "Spekulasi itu mungkin hanya kebetulan.",
  ui_story_5046_50460402_82_dialog_content = "Daripada membuang-buang waktu untuk kebetulan, mungkin lebih baik dihabiskan untuk mengejar tersangka dan membuat semua orang lega.",
  ui_story_5046_50460402_83_dialog_content = "Sudah larut. Saatnya tulang-tulang tua ini kembali.",
  ui_story_5046_50460402_84_dialog_content = "Maaf mengganggu Anda. Selamat tinggal.",
  ui_story_5046_50460402_85_dialog_content = "Maafkan aku karena tidak melihatmu keluar.",
  ui_story_5046_50460402_86_dialog_content = "Sudah lama sekali, teman lama.",
  ui_story_5046_50460402_87_dialog_content = "Kamu rupanya.",
  ui_story_5046_50460402_88_dialog_content = "Tidak senang melihat teman lama Anda?",
  ui_story_5046_50460402_89_dialog_content = "Saya tidak berpikir Anda di sini untuk saya tapi <color=#FFB400>itu</color>, Kanan?",
  ui_story_5046_50460501_1_dialog_content = "Tuan Hamell bertingkah sedikit curiga, seperti sedang menyembunyikan sesuatu.",
  ui_story_5046_50460501_2_dialog_content = "Tapi dia tidak mau memberikan info lebih lanjut.",
  ui_story_5046_50460501_3_dialog_content = "Hati menjadi tersangka, penculikan Caelestite, bahan bakar dan detonator di tempat latihan...",
  ui_story_5046_50460501_4_dialog_content = "Kebakaran panti asuhan tua, keengganan Pak Hamell...",
  ui_story_5046_50460501_5_dialog_content = "Bisakah itu semua hanya satu kebetulan besar?",
  ui_story_5046_50460501_6_dialog_content = "Huh... Aku kehabisan akal.",
  ui_story_5046_50460501_7_dialog_content = "Andai saja Pak Zenas ada di sini. Dia pasti—",
  ui_story_5046_50460501_8_dialog_content = "Apakah Anda mencari saya, nona?",
  ui_story_5046_50460501_9_dialog_content = "Pak?!",
  ui_story_5046_50460501_10_dialog_content = "Sudah berapa lama kau di situ?",
  ui_story_5046_50460501_11_dialog_content = "Sementara waktu. Saya melihat Anda bergumam pada diri sendiri seperti sedang berpikir keras, jadi saya memutuskan untuk tidak menyela.",
  ui_story_5046_50460501_12_dialog_content = "Maaf, saya tidak memperhatikan...",
  ui_story_5046_50460501_13_dialog_content = "Oh, saya membuat penemuan besar dalam kasus ini, Pak!",
  ui_story_5046_50460501_14_dialog_content = "Benar-benar? Apa yang Anda temukan?",
  ui_story_5046_50460501_15_dialog_content = "Gadis kecil yang kami selamatkan saat latihan mengatakan kebakaran terjadi karena dia tidak sengaja menabrak sebuah kotak.",
  ui_story_5046_50460501_16_dialog_content = "Saya menduga kotak itu adalah detonator yang dipasang untuk menyalakan tong bahan bakar yang ditimbun di gudang pada waktu tertentu.",
  ui_story_5046_50460501_17_dialog_content = "Siapa pun yang mengaturnya pasti tidak mengandalkan gadis kecil itu untuk mengacaukan rencananya.",
  ui_story_5046_50460501_18_dialog_content = "Pengapian tepat waktu... Tapi untuk apa?",
  ui_story_5046_50460501_19_dialog_content = "Berdasarkan penyelidikan sebelumnya, hanya terjadi tiga kali kebakaran dalam dua bulan terakhir yang menelan korban jiwa.",
  ui_story_5046_50460501_20_dialog_content = "Dan ketiga almarhum pernah bekerja di panti asuhan tua.",
  ui_story_5046_50460501_21_dialog_content = "Hati, yang muncul di tempat kejadian hari ini, tinggal di fasilitas itu selama sebulan.",
  ui_story_5046_50460501_22_dialog_content = "Saya yakin sesuatu pasti telah terjadi padanya di panti asuhan yang membuatnya membenci para korban.",
  ui_story_5046_50460501_23_dialog_content = "Setelah kehilangan kendali atas kekuatannya dan membakar panti asuhan, dia dibawa oleh Shadowlord ke sebuah mansion, jadi dia terpaksa meninggalkan rencana balas dendamnya.",
  ui_story_5046_50460501_24_dialog_content = "Sampai dia dibebaskan dua bulan lalu, mendorong Hati untuk segera mengejar mereka.",
  ui_story_5046_50460501_25_dialog_content = "Tuan Hamell telah lama menjadi penyandang dana panti asuhan dan juga muncul di lokasi hari ini.",
  ui_story_5046_50460501_26_dialog_content = "Jadi Anda berpikir Hati menargetkan Tuan Hamell.",
  ui_story_5046_50460501_27_dialog_content = "Ya, tapi itu hanya teori tanpa ada yang solid untuk mendukungnya.",
  ui_story_5046_50460501_28_dialog_content = "Jadi Anda pergi menemui Tuan Hamell dengan harapan dia akan bekerja sama.",
  ui_story_5046_50460501_29_dialog_content = "Ya...",
  ui_story_5046_50460501_30_dialog_content = "Tuan Hamell menolak teori saya sebagai kebetulan, tetapi saya merasa dia menyembunyikan sesuatu dari saya.",
  ui_story_5046_50460501_31_dialog_content = "Tubuh Anda selalu selangkah lebih maju dari pikiran Anda, nona.",
  ui_story_5046_50460501_32_dialog_content = "Apa yang Anda maksud dengan itu, Pak?",
  ui_story_5046_50460501_33_dialog_content = "Setiap orang yang bisa meraih kekayaan dan ketenaran dalam tas campuran seperti Umbraton memiliki rahasianya sendiri.",
  ui_story_5046_50460501_34_dialog_content = "Dan rahasia itu adalah garis hidup mereka yang mereka tidak ingin orang lain tahu, terutama yang berasal dari Lumopolis.",
  ui_story_5046_50460501_35_dialog_content = "Saya bisa mengerti bagaimana Anda ingin melindungi Tuan Hamell, Yang Mulia, tapi Anda hanya membuat tersangka khawatir.",
  ui_story_5046_50460501_36_dialog_content = "Tuan Hamell tidak akan pernah bekerja sama atau menerima perlindungan Anda, dan tersangka kemungkinan besar akan memperhatikan apa yang telah Anda lakukan dan bersembunyi lebih dalam.",
  ui_story_5046_50460501_37_dialog_content = "Ini adalah kurangnya pandangan jauh ke depan di pihak saya... Maaf, Pak.",
  ui_story_5046_50460501_38_dialog_content = "Ternyata aku tidak membantumu sama sekali...",
  ui_story_5046_50460501_39_dialog_content = "Tapi saya tidak berpikir teori Anda tidak berdasar. Itu tidak semua kebetulan.",
  ui_story_5046_50460501_40_dialog_content = "Jadi, Anda menyetujui teori saya, Pak?",
  ui_story_5046_50460501_41_dialog_content = "Tentu saja. Setelah menyaksikan perkembangan Anda selama bertahun-tahun, saya tahu lebih baik dari siapa pun tentang kemampuan Anda.",
  ui_story_5046_50460501_42_dialog_content = "Anda yang terbaik dalam menarik petunjuk dari catatan dan merangkainya menjadi satu bukti yang komprehensif, nona.",
  ui_story_5046_50460501_43_dialog_content = "S-Tuan...",
  ui_story_5046_50460501_44_dialog_content = "Itu karena kamu adalah instruktur yang hebat!",
  ui_story_5046_50460501_45_dialog_content = "...",
  ui_story_5046_50460501_46_dialog_content = "Ahem. Apakah Anda tidak menyelidiki tersangka dan keberadaan Caelestite, Pak?",
  ui_story_5046_50460501_47_dialog_content = "Ya. Itu membawa saya ke Firefly Bar, yang pemiliknya adalah seorang teman Hati.",
  ui_story_5046_50460501_48_dialog_content = "Tapi dia bungkam, jadi aku tidak bisa mendapatkan apa-apa. Saya memiliki orang-orang yang mengintai bar, jadi mudah-mudahan kita akan mendapatkan sesuatu.",
  ui_story_5046_50460501_49_dialog_content = "Aduh...",
  ui_story_5046_50460501_50_dialog_content = "Ada apa, Pak? Apakah luka bakar itu menyakitimu?",
  ui_story_5046_50460501_51_dialog_content = "Ini semua salahku bahwa kau terluka...",
  ui_story_5046_50460501_52_dialog_content = "Saya baik-baik saja. Luka kecil tidak akan menggangguku.",
  ui_story_5046_50460501_53_dialog_content = "Karena Anda yakin Tuan Hamell adalah target Hati selanjutnya, saya harus kembali dan membuat rencana...",
  ui_story_5046_50460501_54_dialog_content = "Kita hampir kehabisan waktu...",
  ui_story_5046_50460501_55_dialog_content = "Ugh!",
  ui_story_5046_50460501_56_dialog_content = "Tolong berhenti memaksakan diri, Pak!",
  ui_story_5046_50460501_57_dialog_content = "Ketika kami bertemu pertama kali, Anda menyerbu ke dalam api untuk menyelamatkan saya meskipun Anda terluka.",
  ui_story_5046_50460501_58_dialog_content = "Dan hari ini, Anda melindungi saya ketika saya bergegas dengan sembrono ke dalam api.",
  ui_story_5046_50460501_59_dialog_content = "Sudah waktunya aku melakukan sesuatu untukmu!",
  ui_story_5046_50460501_60_dialog_content = "Gadisku...",
  ui_story_5046_50460501_61_dialog_content = "Tolong berhenti memanggilku seperti itu.",
  ui_story_5046_50460501_62_dialog_content = "Aku tidak ingin terus menjadi bunga yang dimanjakan olehmu, tuan.",
  ui_story_5046_50460501_63_dialog_content = "Saya ingin menjadi hakim yang membawa keadilan ke Lumopolis dan seseorang yang bisa diandalkan seperti Anda, Pak.",
  ui_story_5046_50460501_64_dialog_content = "Aku tahu jalanku masih panjang, tapi aku tidak akan pergi kemana-mana jika aku tidak mengambil langkah pertama.",
  ui_story_5046_50460501_65_dialog_content = "Meski hanya langkah kecil, aku harus tetap mengambilnya.",
  ui_story_5046_50460501_66_dialog_content = "Jadi, tolong izinkan saya untuk memastikan keamanan Tuan Hamell!",
  ui_story_5046_50460501_67_dialog_content = "Heh...",
  ui_story_5046_50460501_68_dialog_content = "Gadisku...",
  ui_story_5046_50460501_69_dialog_content = "Maksud saya, Kristen.",
  ui_story_5046_50460501_70_dialog_content = "Itu sentimen yang menyentuh, dan saya sangat tersentuh oleh tekadnya.",
  ui_story_5046_50460501_71_dialog_content = "(Tunggu, kenapa dia mencondongkan tubuh lebih dekat...?)",
  ui_story_5046_50460501_72_dialog_content = "(Aku bisa merasakan napasnya...)",
  ui_story_5046_50460501_73_dialog_content = "(Rambutnya membuat wajahku gatal...)",
  ui_story_5046_50460501_74_dialog_content = "Dan saya juga bisa merasakan sepenuhnya kasih sayang yang Anda pegang terhadap saya ...",
  ui_story_5046_50460501_75_dialog_content = "(Kasih sayang? Apa yang dia bicarakan?)",
  ui_story_5046_50460501_76_dialog_content = "(Tidak, jangan beri tahu saya!)",
  ui_story_5046_50460501_77_dialog_content = "Kristen, SAYA...",
  ui_story_5046_50460501_78_dialog_content = "S-Tuan!",
  ui_story_5046_50460501_79_dialog_content = "Aku harus dalam perjalanan ke Mr. Hamell's!",
  ui_story_5046_50460501_80_dialog_content = "Saya akan berusaha untuk memenuhi misi ini!",
  ui_story_5046_50460501_81_dialog_content = "Heheh...",
  ui_story_5046_50460501_82_dialog_content = "Saya percaya dengan kecerdasan dan keberanian Anda, Anda akan menghadapi tantangan dengan gemilang.",
  ui_story_5046_50460501_83_dialog_content = "Terima kasih, Pak!",
  ui_story_5046_50460501_84_dialog_content = "Saya tidak akan mengecewakan Anda dan menyelesaikan misi!",
  ui_story_5046_50460501_85_dialog_content = "<color=#e8d9bb>Umbraton pedesaan</color>",
  ui_story_5046_50460501_86_dialog_content = "Itu pohon maple tertinggi di hutan.",
  ui_story_5046_50460501_87_dialog_content = "Apakah kita di sana sekarang?",
  ui_story_5046_50460501_88_dialog_content = "Jalan setapaknya bergelombang di hutan, jadi hati-hati—",
  ui_story_5046_50460501_89_dialog_content = "Aduh!",
  ui_story_5046_50460501_90_dialog_content = "—Atau Anda akan tersandung.",
  ui_story_5046_50460501_91_dialog_content = "Sakitnya bukan main!",
  ui_story_5046_50460501_92_dialog_content = "Duduk.",
  ui_story_5046_50460501_93_dialog_content = "Ini tidak serius. Kamu akan baik-baik saja.",
  ui_story_5046_50460501_94_dialog_content = "Duduklah, kamu.",
  ui_story_5046_50460501_95_dialog_content = "(Sungguh mengintimidasi... Aku tidak bisa melawannya sama sekali...)",
  ui_story_5046_50460501_96_dialog_content = "Baiklah, aku akan duduk sebentar.",
  ui_story_5046_50460501_97_dialog_content = "Gulung kaki celana Anda.",
  ui_story_5046_50460501_98_dialog_content = "Untuk apa?",
  ui_story_5046_50460501_99_dialog_content = "Aku akan mengurangi rasa sakitnya.",
  ui_story_5046_50460501_100_dialog_content = "Yah, tidak terlalu sakit... Whoa, kamu tidak perlu menggulungnya untukku, aku bisa melakukannya sendiri!",
  ui_story_5046_50460501_101_dialog_content = "I-Apakah ini cukup baik?",
  ui_story_5046_50460501_102_dialog_content = "Ya, seharusnya di sini. Apakah ini sakit ketika saya menekannya?",
  ui_story_5046_50460501_103_dialog_content = "Tidak apa-apa, tapi tanganmu panas! Meskipun di hutan cukup dingin.",
  ui_story_5046_50460501_104_dialog_content = "Suhu tubuh saya lebih tinggi dari biasanya. Mendekatlah jika kau merasa kedinginan.",
  ui_story_5046_50460501_105_dialog_content = "(Hati mungkin tampak tidak bisa didekati, tetapi telinganya yang lembut akan terangkat saat dia berjongkok.)",
  ui_story_5046_50460501_106_dialog_content = "(Dan dia sebenarnya cukup baik, mengingatkan saya untuk berhati-hati berjalan di sini dan memijat pergelangan kaki saya yang terkilir...)",
  ui_story_5046_50460501_107_dialog_content = "Ada apa?",
  ui_story_5046_50460501_108_dialog_content = "Tidak ada, tidak apa-apa!",
  ui_story_5046_50460501_109_dialog_content = "Kami masih punya waktu. Mengapa kita tidak istirahat di sini?",
  ui_story_5046_50460501_110_dialog_content = "Oke.",
  ui_story_5046_50460501_111_dialog_content = "...",
  ui_story_5046_50460501_112_dialog_content = "...",
  ui_story_5046_50460501_113_dialog_content = "(Ini canggung. Aku harus mengatakan sesuatu...)",
  ui_story_5046_50460501_114_dialog_content = "Bisakah kamu ceritakan tentang ibumu?",
  ui_story_5046_50460501_115_dialog_content = "A-aku tidak bermaksud buruk dengan itu!",
  ui_story_5046_50460501_116_dialog_content = "Ibuku meninggalkanku segera setelah aku lahir. Aku bahkan tidak bisa melihat seperti apa dia...",
  ui_story_5046_50460501_117_dialog_content = "...",
  ui_story_5046_50460501_118_dialog_content = "Saya kira Anda tidak ingin memberi tahu saya, t-tidak apa-apa.",
  ui_story_5046_50460501_119_dialog_content = "...",
  ui_story_5046_50460501_120_dialog_content = "Terus terang, saya mengerti betapa Anda ingin memulihkan ingatan itu.",
  ui_story_5046_50460501_121_dialog_content = "...",
  ui_story_5046_50460501_122_dialog_content = "Soroz adalah orang yang membesarkan saya selama ini.",
  ui_story_5046_50460501_123_dialog_content = "Itu bukan hanya Colossus tapi juga teman dan guruku.",
  ui_story_5046_50460501_124_dialog_content = "Kami sudah tidak terpisahkan selama bertahun-tahun. Itu akan mengajari saya tentang dunia luar dan mengobrol ketika saya bosan.",
  ui_story_5046_50460501_125_dialog_content = "Sayang sekali dia tidak mengingatku sekarang.",
  ui_story_5046_50460501_126_dialog_content = "Itu kehilangan ingatannya juga?",
  ui_story_5046_50460501_127_dialog_content = "Itu kehilangan semua ingatan untuk menyelamatkan hidup saya, jadi saya berusaha menemukan cara untuk memulihkannya.",
  ui_story_5046_50460501_128_dialog_content = "Grimme benar, kami memiliki kesamaan.",
  ui_story_5046_50460501_129_dialog_content = "Dan saat itulah kami berdua bekerja keras untuk mengembalikan ingatan.",
  ui_story_5046_50460501_130_dialog_content = "Jadi saya mengerti bagaimana perasaan Anda, dan saya harap Anda dapat mengingat kembali kejadian bersama ibu Anda.",
  ui_story_5046_50460501_131_dialog_content = "...",
  ui_story_5046_50460501_132_dialog_content = "Jangan ragu untuk memberi tahu saya jika ada yang bisa saya bantu terkait ingatan Soroz.",
  ui_story_5046_50460501_133_dialog_content = "Sebelum Anda dapat membantu, Anda harus menghapus status tersangka Anda!",
  ui_story_5046_50460501_134_dialog_content = "Berjanjilah padaku kau akan berterus terang setelah kita mendapatkan liontinnya, oke?",
  ui_story_5046_50460501_135_dialog_content = "Tsk... Betapa merepotkan.",
  ui_story_5046_50460501_136_dialog_content = "Ya, tetapi Anda tetap harus melakukannya!",
  ui_story_5046_50460501_137_dialog_content = "Ya sudah.",
  ui_story_5046_50460501_138_dialog_content = "Anda berjanji!",
  ui_story_5046_50460501_139_dialog_content = "Graah—!",
  ui_story_5046_50460501_140_dialog_content = "Kami mendapatkan Eclipsites datang, dan banyak dari mereka...",
  ui_story_5046_50460501_141_dialog_content = "Aaaaaah!!!",
  ui_story_5046_50460501_142_dialog_content = "Awas.",
  ui_story_5046_50460501_143_dialog_content = "Ayo, PlayerName, kenapa kamu begitu lemah?",
  ui_story_5046_50460501_144_dialog_content = "Caelestites tidak pernah dikenal karena berkelahi!",
  ui_story_5046_50460501_145_dialog_content = "Tidak berdaya.",
  ui_story_5046_50460501_146_dialog_content = "Jangan melihat ke bawah pada saya. Eclipsites akan datang di sebelah kiri Anda!",
  ui_story_5046_50460501_147_dialog_content = "Graah—!",
  ui_story_5046_50460501_148_dialog_content = "Makan kapak saya!",
  ui_story_5046_50460501_149_dialog_content = "Bagaimana dengan itu? Saya mungkin tidak bisa bertarung, tetapi kemampuan saya untuk berkoordinasi memiliki persetujuan dari Carleen!",
  ui_story_5046_50460501_150_dialog_content = "Lalu bersembunyi di belakangku dan berkoordinasi!",
  ui_story_5046_50460502_1_dialog_content = "Ini buruk, bagaimana mungkin ada begitu banyak Eclipsites di sini...",
  ui_story_5046_50460502_2_dialog_content = "Terkesiap... terkesiap...",
  ui_story_5046_50460502_3_dialog_content = "Ini bukan tempat atau waktu bagi saya untuk turun ...",
  ui_story_5046_50460502_4_dialog_content = "Graah...",
  ui_story_5046_50460502_5_dialog_content = "Lebih banyak Eclipse akan datang!",
  ui_story_5046_50460502_6_dialog_content = "Kutukan! Haruskah aku melakukan itu...",
  ui_story_5046_50460502_7_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5046_50460502_8_dialog_content = "Graah—!",
  ui_story_5046_50460502_9_dialog_content = "Wah, Eclipsites... Semuanya hangus!",
  ui_story_5046_50460502_10_dialog_content = "Saya tidak merasakan lagi Eclipsites di sekitar.",
  ui_story_5046_50460502_11_dialog_content = "Hosh... Hosh...",
  ui_story_5046_50460502_12_dialog_content = "Argh!",
  ui_story_5046_50460502_13_dialog_content = "Anda menggunakan kekuatan...",
  ui_story_5046_50460502_14_dialog_content = "Ck, ck...",
  ui_story_5046_50460502_15_dialog_content = "Kamu... Kamu telah berubah menjadi apa yang kamu benci...",
  ui_story_5046_50460502_16_dialog_content = "Beginilah... ibu... meninggalkan kami...",
  ui_story_5046_50460502_17_dialog_content = "Diam! Aku bilang tutup mulutmu!",
  ui_story_5046_50460502_18_dialog_content = "Apa yang salah, Hati?!",
  ui_story_5046_50460502_19_dialog_content = "(Hati berguling-guling di tanah kesakitan dengan mata tertutup.)",
  ui_story_5046_50460502_20_dialog_content = "Saya katakan, tutup mulut!",
  ui_story_5046_50460502_21_dialog_content = "Bu... aku bukan anak nakal... aku bukan...",
  ui_story_5046_50460502_22_dialog_content = "Mama? Apakah dia tenggelam dalam kenangan masa lalu?",
  ui_story_5046_50460502_23_dialog_content = "Ini tidak akan baik. Saya harus menggunakan kemampuan psikis saya untuk membebaskannya.",
  ui_story_5046_50460502_24_dialog_content = "Maaf, Hati, tapi saya tidak bermaksud mengorek pikiran Anda.",
  ui_story_5046_50460502_25_option_content = "Force Boost!",
  ui_story_5046_50460502_26_dialog_content = "(Di mana aku?)",
  ui_story_5046_50460502_27_dialog_content = "Bu, kamu kena cocklebur! Biarkan aku melepaskan mereka.",
  ui_story_5046_50460502_28_dialog_content = "Terima kasih, Hati.",
  ui_story_5046_50460502_29_dialog_content = "Kau anak yang baik.",
  ui_story_5046_50460502_30_dialog_content = "Hehe…",
  ui_story_5046_50460502_31_dialog_content = "Jarang sekali kau mengajakku bermain, Bu.",
  ui_story_5046_50460502_32_dialog_content = "(Ini sedikit Hati, dan ibunya juga.)",
  ui_story_5046_50460502_33_dialog_content = "...",
  ui_story_5046_50460502_34_dialog_content = "Maaf, Hati.",
  ui_story_5046_50460502_35_dialog_content = "Mengapa ibu meminta maaf? Anda tidak melakukan sesuatu yang salah.",
  ui_story_5046_50460502_36_dialog_content = "Yah, itu salahku.",
  ui_story_5046_50460502_37_dialog_content = "Tidak, kamu tidak melakukan kesalahan...",
  ui_story_5046_50460502_38_dialog_content = "Kamu seharusnya bermain di luar seperti anak-anak lain, tapi—",
  ui_story_5046_50460502_39_dialog_content = "Apa aku benar melakukan ini, Fenrir...?",
  ui_story_5046_50460502_40_dialog_content = "Apakah ibu menangis karena aku?",
  ui_story_5046_50460502_41_dialog_content = "Lalu aku tidak akan keluar lagi.",
  ui_story_5046_50460502_42_dialog_content = "Tidak apa-apa, aku baik-baik saja... Ayo, ayo bermain!",
  ui_story_5046_50460502_43_dialog_content = "Aku akan memejamkan mata, menghitung sampai tiga dan datang untuk menemukanmu!",
  ui_story_5046_50460502_44_dialog_content = "Oke!",
  ui_story_5046_50460502_45_dialog_content = "Tiga…",
  ui_story_5046_50460502_46_dialog_content = "Graah...",
  ui_story_5046_50460502_47_dialog_content = "Sesuatu yang hitam mendekati Ibu...",
  ui_story_5046_50460502_48_dialog_content = "Dua...",
  ui_story_5046_50460502_49_dialog_content = "Benda hitam itu sepertinya akan menyakitinya...",
  ui_story_5046_50460502_50_dialog_content = "Satu...",
  ui_story_5046_50460502_51_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5046_50460502_52_dialog_content = "!!!",
  ui_story_5046_50460502_53_dialog_content = "Hati?!",
  ui_story_5046_50460502_54_dialog_content = "Bu, makhluk ini sangat jahat!",
  ui_story_5046_50460502_55_dialog_content = "Aku akan membakarnya menjadi bola api!",
  ui_story_5046_50460502_56_dialog_content = "Hah!",
  ui_story_5046_50460502_57_dialog_content = "Kenapa kamu—bukankah aku sudah memberitahumu untuk tidak menggunakan api?!",
  ui_story_5046_50460502_58_dialog_content = "Kenapa kamu tidak mendengarkan?",
  ui_story_5046_50460502_59_dialog_content = "Tapi ibu...",
  ui_story_5046_50460502_60_dialog_content = "Pulanglah bersamaku sekarang!",
  ui_story_5046_50460502_61_dialog_content = "Huhu... Kenapa...",
  ui_story_5046_50460502_62_dialog_content = "Apakah Ibu membenciku... saat aku bermain api...?",
  ui_story_5046_50460502_63_dialog_content = "(Ibu tidak suka Hati... Tidak suka api...)",
  ui_story_5046_50460502_64_dialog_content = "(Hati adalah anak nakal ...)",
  ui_story_5046_50460502_65_dialog_content = "(Anak nakal...)",
  ui_story_5046_50460502_66_dialog_content = "(Hati adalah ... anak nakal?)",
  ui_story_5046_50460502_67_dialog_content = "(TIDAK, Hati bukan anak nakal!)",
  ui_story_5046_50460502_68_dialog_content = "(Menggunakan kekuatan yang tidak disetujui Ibu untuk menyelamatkan orang yang dicintai...)",
  ui_story_5046_50460502_69_dialog_content = "(Itu tidak berarti Hati adalah anak nakal!)",
  ui_story_5046_50460502_70_dialog_content = "(Hati bukan anak nakal...?)",
  ui_story_5046_50460502_71_dialog_content = "(Ibumu pasti punya alasan tak terucapkan untuk bersikap kejam Hati...)",
  ui_story_5046_50460502_72_dialog_content = "(Dan kamu yang muda terlihat sangat keren menggunakan api untuk melindungi ibumu!)",
  ui_story_5046_50460502_73_dialog_content = "(Sama seperti yang keren Hati yang menggunakan api untuk melindungiku!)",
  ui_story_5046_50460502_74_dialog_content = "(Hati adalah anak yang hebat dan luar biasa!)",
  ui_story_5046_50460502_75_dialog_content = "(Hati adalah anak yang luar biasa?)",
  ui_story_5046_50460502_76_dialog_content = "(Itu benar, Hati adalah anak yang luar biasa! Sekarang tenang dan bangun perlahan...)",
  ui_story_5046_50460502_77_dialog_content = "...",
  ui_story_5046_50460502_78_dialog_content = "PlayerName?",
  ui_story_5046_50460502_79_dialog_content = "Ini aku. Merasa baik-baik saja, bukan?",
  ui_story_5046_50460502_80_dialog_content = "Ya...",
  ui_story_5046_50460502_81_dialog_content = "Maaf membuat masalah untukmu.",
  ui_story_5046_50460502_82_dialog_content = "Tidak, saya harus meminta maaf.",
  ui_story_5046_50460502_83_dialog_content = "Aku menyelinap ke dalam memori Anda tanpa izin Anda ...",
  ui_story_5046_50460502_84_dialog_content = "Semoga kamu tidak marah padaku karena itu!",
  ui_story_5046_50460502_85_dialog_content = "Jika bukan karena kamu...",
  ui_story_5046_50460502_86_dialog_content = "Saya mungkin akan menjadi gila.",
  ui_story_5046_50460502_87_dialog_content = "Jadi terima kasih.",
  ui_story_5046_50460502_88_dialog_content = "Oke, aku tidak terbiasa dengan sikapmu yang tiba-tiba seperti ini.",
  ui_story_5046_50460502_89_dialog_content = "Ehem, sudah hampir waktunya. Kita harus sampai ke pohon itu.",
  ui_story_5046_50460502_90_dialog_content = "Jika kau masih membutuhkanku untuk memulihkan kenangan untukmu setelah semua ini berakhir...",
  ui_story_5046_50460502_91_dialog_content = "Datang saja menemuiku di Colossus.",
  ui_story_5046_50460502_92_dialog_content = "Tentu.",
  ui_story_5046_50460502_93_dialog_content = "Juga, ingatlah bahwa Anda berjanji untuk menjelaskan semuanya dan membersihkan diri Anda ...",
  ui_story_5046_50460502_94_dialog_content = "Jika tidak, Anda akan mendapatkan hadiah bahkan sebelum Anda dapat melihat saya.",
  ui_story_5046_50460502_95_dialog_content = "Aku berjanji.",
  ui_story_5046_50460502_96_dialog_content = "Serius?",
  ui_story_5046_50460502_97_dialog_content = "Ya.",
  ui_story_5046_50460601_1_dialog_content = "(Satu regu penjaga Lumopolis tiba di panti asuhan pagi ini tetapi Tuan Hamell tidak menyuruh mereka pergi.)",
  ui_story_5046_50460601_2_dialog_content = "(Dan dia bahkan membawa mereka keluar dari Umbraton dan masuk ke hutan ini...)",
  ui_story_5046_50460601_3_dialog_content = "(Sekarang Caelestite dan Hati di sini, dan kedua belah pihak bentrok.)",
  ui_story_5046_50460601_4_dialog_content = "(Penjaga ini tidak bertarung dengan gaya Lumopolis, namun mereka mengenakan seragam Penjaga Lumo.)",
  ui_story_5046_50460601_5_dialog_content = "(Apa yang terjadi di sini...?)",
  ui_story_5046_50460601_6_dialog_content = "(Tidak ada gunanya menghentikan mereka sekarang, jadi aku hanya perlu menonton dari sini untuk saat ini.)",
  ui_story_5046_50460601_7_dialog_content = "Huff... huff... Bahkan itu tidak bisa membunuhmu.",
  ui_story_5046_50460601_8_dialog_content = "Pak Hamell? Apa yang kamu katakan? Dan apa yang kamu lakukan di sini?",
  ui_story_5046_50460601_9_dialog_content = "Dimana Pak Zenas? Bukankah pesan itu sampai padanya?",
  ui_story_5046_50460601_10_dialog_content = "Daripada menunggumu datang untuk membunuhku, aku lebih memilih serangan pendahuluan.",
  ui_story_5046_50460601_11_dialog_content = "Bukankah Anda membunuh Andre, Fairmont, dan Carlotta?",
  ui_story_5046_50460601_12_dialog_content = "Anda menyimpan dendam atas apa yang terjadi pada Anda di panti asuhan dan ingin balas dendam terhadap kami?",
  ui_story_5046_50460601_13_dialog_content = "Anda ingin membunuh kami berdua sekaligus saat latihan, bukan?",
  ui_story_5046_50460601_14_dialog_content = "Sayang sekali rencana itu gagal.",
  ui_story_5046_50460601_15_dialog_content = "Saya tidak tahu siapa orang-orang itu, dan saya baru saja melewati tempat latihan.",
  ui_story_5046_50460601_16_dialog_content = "Berhenti bermain bodoh! Anda tidak menginginkan apa pun selain untuk saya dan—Argh!",
  ui_story_5046_50460601_17_dialog_content = "Awas!",
  ui_story_5046_50460601_18_dialog_content = "(Tuan Hamell jatuh! Benar Hati bunuh dia?)",
  ui_story_5046_50460601_19_dialog_content = "Bertahanlah, Tuan Hamell!",
  ui_story_5046_50460601_20_dialog_content = "Dia meninggal.",
  ui_story_5046_50460601_21_dialog_content = "Hati Kelp, kau tersangka pembunuhan. Saya meminta Anda ikut dengan saya ke Umbraton untuk penyelidikan lebih lanjut!",
  ui_story_5046_50460601_22_dialog_content = "Merindukan Kristen? Apa yang kamu lakukan di sini?",
  ui_story_5046_50460601_23_dialog_content = "Aku tidak membunuhnya.",
  ui_story_5046_50460601_24_dialog_content = "Tentu saja, Anda akan mengatakan itu.",
  ui_story_5046_50460601_25_dialog_content = "Saya bisa membuktikan bahwa Hati tidak bersalah. Tuan Hamell tidak tersentuh.",
  ui_story_5046_50460601_26_dialog_content = "Mengapa Anda menyembunyikan seorang pembunuh, PlayerName?",
  ui_story_5046_50460601_27_dialog_content = "Dia masih memegang senjata mematikan di tangannya...",
  ui_story_5046_50460601_28_dialog_content = "Aku mengatakan yang sebenarnya!",
  ui_story_5046_50460601_29_dialog_content = "Karena Anda ingin membela diri, mengapa Anda tidak datang ke Aula Kehakiman bersama saya?",
  ui_story_5046_50460601_30_dialog_content = "Meskipun saya hanya seorang hakim percobaan, saya harus memastikan bahwa keadilan ditegakkan dan tidak ada kejahatan yang luput dari hukuman.",
  ui_story_5046_50460601_31_dialog_content = "Tidak mungkin, aku belum bisa pergi denganmu.",
  ui_story_5046_50460601_32_dialog_content = "Menolak penangkapan hanya akan memperburuk keadaan.",
  ui_story_5046_50460601_33_dialog_content = "Ya terserah.",
  ui_story_5046_50460601_34_dialog_content = "Tolong dinginkan, kalian berdua!",
  ui_story_5046_50460601_35_dialog_content = "Kristen! Apakah kamu baik-baik saja?",
  ui_story_5046_50460601_36_dialog_content = "Kau terlambat, pria bertopeng.",
  ui_story_5046_50460601_37_dialog_content = "Apakah ini Tuan Hamell?",
  ui_story_5046_50460601_38_dialog_content = "Hati? Anda membunuh Tuan Hamell, bukan? Tangkap dia sekaligus, Kristen.",
  ui_story_5046_50460601_39_dialog_content = "Tunggu sebentar! Hati tidak melakukan semua itu!",
  ui_story_5046_50460601_40_dialog_content = "Anda ingin melawan? Tidak masalah dengan saya!",
  ui_story_5046_50460601_41_dialog_content = "Di sana berbahaya PlayerName, kemarilah!",
  ui_story_5046_50460601_42_dialog_content = "Rasakan ini!",
  ui_story_5046_50460601_43_dialog_content = "Kau terlalu lambat.",
  ui_story_5046_50460601_44_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5046_50460601_45_dialog_content = "topengku...",
  ui_story_5046_50460601_46_dialog_content = "Muka...!",
  ui_story_5046_50460601_47_dialog_content = "Siapa dia? Siapa dia?!",
  ui_story_5046_50460601_48_dialog_content = "Apa yang salah, Hati?",
  ui_story_5046_50460601_49_dialog_content = "Aku... eh... ah...!",
  ui_story_5046_50460601_50_dialog_content = "<color=#e8d9bb>\"Hari itu-\"</color>",
  ui_story_5046_50460601_51_dialog_content = "<color=#e8d9bb>\"Aku melihat wajah ini.\"</color>",
  ui_story_5046_50460601_52_dialog_content = "<color=#e8d9bb>\"Hari itu-\"</color>",
  ui_story_5046_50460601_53_dialog_content = "<color=#e8d9bb>\"Apa yang terjadi... padaku... ibu?\"</color>",
  ui_story_5046_50460601_54_dialog_content = "Aghhhh!",
  ui_story_5046_50460601_55_dialog_content = "Hati? Hati?!",
  ui_story_5046_50460601_56_dialog_content = "Ada yang salah dengan dia, Pak.",
  ui_story_5046_50460601_57_dialog_content = "Ahhhhhhh!",
  ui_story_5046_50460601_58_dialog_content = "Hati! Hati! Bisakah kamu mendengarku?",
  ui_story_5046_50460601_59_dialog_content = "Keluarlah dari sana!",
  ui_story_5046_50460601_60_dialog_content = "Ugh!",
  ui_story_5046_50460601_61_dialog_content = "<color=#e8d9bb>Mendesis-</color>",
  ui_story_5046_50460601_62_dialog_content = "Penampilannya baru saja berubah! Dan dia terbakar?!",
  ui_story_5046_50460601_63_dialog_content = "Hati-hati! Mundur, Kristen!",
  ui_story_5046_50460601_64_dialog_content = "Awooo!!!",
  ui_story_5046_50460601_65_dialog_content = "Hati!!!",
  ui_story_5046_50460601_66_dialog_content = "(Penampilannya sekarang menyerupai setan batin yang saya lihat dalam ingatannya ...)",
  ui_story_5046_50460601_67_dialog_content = "(Apakah itu mengambil alih dia? Tidak mungkin, saya harus mengeluarkannya!)",
  ui_story_5046_50460601_68_dialog_content = "Kemarilah, PlayerName! Hati adalah ancaman berbahaya sekarang!",
  ui_story_5046_50460601_69_dialog_content = "Ya, benar, Hati tidak akan menyakitiku! Dia membutuhkanku sekarang!",
  ui_story_5046_50460601_70_dialog_content = "Anda harus tenang, Hati!",
  ui_story_5046_50460601_71_dialog_content = "Auuu!",
  ui_story_5046_50460601_72_dialog_content = "Berhenti membuang-buang waktu Anda, dia tidak mendengarkan!",
  ui_story_5046_50460601_73_dialog_content = "Ayo cepat kesini, PlayerName!",
  ui_story_5046_50460601_74_dialog_content = "PlayerName…",
  ui_story_5046_50460601_75_dialog_content = "Hati sedang memanggil namaku!",
  ui_story_5046_50460601_76_dialog_content = "Tidak, aku tidak bisa meninggalkannya sendirian!",
  ui_story_5046_50460601_77_dialog_content = "(Apakah ada cara baginya untuk mendengarkan saya...)",
  ui_story_5046_50460601_78_dialog_content = "(Saya mengerti, saya bisa melakukan ini...)",
  ui_story_5046_50460601_79_option_content = "Force Boost!",
  ui_story_5046_50460601_80_dialog_content = "(Tenang, Hati!)",
  ui_story_5046_50460601_81_dialog_content = "(PlayerName? Aku... aku tidak bisa mengendalikan diriku... ketika aku melihat wajah pria itu...)",
  ui_story_5046_50460601_82_dialog_content = "(Kepalaku mulai sakit sekali. Urgh—)",
  ui_story_5046_50460601_83_dialog_content = "(Apa yang akan aku lakukan...?)",
  ui_story_5046_50460601_84_dialog_content = "(Bagaimanapun, kita harus keluar dari sini dan mencari tempat yang tenang untuk bersantai.)",
  ui_story_5046_50460601_85_dialog_content = "(Kami pergi bersama...?)",
  ui_story_5046_50460601_86_dialog_content = "(Bersama!)",
  ui_story_5046_50460601_87_dialog_content = "Jangan biarkan mereka pergi! Aduh!",
  ui_story_5046_50460601_88_dialog_content = "Tetap di tempat, Pak, Anda terluka!",
  ui_story_5046_50460601_89_dialog_content = "Dimana Caelestite?",
  ui_story_5046_50460601_90_dialog_content = "Hati membawanya bersamanya...",
  ui_story_5046_50460601_91_dialog_content = "Tikus, dia lolos lagi!",
  ui_story_5046_50460601_92_dialog_content = "Dimana topengku?",
  ui_story_5046_50460601_93_dialog_content = "Aku akan mengambilkannya untukmu, tetap diam!",
  ui_story_5046_50460601_94_dialog_content = "(Luka di wajahnya...)",
  ui_story_5046_50460601_95_dialog_content = "Oh tidak, api!",
  ui_story_5046_50460601_96_dialog_content = "Nona muda masih di dalam!",
  ui_story_5046_50460601_97_dialog_content = "Apakah seseorang masih di sana?",
  ui_story_5046_50460601_98_dialog_content = "Tolong, Tuan, saya mohon Anda untuk menyelamatkan Nona Kristen!",
  ui_story_5046_50460601_99_dialog_content = "Uhuk, uhuk...",
  ui_story_5046_50460601_100_dialog_content = "Ibu... Ayah... Dimana kau...",
  ui_story_5046_50460601_101_dialog_content = "Kak!",
  ui_story_5046_50460601_102_dialog_content = "Siapa... Siapa ini...",
  ui_story_5046_50460601_103_dialog_content = "Akhirnya menemukanmu akhirnya kau diketemukan. Jangan takut, aku akan mengeluarkanmu dari ini.",
  ui_story_5046_50460601_104_dialog_content = "Apakah Anda baik-baik saja, nona?",
  ui_story_5046_50460601_105_dialog_content = "Aku baik-baik saja, terima kasih—Ah!",
  ui_story_5046_50460601_106_dialog_content = "Oh tidak! Wajahmu terluka parah! Harus segera diobati!",
  ui_story_5046_50460601_107_dialog_content = "Aku? Saya minta maaf untuk menakut-nakuti nona muda.",
  ui_story_5046_50460601_108_dialog_content = "aku minta maaf. Anda menyelamatkan saya hanya untuk saya ...",
  ui_story_5046_50460601_109_dialog_content = "Tidak apa-apa. Aku senang kau baik-baik saja.",
  ui_story_5046_50460601_110_dialog_content = "May aku tanya namamu...?",
  ui_story_5046_50460601_111_dialog_content = "Zenas.",
  ui_story_5046_50460601_112_dialog_content = "Mulai hari ini, saya adalah tutor rumah Anda, nona.",
  ui_story_5046_50460601_113_dialog_content = "Itu bagus, pak!",
  ui_story_5046_50460601_114_dialog_content = "Saya berterima kasih karena Anda menerima bangsawan rendahan seperti saya, serta merekomendasikan saya kepada ayah Anda.",
  ui_story_5046_50460601_115_dialog_content = "Anda seorang bangsawan, tuan?",
  ui_story_5046_50460601_116_dialog_content = "Ya. Lihat, ini lambang keluargaku.",
  ui_story_5046_50460601_117_dialog_content = "Sungguh pola yang unik.",
  ui_story_5046_50460601_118_dialog_content = "Rumah itu telah menurun dan tidak layak disebut lagi.",
  ui_story_5046_50460601_119_dialog_content = "<color=#e8d9bb>\"Sejak saat itu, dia tinggal dan mengajariku.\"</color>",
  ui_story_5046_50460601_120_dialog_content = "<color=#e8d9bb>\"Sampai dia mengundurkan diri dan pergi melayani Lumopolis dalam kapasitas resmi.\"</color>",
  ui_story_5046_50460601_121_dialog_content = "<color=#e8d9bb>\"Setelah saya lulus Dawn Academy, saya bergabung dengan Lumo Hall of Justice dan terus mengikutinya.\"</color>",
  ui_story_5046_50460601_122_dialog_content = "Masker Anda, Pak.",
  ui_story_5046_50460601_123_dialog_content = "Fiuh…",
  ui_story_5046_50460601_124_dialog_content = "Hati membunuh Tuan Hamell dan menculik Caelestite lagi.",
  ui_story_5046_50460601_125_dialog_content = "Kita harus mengirim penjaga untuk mengejar dan memperluas penyelidikan kita.",
  ui_story_5046_50460601_126_dialog_content = "Siap, Pak!",
  ui_story_5046_50460601_127_dialog_content = "Di sinilah Anda keluar dari kasus ini, Kristen.",
  ui_story_5046_50460601_128_dialog_content = "Apa?",
  ui_story_5046_50460601_129_dialog_content = "Menimbang bahwa kasusnya hanya akan bertambah buruk, saya tidak ingin menempatkan Anda dalam bahaya yang lebih besar.",
  ui_story_5046_50460601_130_dialog_content = "Juga, berdasarkan insiden dengan Hamell, saya pikir Anda masih kurang pengalaman untuk berurusan dengan tersangka.",
  ui_story_5046_50460601_131_dialog_content = "Tapi tidak ada yang lebih tertarik dalam kasus ini selain saya kecuali Anda, Pak. Izinkan saya untuk terus membantu Anda!",
  ui_story_5046_50460601_132_dialog_content = "Jangan katakan lagi. Aku akan menangani mereka sendiri.",
  ui_story_5046_50460601_133_dialog_content = "Kumpulkan saja semua temuan sejauh ini dalam satu file dan serahkan ke Balai Kehakiman.",
  ui_story_5046_50460601_134_dialog_content = "Tapi—",
  ui_story_5046_50460601_135_dialog_content = "Cukup! Anda mungkin nona muda saya, tapi saya atasan Anda.",
  ui_story_5046_50460601_136_dialog_content = "Ikuti perintah saya!",
  ui_story_5046_50460601_137_dialog_content = "Ya…",
  ui_story_5046_50460601_138_dialog_content = "Aku mungkin terlalu kasar dengan kata-kataku, tapi itu karena mengkhawatirkan keselamatanmu.",
  ui_story_5046_50460601_139_dialog_content = "Anda harus kembali sekarang.",
  ui_story_5046_50460601_140_dialog_content = "Pertama kali saya dikirim untuk mengikuti tersangka dan saya mengacaukan semuanya.",
  ui_story_5046_50460601_141_dialog_content = "Bahkan jika dia tidak mengizinkanku, aku akan menyelesaikan masalah ini.",
  ui_story_5046_50460601_142_dialog_content = "Belum lagi saya meragukan semua kasus ini ...",
  ui_story_5046_50460601_143_dialog_content = "Jika Hati dimaksudkan untuk menyalakan api, mengapa dia menyelamatkan PlayerName dan gadis kecil itu?",
  ui_story_5046_50460601_144_dialog_content = "Juga, mengapa PlayerName membela Hati dan membantunya melarikan diri saat dia menjadi sandera?",
  ui_story_5046_50460601_145_dialog_content = "Sebelum meninggal, Hamell menyebutkan hal itu Hati memiliki target lain di sampingnya.",
  ui_story_5046_50460601_146_dialog_content = "Cari tahu siapa itu dan aku akan menemukannya Hati.",
  ui_story_5046_50460601_147_dialog_content = "Tuan Zenas, kali ini saya akan membuktikan kepada Anda bahwa saya bukan lagi bunga yang dimanjakan!",
  ui_story_5046_50460601_148_dialog_content = "Saya benar-benar akan menjadi bantuan yang tak ternilai melalui kemampuan saya sendiri!",
  ui_story_5046_50460701_1_dialog_content = "(Ugh, selimut basah adalah yang terburuk.)",
  ui_story_5046_50460701_2_dialog_content = "(Apakah atapnya bocor lagi? Itu tidak pernah terjadi pada rumah lama.)",
  ui_story_5046_50460701_3_dialog_content = "Ibu ibu?",
  ui_story_5046_50460701_4_dialog_content = "(Apakah ibu tertidur?)",
  ui_story_5046_50460701_5_dialog_content = "(Akhir-akhir ini dia sering keluar dan harus memasak dan melakukan pekerjaan rumah ketika sampai di rumah, jadi dia pasti sangat lelah.)",
  ui_story_5046_50460701_6_dialog_content = "(Saya seorang gadis besar sekarang dan tidak dapat menimbulkan masalah bagi Ibu!)",
  ui_story_5046_50460701_7_dialog_content = "(Saya harus mengeringkan selimut sendiri!)",
  ui_story_5046_50460701_8_dialog_content = "(Dia akan sangat senang ketika dia melihat saya melakukan pekerjaan rumah setelah dia bangun!)",
  ui_story_5046_50460701_9_dialog_content = "(Dia akan memanggilku anak yang baik!)",
  ui_story_5046_50460701_10_dialog_content = "<color=#e8d9bb>Ta-tam... Ta-tam...</color>",
  ui_story_5046_50460701_11_dialog_content = "(Fiuh, ini harus dilakukan. Berapa lama Ibu biasanya menggantung selimut?)",
  ui_story_5046_50460701_12_dialog_content = "(Kalau saja sudah kering sebelum Ibu bangun!)",
  ui_story_5046_50460701_13_dialog_content = "Kering, selimut!",
  ui_story_5046_50460701_14_dialog_content = "Selimut, selimut!",
  ui_story_5046_50460701_15_dialog_content = "Keringkan sekarang!",
  ui_story_5046_50460701_16_dialog_content = "<color=#e8d9bb>Mendesis-</color>",
  ui_story_5046_50460701_17_dialog_content = "Woah!",
  ui_story_5046_50460701_18_dialog_content = "Dari mana datangnya api?!",
  ui_story_5046_50460701_19_dialog_content = "Ibu akan marah jika dia melihat ini!",
  ui_story_5046_50460701_20_dialog_content = "Aku harus memadamkan api!",
  ui_story_5046_50460701_21_dialog_content = "Hati? Apa yang sedang kamu lakukan?!",
  ui_story_5046_50460701_22_dialog_content = "Boo-hoo... Bu!",
  ui_story_5046_50460701_23_dialog_content = "(Dia tampak sangat ketakutan... Aku harus minta maaf sekarang!)",
  ui_story_5046_50460701_24_dialog_content = "Maaf, saya hanya ingin mengeringkan selimut...",
  ui_story_5046_50460701_25_dialog_content = "A-aku tidak bermaksud untuk membakarnya... hanya saja...",
  ui_story_5046_50460701_26_dialog_content = "Kau terluka?",
  ui_story_5046_50460701_27_dialog_content = "Tidak... Aku tidak sengaja, Bu...",
  ui_story_5046_50460701_28_dialog_content = "Dan saya tidak bermaksud melakukan apa pun yang Anda tidak ingin saya lakukan ...",
  ui_story_5046_50460701_29_dialog_content = "Oke, ingat jangan pernah menggunakan kekuatanmu lagi!",
  ui_story_5046_50460701_30_dialog_content = "Apa kau mendengarku!?",
  ui_story_5046_50460701_31_dialog_content = "(Ibu sangat galak...)",
  ui_story_5046_50460701_32_dialog_content = "Tapi aku hanya... Aku tidak melakukannya dengan sengaja...",
  ui_story_5046_50460701_33_dialog_content = "Wahhhhh—!",
  ui_story_5046_50460701_34_dialog_content = "Anda masih tidak dapat mengontrol kekuatan sekarang ...",
  ui_story_5046_50460701_35_dialog_content = "Dan itu sangat kuat, cukup untuk menyakitimu jika kamu ceroboh...",
  ui_story_5046_50460701_36_dialog_content = "Ada juga orang yang menginginkan kekuatan dan itu bisa membuatmu terluka juga...",
  ui_story_5046_50460701_37_dialog_content = "Jadi jangan pernah menggunakannya lagi, Anda dengar, Hati?",
  ui_story_5046_50460701_38_dialog_content = "Boo-hoo... Mengerti...",
  ui_story_5046_50460701_39_dialog_content = "(Mama...)",
  ui_story_5046_50460701_40_dialog_content = "<color=#e8d9bb>\"Apakah kamu begitu takut dengan kekuatanku, Bu?\"</color>",
  ui_story_5046_50460701_41_dialog_content = "<color=#e8d9bb>\"Apakah kamu begitu takut padaku, Bu?\"</color>",
  ui_story_5046_50460701_42_dialog_content = "<color=#e8d9bb>\"Tapi aku sangat mencintaimu, Bu!\"</color>",
  ui_story_5046_50460701_43_dialog_content = "Ahhhh!",
  ui_story_5046_50460701_44_dialog_content = "(Mama tidak mau Hati lagi...)",
  ui_story_5046_50460701_45_dialog_content = "(Karena Hati tidak mendengarkannya...)",
  ui_story_5046_50460701_46_dialog_content = "Aku... Ugh... Ibu... Aghhh!",
  ui_story_5046_50460701_47_dialog_content = "Bangun, Hati!",
  ui_story_5046_50460701_48_dialog_content = "(Dia tampaknya terjebak dalam ingatannya.)",
  ui_story_5046_50460701_49_dialog_content = "(Aku bisa merasakan setan batinnya tanpa henti berbisik di telinganya...)",
  ui_story_5046_50460701_50_dialog_content = "Jika Hati tidak bisa menghadapi iblis dalam dirinya secara langsung, dia akan tetap terjebak dalam ingatannya selamanya...",
  ui_story_5046_50460701_51_dialog_content = "Membiarkannya melayang tanpa sadar di masa lalu seperti ini bukanlah pilihan.",
  ui_story_5046_50460701_52_dialog_content = "Aku harus membantunya!",
  ui_story_5046_50460701_53_option_content = "Force Boost!",
  ui_story_5046_50460701_54_dialog_content = "(Ini pasti rumah Hati.)",
  ui_story_5046_50460701_55_dialog_content = "Hati! Apa yang sedang kamu lakukan!?",
  ui_story_5046_50460701_56_dialog_content = "Ibu?",
  ui_story_5046_50460701_57_dialog_content = "Jawab aku—apa yang kamu lakukan!?",
  ui_story_5046_50460701_58_dialog_content = "Aku hanya ingin melihat apa yang dimainkan anak-anak di luar.",
  ui_story_5046_50460701_59_dialog_content = "Menutup jendela! Sekarang!",
  ui_story_5046_50460701_60_dialog_content = "Tapi aku juga ingin keluar dan bermain.",
  ui_story_5046_50460701_61_dialog_content = "Sudah berapa kali aku memberitahumu? Apakah Anda membutuhkan saya untuk mengulanginya?",
  ui_story_5046_50460701_62_dialog_content = "Menangis...",
  ui_story_5046_50460701_63_dialog_content = "Kenapa kau tidak membiarkanku keluar untuk bermain!?",
  ui_story_5046_50460701_64_dialog_content = "Anda selalu mengatakan itu untuk perlindungan saya sendiri!",
  ui_story_5046_50460701_65_dialog_content = "Tapi Anda tidak pernah memberi tahu saya mengapa begitu!",
  ui_story_5046_50460701_66_dialog_content = "...",
  ui_story_5046_50460701_67_dialog_content = "Tempat baru tempat kami pindah ini sangat kumuh dan dingin! Di sini mengerikan!",
  ui_story_5046_50460701_68_dialog_content = "Apa kau tidak punya buku bergambar itu? Pergi dan baca sendiri.",
  ui_story_5046_50460701_69_dialog_content = "Tapi saya sudah membaca semua buku itu berkali-kali!",
  ui_story_5046_50460701_70_dialog_content = "Anak-anak di buku itu bisa bermain bersama dan saling mengunjungi...",
  ui_story_5046_50460701_71_dialog_content = "Anda menggunakan buku bergambar itu untuk mengajari saya cara berbicara dengan orang, membeli barang, dan mengucapkan terima kasih...",
  ui_story_5046_50460701_72_dialog_content = "...",
  ui_story_5046_50460701_73_dialog_content = "Tapi saya belum punya kesempatan untuk menggunakannya sama sekali!",
  ui_story_5046_50460701_74_dialog_content = "Karena Anda tidak akan membiarkan saya keluar!",
  ui_story_5046_50460701_75_dialog_content = "Aku mengajarimu semua hal ini karena...",
  ui_story_5046_50460701_76_dialog_content = "Saya harap Anda akan dapat menjaga diri sendiri suatu hari nanti, ketika saya tidak ada lagi.",
  ui_story_5046_50460701_77_dialog_content = "Kenapa kamu tidak ada lagi?",
  ui_story_5046_50460701_78_dialog_content = "...",
  ui_story_5046_50460701_79_dialog_content = "Mengapa ibu terlihat sangat sedih?",
  ui_story_5046_50460701_80_dialog_content = "Apakah seseorang jahat kepada Anda?",
  ui_story_5046_50460701_81_dialog_content = "Aku sudah dewasa!",
  ui_story_5046_50460701_82_dialog_content = "Jika seseorang menggertakmu, aku akan memukul mereka semua sampai mereka kabur!",
  ui_story_5046_50460701_83_dialog_content = "Dan jika saya tidak bisa memukul semuanya, saya akan membakarnya!",
  ui_story_5046_50460701_84_dialog_content = "!!!",
  ui_story_5046_50460701_85_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5046_50460701_86_dialog_content = "M... Ibu?",
  ui_story_5046_50460701_87_dialog_content = "Bukankah aku sudah memberitahumu bahwa kamu tidak bisa melakukan itu !?",
  ui_story_5046_50460701_88_dialog_content = "Ibu... kau memukulku...",
  ui_story_5046_50460701_89_dialog_content = "Beri tahu saya! Kenapa aku tidak bisa!?",
  ui_story_5046_50460701_90_dialog_content = "Mengapa mengapa mengapa!?",
  ui_story_5046_50460701_91_dialog_content = "(Katakan padaku... Kenapa aku tidak bisa...)",
  ui_story_5046_50460701_92_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5046_50460701_93_dialog_content = "?!",
  ui_story_5046_50460701_94_dialog_content = "Wow!",
  ui_story_5046_50460701_95_dialog_content = "Hati, Anda...!",
  ui_story_5046_50460701_96_dialog_content = "Ibu? Tubuhku... terbakar...",
  ui_story_5046_50460701_97_dialog_content = "Ibu memiliki liontin seperti milikku.",
  ui_story_5046_50460701_98_dialog_content = "Untuk apa liontin ini?",
  ui_story_5046_50460701_99_dialog_content = "Liontin ini sangat penting.",
  ui_story_5046_50460701_100_dialog_content = "Jadi jaga baik-baik.",
  ui_story_5046_50460701_101_dialog_content = "Oh!",
  ui_story_5046_50460701_102_dialog_content = "Tapi mengapa liontin ini begitu penting?",
  ui_story_5046_50460701_103_dialog_content = "... Liontin itu... penting...",
  ui_story_5046_50460701_104_dialog_content = "... liontin ... di ...",
  ui_story_5046_50460701_105_dialog_content = "(Bagian ingatannya yang ini sangat kabur...)",
  ui_story_5046_50460701_106_dialog_content = "Bu, apa yang kamu lakukan? Anda terlihat stres.",
  ui_story_5046_50460701_107_dialog_content = "Ulang tahun saya hari ini! Saya ingin makan kue stroberi!",
  ui_story_5046_50460701_108_dialog_content = "... Hati... dengarkan aku.",
  ui_story_5046_50460701_109_dialog_content = "Sudah terlambat... Sudah terlambat untuk pembicaraan seperti itu. Tidak ada waktu.",
  ui_story_5046_50460701_110_dialog_content = "Ambil liontin ini, simpan di dekatmu dan jangan pernah kehilangannya!",
  ui_story_5046_50460701_111_dialog_content = "Bu, apa yang kamu katakan? Saya tidak mengerti.",
  ui_story_5046_50460701_112_dialog_content = "Orang jahat... Orang yang sangat jahat akan datang untukmu.",
  ui_story_5046_50460701_113_dialog_content = "Orang jahat? Siapa?",
  ui_story_5046_50460701_114_dialog_content = "Bu, siapa orang jahat ini?",
  ui_story_5046_50460701_115_dialog_content = "Bu, apa yang akan kamu lakukan? Mama?",
  ui_story_5046_50460701_116_dialog_content = "Ah-!",
  ui_story_5046_50460701_117_dialog_content = "<color=#e8d9bb>\"Bu, siapa orang jahat ini?\"</color>",
  ui_story_5046_50460701_118_dialog_content = "<color=#e8d9bb>\"Kenapa orang jahat itu datang dan melakukan ini pada kita...?\"</color>",
  ui_story_5046_50460701_119_dialog_content = "<color=#e8d9bb>\"Apakah Mom berpikir... aku orang jahat?\"</color>",
  ui_story_5046_50460701_120_dialog_content = "<color=#e8d9bb>\"Itukah sebabnya dia membakarku...?\"</color>",
  ui_story_5046_50460701_121_dialog_content = "<color=#e8d9bb>\"Apakah aku benar, Bu?\"</color>",
  ui_story_5046_50460701_122_dialog_content = "(Akhirnya aku mengerti... Hati...)",
  ui_story_5046_50460701_123_dialog_content = "(Orang jahat yang Ibu bicarakan... Itu kamu...)",
  ui_story_5046_50460701_124_dialog_content = "(Aku benci kekuatan ini... Kekuatan ini... menelan kita utuh...)",
  ui_story_5046_50460701_125_dialog_content = "Kita...?",
  ui_story_5046_50460701_126_dialog_content = "Hati! Hati!",
  ui_story_5046_50460701_127_dialog_content = "Siapa itu...?",
  ui_story_5046_50460701_128_dialog_content = "Ini aku! PlayerName!",
  ui_story_5046_50460701_129_dialog_content = "PlayerName? Anda ingin ... meninggalkan saya juga?",
  ui_story_5046_50460701_130_dialog_content = "(PlayerName... Kesayanganmu PlayerName...)",
  ui_story_5046_50460701_131_dialog_content = "(Dia juga akan meninggalkanmu...)",
  ui_story_5046_50460701_132_dialog_content = "(Siapa yang menginginkan seseorang yang selalu membakar segalanya...? Seseorang yang tidak bisa mengendalikan apinya sendiri...)",
  ui_story_5046_50460701_133_dialog_content = "(Seseorang yang selalu membuat ibunya marah... Sampai akhirnya dia menelantarkannya... Hati...)",
  ui_story_5046_50460701_134_dialog_content = "Ibu tidak mencintaiku... tidak ada yang akan...",
  ui_story_5046_50460701_135_dialog_content = "Bukannya begitu, sih!",
  ui_story_5046_50460701_136_dialog_content = "Setiap kali Anda menggunakan kekuatan Anda, itu untuk orang-orang penting bagi Anda!",
  ui_story_5046_50460701_137_dialog_content = "Untuk menghentikan Eclipsites menyakiti ibumu... Keringkan selimutmu sendiri, agar ibumu bisa lebih banyak istirahat...",
  ui_story_5046_50460701_138_dialog_content = "Menyelamatkanku dari gerombolan Eclipsites saat aku tak berdaya melawan mereka...",
  ui_story_5046_50460701_139_dialog_content = "Menggunakan kekuatan terlarangmu demi orang-orang yang kau sayangi...",
  ui_story_5046_50460701_140_dialog_content = "Tidak bisakah kamu melihat, Hati? Kamu gadis yang sangat baik dan perhatian!",
  ui_story_5046_50460701_141_dialog_content = "Itu yang aku suka darimu!",
  ui_story_5046_50460701_142_dialog_content = "Dan aku tahu ibumu pasti merasakan hal yang sama!",
  ui_story_5046_50460701_143_dialog_content = "Bagaimana mungkin ibumu tidak mencintai anak yang baik dan penyayang sepertimu?",
  ui_story_5046_50460701_144_dialog_content = "Ibu ... mencintaiku?",
  ui_story_5046_50460701_145_dialog_content = "(Dia berbohong padamu...)",
  ui_story_5046_50460701_146_dialog_content = "Semua yang saya katakan itu benar!",
  ui_story_5046_50460701_147_dialog_content = "Kau pembohong! Semua yang telah Anda lakukan adalah air mata Hati turun! Kamu orang jahat!",
  ui_story_5046_50460701_148_dialog_content = "Hati, mari kita kalahkan orang jahat ini bersama-sama!",
  ui_story_5046_50460702_1_dialog_content = "Saya menang?",
  ui_story_5046_50460702_2_dialog_content = "(Apakah kamu menang...?)",
  ui_story_5046_50460702_3_dialog_content = "(Tidak... Kamu masih di sini... Aku masih di sini...)",
  ui_story_5046_50460702_4_dialog_content = "(Kamu masih tidak bisa... benar-benar... menerima dirimu sendiri...)",
  ui_story_5046_50460702_5_dialog_content = "Apa yang kamu?",
  ui_story_5046_50460702_6_dialog_content = "(Kita akan bertemu lagi...)",
  ui_story_5046_50460702_7_dialog_content = "Hati!",
  ui_story_5046_50460702_8_dialog_content = "Urgh... hufff...",
  ui_story_5046_50460702_9_dialog_content = "Hmm? PlayerName...?",
  ui_story_5046_50460702_10_dialog_content = "Brilian, Anda akhirnya bangun.",
  ui_story_5046_50460702_11_dialog_content = "...",
  ui_story_5046_50460702_12_dialog_content = "Terima kasih. Anda baru saja menyelamatkan saya lagi.",
  ui_story_5046_50460702_13_dialog_content = "Anda tidak perlu berterima kasih kepada saya. Anda baru saja menyelamatkan saya dari Eclipsites!",
  ui_story_5046_50460702_14_dialog_content = "...",
  ui_story_5046_50460702_15_dialog_content = "Saya ingin mendapatkan liontin saya kembali dari pria bertopeng itu karena itu milik ibu saya.",
  ui_story_5046_50460702_16_dialog_content = "Sejak saya masih kecil, saya selalu berbeda dari orang lain. Saya hanya bisa melihat mereka dari kejauhan melalui jendela, dan tidak pernah diizinkan keluar.",
  ui_story_5046_50460702_17_dialog_content = "Di duniaku, hanya ada ibuku.",
  ui_story_5046_50460702_18_dialog_content = "Dia bermain-main denganku, mengajariku membaca, membacakan cerita untukku... Ibuku adalah segalanya bagiku.",
  ui_story_5046_50460702_19_dialog_content = "Aku sangat mencintainya, tapi ibuku... Mungkin dia tidak mencintaiku seperti aku mencintainya.",
  ui_story_5046_50460702_20_dialog_content = "Bagaimana Anda bisa mengatakan itu...?",
  ui_story_5046_50460702_21_dialog_content = "Sejauh yang saya ingat, kami selalu bergerak, dan tidak pernah tinggal di satu tempat terlalu lama.",
  ui_story_5046_50460702_22_dialog_content = "Ibuku sering menatapku dengan sedikit ketakutan di matanya, dan dia tidak pernah membiarkanku keluar.",
  ui_story_5046_50460702_23_dialog_content = "Rumah terakhir kami adalah rumah yang paling lama kami tinggali. Itu juga tempat masa kecilku berakhir...",
  ui_story_5046_50460702_24_dialog_content = "Hati...",
  ui_story_5046_50460702_25_dialog_content = "Saya selalu mencoba melarikan diri, untuk menghindari mengingat hari itu. Tapi bagaimana saya bisa lupa?",
  ui_story_5046_50460702_26_dialog_content = "26 Agustus. Hari itu... adalah hari ulang tahunku.",
  ui_story_5046_50460702_27_dialog_content = "?!",
  ui_story_5046_50460702_28_dialog_content = "Hati...",
  ui_story_5046_50460702_29_dialog_content = "Meskipun kadang-kadang ibu saya bisa keras, dia sangat baik kepada saya.",
  ui_story_5046_50460702_30_dialog_content = "Dia selalu ingat hari ulang tahunku dan menyiapkan semuanya satu hari sebelumnya. Dia bahkan membuat kue krim stroberi denganku...",
  ui_story_5046_50460702_31_dialog_content = "Hari itu, Ibu bangun pagi seperti biasanya, tapi suasana hatinya tampak aneh.",
  ui_story_5046_50460702_32_dialog_content = "Dia hanya mengucapkan selamat ulang tahun kepadaku dan kemudian mulai menyibukkan diri di sekitar rumah seperti sedang mempersiapkan sesuatu.",
  ui_story_5046_50460702_33_dialog_content = "Saya terus bertanya apakah saya boleh makan kue itu, tetapi ibu saya tidak menjawab.",
  ui_story_5046_50460702_34_dialog_content = "Kemudian dia melemparkan saya ke perapian. Dia mencoba membakarku hidup-hidup.",
  ui_story_5046_50460702_35_dialog_content = "Mengapa dia melakukan itu!?",
  ui_story_5046_50460702_36_dialog_content = "Aku benar-benar tidak ingat apa yang terjadi setelah dia melemparkanku ke dalam api. Ketika saya bangun, saya berada di panti asuhan.",
  ui_story_5046_50460702_37_dialog_content = "Itu adalah pertama kalinya saya bergaul dengan begitu banyak anak ...",
  ui_story_5046_50460702_38_dialog_content = "Saya selalu ingin keluar dan bermain dengan anak-anak lain, tetapi saya tidak pernah membayangkan hal ini akan terjadi.",
  ui_story_5046_50460702_39_dialog_content = "Saya belajar bergaul dengan anak-anak lain dan orang dewasa di panti asuhan, tetapi mereka tidak ramah.",
  ui_story_5046_50460702_40_dialog_content = "Anak-anak selalu bertengkar satu sama lain, dan orang dewasa sangat kejam kepada kami.",
  ui_story_5046_50460702_41_dialog_content = "Di sana mengerikan, dan saya hanya ingin mengeluh kepada ibu saya, tetapi saya tidak tahu di mana dia berada.",
  ui_story_5046_50460702_42_dialog_content = "Saat itulah aku menyadari... bahwa dia telah meninggalkanku.",
  ui_story_5046_50460702_43_dialog_content = "Suatu malam, orang-orang di panti asuhan mencoba melakukan sesuatu kepadaku ketika aku sedang tidur. Saya mencoba membebaskan diri dengan sekuat tenaga, dan seseorang memotong telinga saya.",
  ui_story_5046_50460702_44_dialog_content = "Sepotong telinga saya lepas, begitu saja. Saya belum pernah merasakan begitu banyak rasa sakit sebelumnya.",
  ui_story_5046_50460702_45_dialog_content = "Saya tidak bisa mengendalikan emosi saya—saya melampiaskan amarah saya dan membakar seluruh panti asuhan.",
  ui_story_5046_50460702_46_dialog_content = "Seperti yang Anda tahu, saya dikirim ke Shadowlord setelah ini dan dia melepaskan saya dua bulan yang lalu.",
  ui_story_5046_50460702_47_dialog_content = "Hati...",
  ui_story_5046_50460702_48_dialog_content = "Tidak ada yang namanya ibu yang tidak menyayangi anaknya.",
  ui_story_5046_50460702_49_dialog_content = "Saya yakin dia ingin Anda menjalani kehidupan yang baik, apa pun yang terjadi.",
  ui_story_5046_50460702_50_dialog_content = "Anda tidak perlu mencoba membuat saya merasa lebih baik, PlayerName.",
  ui_story_5046_50460702_51_dialog_content = "Jika ibuku mencintaiku, mengapa dia melemparkanku ke perapian itu?",
  ui_story_5046_50460702_52_dialog_content = "Aku tahu bukan itu yang sebenarnya kau pikirkan jauh di lubuk hatimu, benar, Hati?",
  ui_story_5046_50460702_53_dialog_content = "Kalau tidak, mengapa Anda berusaha keras untuk menemukan ingatan yang hilang itu?",
  ui_story_5046_50460702_54_dialog_content = "Kamu harus percaya bahwa ibumu masih mencintaimu, di suatu tempat di hatimu.",
  ui_story_5046_50460702_55_dialog_content = "...",
  ui_story_5046_50460702_56_dialog_content = "... Hmn.",
  ui_story_5046_50460702_57_dialog_content = "Saat aku baru saja kehilangan kendali atas diriku, kenapa kau tidak pergi dengan yang lain di tengah semua kekacauan?",
  ui_story_5046_50460702_58_dialog_content = "Karena... Saya pikir Anda mungkin membutuhkan bantuan saya.",
  ui_story_5046_50460702_59_dialog_content = "Selain Grimme, tidak ada yang akan berusaha keras untuk membantuku.",
  ui_story_5046_50460702_60_dialog_content = "Wajar jika teman saling mendukung.",
  ui_story_5046_50460702_61_dialog_content = "Teman-teman? Saya tidak punya teman.",
  ui_story_5046_50460702_62_dialog_content = "Mulai sekarang, kamu bisa memanggilku temanmu.",
  ui_story_5046_50460702_63_dialog_content = "Anda telah mencari ingatan Anda selama dua bulan penuh sejak Anda meninggalkan Shadowlord.",
  ui_story_5046_50460702_64_dialog_content = "Tapi masih ada dunia yang begitu besar di luar sana, menunggu untuk Anda jelajahi.",
  ui_story_5046_50460702_65_dialog_content = "Ketika Anda mendapatkan ingatan Anda kembali, Anda dipersilakan untuk datang dan bergaul dengan saya di Colossus!",
  ui_story_5046_50460702_66_dialog_content = "Kita bisa keliling dunia dan mengganti waktu yang dulu tidak boleh kamu jalani!",
  ui_story_5046_50460702_67_dialog_content = "...",
  ui_story_5046_50460702_68_dialog_content = "Jadi, bagaimana menurutmu?",
  ui_story_5046_50460702_69_dialog_content = "...",
  ui_story_5046_50460702_70_dialog_content = "Tentu.",
  ui_story_5046_50460801_1_dialog_content = "(Kata-kata terakhir Mr. Hamell dan satu-satunya orang yang selamat yang disebutkannya—semuanya berhubungan dengan panti asuhan.)",
  ui_story_5046_50460801_2_dialog_content = "(Tidak ada petunjuk lain yang tersedia saat ini. Para tersangka Hati Dan PlayerName juga melarikan diri.)",
  ui_story_5046_50460801_3_dialog_content = "(Seperti yang terjadi, satu-satunya pilihan saya adalah terus mencari ke panti asuhan.)",
  ui_story_5046_50460801_4_dialog_content = "(Hampir tidak ada jejak masa lalu yang tersisa setelah panti asuhan dibangun kembali. Sekarang, hanya anak-anak yang tersisa dari tahun itu yang belum diselidiki.)",
  ui_story_5046_50460801_5_dialog_content = "Anda seorang hakim? Apakah Anda yakin Anda mendapatkan orang yang tepat? aku hanya seorang hamba...",
  ui_story_5046_50460801_6_dialog_content = "(Hanya ada dua orang yang bisa kutemukan catatannya di arsip. Sepertinya gadis ini dua tahun lebih tua darinya Hati.)",
  ui_story_5046_50460801_7_dialog_content = "(Setelah kebakaran, dia dikirim untuk tinggal bersama keluarga angkat di dekatnya. Sekarang, dia menjadi pembantu keluarga bangsawan di Lumopolis.)",
  ui_story_5046_50460801_8_dialog_content = "Tolong, tidak perlu gugup. Saya hanya ingin tahu tentang kebakaran di Panti Asuhan Umbraton.",
  ui_story_5046_50460801_9_dialog_content = "Sejauh yang saya tahu, Anda tinggal di sana cukup lama.",
  ui_story_5046_50460801_10_dialog_content = "Mereka menanyakan semua pertanyaan ini berkali-kali sebelumnya... Mengapa ini terjadi lagi?",
  ui_story_5046_50460801_11_dialog_content = "Aku tertidur lelap malam itu... sampai aku dibangunkan oleh teriakan anak-anak lain. Ketika saya bangun, seluruh tempat sudah dilalap api.",
  ui_story_5046_50460801_12_dialog_content = "Gadis baru itu, sang demi-human—seluruh tubuhnya terbakar. Anak laki-laki di tempat tidur di sebelah saya mengatakan bahwa dialah yang memulai semuanya.",
  ui_story_5046_50460801_13_dialog_content = "Saya bergegas keluar dari sana, saya tidak bisa benar-benar memperhatikan hal lain.",
  ui_story_5046_50460801_14_dialog_content = "(Hmm... Persis sama dengan pernyataannya sebelumnya. Ini semua adalah informasi yang diketahui.)",
  ui_story_5046_50460801_15_dialog_content = "Apakah Anda memperhatikan pada saat apakah demi-human ini bernama Hati pernah berdebat dengan siapa pun di panti asuhan?",
  ui_story_5046_50460801_16_dialog_content = "Atau apakah dia menyimpan keluhan terhadap para guru, administrator, atau orang lain di panti asuhan?",
  ui_story_5046_50460801_17_dialog_content = "Saya tidak yakin, saya tidak mendengar apapun.",
  ui_story_5046_50460801_18_dialog_content = "Tapi balas dendam...? Berapa umurnya saat itu? Dia bahkan tidak setua saya.",
  ui_story_5046_50460801_19_dialog_content = "Dan dia baru berada di panti asuhan selama sebulan. Siapa yang bisa dia jadikan musuh dalam waktu sesingkat itu?",
  ui_story_5046_50460801_20_dialog_content = "Jika Anda benar-benar berpikir itu mungkin, beberapa anak lebih besar dari yang lain dan suka memaksakan diri untuk menggertak orang agar melakukan apa yang mereka inginkan.",
  ui_story_5046_50460801_21_dialog_content = "Gadis demi-human itu terlalu kecil untuk melawan anak-anak besar itu...",
  ui_story_5046_50460801_22_dialog_content = "Dan para guru di sana tidak peduli dengan perselisihan antara anak-anak, mereka tidak sabar atau baik hati...",
  ui_story_5046_50460801_23_dialog_content = "Saya rasa tidak ada di antara kita yang menyukai staf di sana?",
  ui_story_5046_50460801_24_dialog_content = "Ngomong-ngomong, ada satu hal lagi yang ingin saya tanyakan.",
  ui_story_5046_50460801_25_dialog_content = "Apakah Anda tetap berhubungan dengan salah satu anak yang diadopsi dari panti asuhan?",
  ui_story_5046_50460801_26_dialog_content = "Tingkat adopsi di panti asuhan sangat tinggi, tetapi tidak ada catatan untuk anak adopsi dan tidak ada bukti kunjungan kembali...",
  ui_story_5046_50460801_27_dialog_content = "Saya tidak terus berhubungan dengan siapa pun.",
  ui_story_5046_50460801_28_dialog_content = "Saat itu, kami biasa bercanda bahwa ketika mereka datang untuk membawa pergi delapan atau sembilan anak setiap bulan, mereka diberi makan ke Eclipsites.",
  ui_story_5046_50460801_29_dialog_content = "Delapan atau sembilan anak diadopsi setiap bulan...",
  ui_story_5046_50460801_30_dialog_content = "(Ini memang situasi yang tidak normal...)",
  ui_story_5046_50460801_31_dialog_content = "Maaf telah menyita waktu Anda. Terima kasih banyak.",
  ui_story_5046_50460801_32_dialog_content = "(Orang yang selamat berikutnya adalah anak laki-laki seusia dengan Hati.)",
  ui_story_5046_50460801_33_dialog_content = "(Menurut catatan, dia mengelola toko roti dengan orang tua angkatnya setelah dia diadopsi.)",
  ui_story_5046_50460801_34_dialog_content = "Anda seorang hakim? Aku tidak melakukan apa-apa!",
  ui_story_5046_50460801_35_dialog_content = "Tolong, tidak perlu gugup seperti itu. Saya ingin memahami apa yang terjadi terkait kebakaran di Panti Asuhan Umbraton.",
  ui_story_5046_50460801_36_dialog_content = "Hah? Itu semua sudah lama terjadi, tapi kau masih menyelidikinya, eh?",
  ui_story_5046_50460801_37_dialog_content = "Tapi saya khawatir Anda kurang beruntung—saya tidak bisa memberi tahu Anda sesuatu yang baru. Semua yang dapat saya ingat telah diturunkan dalam pernyataan saya.",
  ui_story_5046_50460801_38_dialog_content = "Jadi jika memungkinkan, saya harap Anda tidak menakut-nakuti pelanggan saya.",
  ui_story_5046_50460801_39_dialog_content = "Anu…",
  ui_story_5046_50460801_40_dialog_content = "Jika Anda dapat membantu saya dengan mengingat lebih banyak tentang apa yang terjadi, saya akan membeli semua roti di toko roti Anda.",
  ui_story_5046_50460801_41_dialog_content = "Sungguh!?",
  ui_story_5046_50460801_42_dialog_content = "Nah, sekarang setelah Anda menyebutkannya, saya mungkin dapat mengingat beberapa detail lagi.",
  ui_story_5046_50460801_43_dialog_content = "Terima kasih atas kerja sama anda. Anda mengatakan itu Hati nyalakan api. Bisakah Anda menjelaskan apa yang terjadi secara lebih rinci?",
  ui_story_5046_50460801_44_dialog_content = "Malam itu... Aku selalu tidur sangat nyenyak sejak aku masih kecil, jadi aku bangun segera setelah mendengar demi-human itu mulai berteriak.",
  ui_story_5046_50460801_45_dialog_content = "Tempat tidurku cukup jauh dari tempat tidurnya. Saya tidak melihat apa yang terjadi, tetapi dia mulai marah setelah teriakan itu.",
  ui_story_5046_50460801_46_dialog_content = "Kemudian api di sekujur tubuhnya membakar tirai. Api mulai membesar dan membesar, dan anak-anak lain akhirnya terbangun.",
  ui_story_5046_50460801_47_dialog_content = "Saya berlari untuk itu, bersama dengan semua anak lainnya, tetapi kaki saya terbakar. Saya mengatakan semua ini sebelumnya ketika mereka menanyakan saya pertama kali.",
  ui_story_5046_50460801_48_dialog_content = "Lalu, tahukah Anda apakah Hati, demi-human, telah membuat musuh di panti asuhan?",
  ui_story_5046_50460801_49_dialog_content = "Para korban serangan pembakaran baru-baru ini semuanya terkait dengan panti asuhan. Saya ingin tahu apakah mereka menyimpan dendam Hati.",
  ui_story_5046_50460801_50_dialog_content = "Selalu ada anak-anak baru yang muncul di panti asuhan, tetapi sebagian besar akhirnya diusir sebelum mereka benar-benar bisa mengenal siapa pun.",
  ui_story_5046_50460801_51_dialog_content = "Jika bukan karena fakta bahwa dia adalah demi-human, aku bahkan tidak akan ingat siapa dia, apalagi dia tidak cocok dengan siapa.",
  ui_story_5046_50460801_52_dialog_content = "Adapun orang-orang yang mengelola panti asuhan ...",
  ui_story_5046_50460801_53_dialog_content = "Mereka harus berurusan dengan sekelompok besar anak nakal yang berisik setiap hari, dan tidak satupun dari mereka adalah milik mereka sendiri.",
  ui_story_5046_50460801_54_dialog_content = "Bahkan jika mereka terlihat cukup ramah di permukaan, siapa yang tahu seperti apa mereka sebenarnya di balik pintu tertutup?",
  ui_story_5046_50460801_55_dialog_content = "(Sepertinya semua orang punya kesan buruk terhadap staf panti asuhan...)",
  ui_story_5046_50460801_56_dialog_content = "Apakah Anda memiliki kontak dengan anak-anak lain yang diadopsi dari panti asuhan?",
  ui_story_5046_50460801_57_dialog_content = "Atau apakah Anda memiliki rincian kontak dari salah satu keluarga angkat?",
  ui_story_5046_50460801_58_dialog_content = "Saya kehilangan kontak dengan semua orang setelah mereka diadopsi.",
  ui_story_5046_50460801_59_dialog_content = "Adapun detail kontak keluarga angkat ...",
  ui_story_5046_50460801_60_dialog_content = "Bukankah itu sesuatu yang seharusnya dicatat oleh sutradara?",
  ui_story_5046_50460801_61_dialog_content = "Anda tahu, saya dulu melihat para guru di panti asuhan menatap anak-anak tertentu, menulis dan menggambar di buku catatan mereka.",
  ui_story_5046_50460801_62_dialog_content = "Dan ketika waktu adopsi tiba, itulah anak-anak yang diusir.",
  ui_story_5046_50460801_63_dialog_content = "Kalau dipikir-pikir, buku catatan itu seharusnya berisi banyak informasi tentang anak angkat, bukan? Entahlah—Anda seorang hakim, Anda harus memiliki wewenang untuk memeriksa mereka, bukan?",
  ui_story_5046_50460801_64_dialog_content = "Sayangnya, tampaknya semuanya hancur dalam api.",
  ui_story_5046_50460801_65_dialog_content = "Bagaimanapun, terima kasih atas kerja sama Anda. Saya akan mengambil semua roti yang Anda miliki.",
  ui_story_5046_50460801_66_dialog_content = "(Fiuh, aku berhasil menangani jumlah roti yang sangat besar itu. Tapi sekarang...)",
  ui_story_5046_50460801_67_dialog_content = "(Masih ada masalah anak angkat yang menghilang, dan Hati, yang dituduh sebagai pembunuh ketika dia masih kecil.)",
  ui_story_5046_50460801_68_dialog_content = "(Panti asuhan macam apa yang berhasil mengadopsi begitu banyak anak setiap bulan, dan kemudian mereka semua menghilang tanpa jejak?)",
  ui_story_5046_50460801_69_dialog_content = "(Skenario terburuknya adalah mereka menggunakannya untuk sesuatu...)",
  ui_story_5046_50460801_70_dialog_content = "(Itu adalah pemikiran yang mengerikan... tapi jika itu benar, Hati hanya alasan untuk menyalakan api dan membunuh Mr. Hamell.)",
  ui_story_5046_50460801_71_dialog_content = "(Memikirkannya membuatku bergidik. Berapa banyak rahasia yang tersembunyi di panti asuhan tua itu?)",
  ui_story_5046_50460801_72_dialog_content = "Oh...",
  ui_story_5046_50460801_73_dialog_content = "Perhatikan langkahmu, nona.",
  ui_story_5046_50460801_74_dialog_content = "Terima kasih…",
  ui_story_5046_50460801_75_dialog_content = "Grimme namanya. Saya pemilik Firefly Bar, tidak jauh dari sini.",
  ui_story_5046_50460801_76_dialog_content = "Suram? Bukankah kamu teman Hati? Tuan Zenas menyebutmu.",
  ui_story_5046_50460801_77_dialog_content = "Oh, jadi Anda pernah mendengar tentang saya? Dengar, apakah kamu keberatan jika kita menyimpan obrolan ringan untuk nanti? Sebenarnya ada sesuatu yang saya ingin tahu apakah Anda dapat membantu saya.",
  ui_story_5046_50460801_78_dialog_content = "Apa…?",
  ui_story_5046_50460801_79_dialog_content = "Graaahh—!",
  ui_story_5046_50460801_80_dialog_content = "!!!",
  ui_story_5046_50460801_81_dialog_content = "Aku baru saja selesai berurusan dengan beberapa hal kotor di pinggiran kota.",
  ui_story_5046_50460801_82_dialog_content = "Gerhana!? Awas di belakangmu!",
  ui_story_5046_50460802_1_dialog_content = "Terima kasih, nona muda. Jika Anda tidak di sini untuk membantu sekarang, Eclipsites itu akan mempersingkat saya.",
  ui_story_5046_50460802_2_dialog_content = "Itu bukan apa-apa. Ngomong-ngomong, saya ingin menanyakan sesuatu tentang Hati.",
  ui_story_5046_50460802_3_dialog_content = "Tentu. Firefly Bar ada di sudut di depan. Mari kita duduk dan mengobrol sambil minum.",
  ui_story_5046_50460802_4_dialog_content = "<color=#e8d9bb>Ding—!</color>",
  ui_story_5046_50460802_5_dialog_content = "Maaf untuk ketidaknyamanannya.",
  ui_story_5046_50460802_6_dialog_content = "Anda baru saja membuat saya benar-benar solid, nona. Inilah yang paling bisa saya lakukan.",
  ui_story_5046_50460802_7_dialog_content = "Silahkan duduk. Ini belum jam kerja. Anda mau minum apa?",
  ui_story_5046_50460802_8_dialog_content = "Saya sedang bertugas, dan saya tidak minum.",
  ui_story_5046_50460802_9_dialog_content = "Selain alkohol, kami juga memiliki berbagai minuman ringan yang sangat enak di sini.",
  ui_story_5046_50460802_10_dialog_content = "Ada Blue Storm, Umbraton Delight, White Night Iced Tea...",
  ui_story_5046_50460802_11_dialog_content = "Tidak terima kasih. Mari kita langsung ke intinya.",
  ui_story_5046_50460802_12_dialog_content = "Bagaimana Anda dan Hati bertemu?",
  ui_story_5046_50460802_13_dialog_content = "Nah, dia bekerja di sini dengan saya, bukan?",
  ui_story_5046_50460802_14_dialog_content = "Dia biasanya menangani memasukkan bahan-bahan, membersihkan dapur... banyak pekerjaan yang berbeda, kok. Dia tidak banyak bicara, tapi dia pekerja keras.",
  ui_story_5046_50460802_15_dialog_content = "Dimana Hati kapan kebakaran baru-baru ini terjadi?",
  ui_story_5046_50460802_16_dialog_content = "Sekarang itu sama sekali bukan yang baru, saya tidak bisa mengingatnya dengan benar.",
  ui_story_5046_50460802_17_dialog_content = "Namun, saya mengingat ini suatu hari dengan sangat jelas. Itu adalah hari pembelian.",
  ui_story_5046_50460802_18_dialog_content = "Hati seharian sibuk di dapur, menghitung stok dan memeriksa kesegaran bahan. Dia tidak mendapatkan kesempatan untuk beristirahat sampai malam.",
  ui_story_5046_50460802_19_dialog_content = "(Ini adalah hari pembunuhan Fairmont. Menurut kesaksian Grimme, Hati tidak memiliki kesempatan untuk melakukan pembunuhan.)",
  ui_story_5046_50460802_20_dialog_content = "(Namun, Grimme mungkin berusaha melindungi Hati.)",
  ui_story_5046_50460802_21_dialog_content = "Nona, tolong percaya padaku. Aku mengatakan yang sebenarnya.",
  ui_story_5046_50460802_22_dialog_content = "Anda bisa memanggil saya Kristen.",
  ui_story_5046_50460802_23_dialog_content = "Kembali ke Hati—apakah Anda memiliki informasi lain tentang dia yang dapat Anda bagikan dengan saya?",
  ui_story_5046_50460802_24_dialog_content = "Misalnya, apakah dia pernah menyebutkan menyimpan dendam terhadap siapa pun? Apakah dia pernah menyebutkan balas dendam atau yang serupa?",
  ui_story_5046_50460802_25_dialog_content = "Seperti yang saya katakan, Hati tidak banyak bicara. Kami belum lama berkenalan, tapi aku belum pernah mendengar dia menyebutkan hal seperti itu selama aku mengenalnya.",
  ui_story_5046_50460802_26_dialog_content = "(Ini sepertinya tidak membawa saya kemana-mana.)",
  ui_story_5046_50460802_27_dialog_content = "Dalam hal ini, saya tidak akan menyusahkan Anda lebih jauh. Selamat tinggal.",
  ui_story_5046_50460802_28_dialog_content = "Anda akan pergi tanpa mencoba jus buatan sendiri yang saya buat khusus untuk Anda?",
  ui_story_5046_50460802_29_dialog_content = "Anda sepertinya tidak tertarik dengan minuman yang saya sebutkan sebelumnya, jadi barusan saya membuatkan minuman khusus untuk Anda.",
  ui_story_5046_50460802_30_dialog_content = "Anda harus tahu, saya ahli mixologi terbaik di Umbraton.",
  ui_story_5046_50460802_31_dialog_content = "Tidak usah.",
  ui_story_5046_50460802_32_dialog_content = "Jangan seperti itu. Minuman untuk cerita yang mengangkangi kebenaran dan kebohongan—begitulah yang dilakukan di Umbraton.",
  ui_story_5046_50460802_33_dialog_content = "Apa salahnya mencobanya, eh?",
  ui_story_5046_50460802_34_dialog_content = "(Sepertinya Grimme mencoba menyiratkan sesuatu... dan kenapa tiba-tiba berdiri begitu dekat denganku!?)",
  ui_story_5046_50460802_35_dialog_content = "Saya masih memiliki tugas resmi untuk diurus, dan pelakunya belum tertangkap. saya tidak bisa...",
  ui_story_5046_50460802_36_dialog_content = "Kamu terlihat sangat sedih ketika aku melihatmu di luar sana di jalan. Apakah kasingnya membentur dinding bata?",
  ui_story_5046_50460802_37_dialog_content = "Saat-saat seperti ini kita harus duduk untuk minum dan mendengarkan satu atau dua dongeng untuk bersantai. Anda bahkan mungkin menemukan beberapa inspirasi baru.",
  ui_story_5046_50460802_38_dialog_content = "(Kedengarannya benar.)",
  ui_story_5046_50460802_39_dialog_content = "(Tidak ada petunjuk lain untuk saat ini. Saya hanya harus duduk dan mendengarkan.)",
  ui_story_5046_50460802_40_dialog_content = "Baik, tapi hanya satu.",
  ui_story_5046_50460802_41_dialog_content = "Hehe, kalau begitu aku akan memulai ceritanya.",
  ui_story_5046_50460802_42_dialog_content = "Sepuluh tahun yang lalu, Umbraton tidak memiliki Shadowlord, dan tidak ada yang peduli dengan pertempuran dan pembunuhan yang terjadi di jalanan, apalagi panti asuhan tertentu di pinggiran kota.",
  ui_story_5046_50460802_43_dialog_content = "Tapi panti asuhan di pinggiran ini masih bisa tetap buka untuk bisnis...",
  ui_story_5046_50460802_44_dialog_content = "Menurut Anda apa alasannya?",
  ui_story_5046_50460802_45_dialog_content = "Dalam masyarakat yang bergejolak ini, panti asuhan berhasil tetap beroperasi... Saya kira itu karena dukungan dari seorang dermawan.",
  ui_story_5046_50460802_46_dialog_content = "Itu benar. Panti asuhan memang menerima bantuan, tetapi tidak ada amal.",
  ui_story_5046_50460802_47_dialog_content = "Panti asuhan itu hanya memiliki lima karyawan dan satu direktur, dan bahkan tidak ada desas-desus samar tentang orang besar Umbraton mana pun yang menjaga tempat itu tetap bertahan.",
  ui_story_5046_50460802_48_dialog_content = "Dan seringkali, beberapa anak diadopsi, sementara beberapa anak dikirim ke panti asuhan...",
  ui_story_5046_50460802_49_dialog_content = "Itu seperti membeli dan menjual minuman di belakang bar.",
  ui_story_5046_50460802_50_dialog_content = "A-Maksudmu panti asuhan ini menjalankan operasi perdagangan anak?",
  ui_story_5046_50460802_51_dialog_content = "Jangan terburu-buru, cerita ini belum berakhir.",
  ui_story_5046_50460802_52_dialog_content = "Mereka mengatakan anak angkat dikirim ke beberapa bangsawan Lumopolis — bangsawan yang garis keturunannya hampir punah.",
  ui_story_5046_50460802_53_dialog_content = "Namun, saya mendengar bahwa beberapa waktu lalu, seorang pejabat bernama Pittman mulai menyelidiki para bangsawan ini lagi.",
  ui_story_5046_50460802_54_dialog_content = "<color=#FFB400>Kasus</color> Pittman sedang menyelidiki!",
  ui_story_5046_50460802_55_dialog_content = "Lima karyawan dan satu direktur... Tepatnya sesuai dengan informasi yang saya miliki di panti asuhan lama!",
  ui_story_5046_50460802_56_dialog_content = "Direktur panti asuhan tua tewas dalam kebakaran, dan tiga karyawan tewas dalam kebakaran yang terjadi dalam dua bulan terakhir...",
  ui_story_5046_50460802_57_dialog_content = "Tuan Hamell juga terhubung dengan panti asuhan tua, ditambah orang yang dia sebutkan...",
  ui_story_5046_50460802_58_dialog_content = "Itu membuat lima!",
  ui_story_5046_50460802_59_dialog_content = "Dikombinasikan dengan pernyataan yang diselidiki sebelumnya dari dua anak yang selamat dari kebakaran...",
  ui_story_5046_50460802_60_dialog_content = "Panti asuhan dalam cerita ini adalah panti asuhan tua bukan?",
  ui_story_5046_50460802_61_dialog_content = "Baiklah... Saya hanya bercerita, tidak lebih.",
  ui_story_5046_50460802_62_dialog_content = "Jika Anda dapat memperoleh inspirasi darinya, bagus untuk Anda.",
  ui_story_5046_50460802_63_dialog_content = "Saya telah belajar banyak dari cerita ini. Saya menghargai bantuan Anda.",
  ui_story_5046_50460802_64_dialog_content = "Tapi saya penasaran... Dari mana Anda mendengar cerita ini?",
  ui_story_5046_50460802_65_dialog_content = "Kasus Bpk. Pittman diselidiki terkait dengan bangsawan Lumopolis.",
  ui_story_5046_50460802_66_dialog_content = "Siapa pun yang menceritakan kisah ini kepada Anda mengetahui begitu banyak detail yang tepat. Itu tidak mungkin warga negara biasa.",
  ui_story_5046_50460802_67_dialog_content = "Orang-orang yang bercerita di sini tidak selalu meninggalkan namanya. Semakin sedikit yang saya tahu, semakin menarik ceritanya.",
  ui_story_5046_50460802_68_dialog_content = "Bayangan tahu semua rahasia.",
  ui_story_5046_50460802_69_dialog_content = "(Grimme terlihat tidak dapat diandalkan tetapi berbicara dengan ketepatan yang sempurna.)",
  ui_story_5046_50460802_70_dialog_content = "(Pertemuan kita di jalanan hari ini bukanlah suatu kebetulan. Aku sengaja dibawa ke sini untuk mendengarkan semua ini.)",
  ui_story_5046_50460802_71_dialog_content = "Segala sesuatu yang terjadi di benua itu terhubung. Seekor kupu-kupu di Umbraton dapat menyebabkan badai di Lumopolis.",
  ui_story_5046_50460802_72_dialog_content = "Hmm?",
  ui_story_5046_50460802_73_dialog_content = "(Ada apa dengan tatapan itu dan ucapan tiba-tiba itu?)",
  ui_story_5046_50460802_74_dialog_content = "Hehe... Baiklah, baiklah, waktu cerita sudah berakhir.",
  ui_story_5046_50460802_75_dialog_content = "Lihat, pemandangan malam sangat menakjubkan. Anda jarang bisa melihat langit malam Umbraton, bukan?",
  ui_story_5046_50460802_76_dialog_content = "Pada malam hari, banyak pedagang kecil muncul di Umbraton, lampu mereka membentang seperti sungai bintang. Sungguh pemandangan yang tak terlupakan.",
  ui_story_5046_50460802_77_dialog_content = "Terima kasih untuk cerita Anda. Minumannya juga enak.",
  ui_story_5046_50460802_78_dialog_content = "Hehe, mocktail spesial ini sebenarnya belum pernah saya coba sebelumnya. Saya hanya berpikir untuk melakukan kombinasi semacam ini setelah melihat Anda.",
  ui_story_5046_50460802_79_dialog_content = "Apakah minuman ini memiliki nama?",
  ui_story_5046_50460802_80_dialog_content = "Belum, tapi aku akan menyebutnya—",
  ui_story_5046_50460802_81_dialog_content = "Lily Lumopolis.",
  ui_story_5046_50460901_1_dialog_content = "Hati, apakah Anda ingat di mana Anda dulu tinggal?",
  ui_story_5046_50460901_2_dialog_content = "Jika Anda ingin mendapatkan kembali ingatan Anda tentang masa lalu, pergilah ke tempat Anda dulu tinggal dan lihat apa yang dapat Anda ingat.",
  ui_story_5046_50460901_3_dialog_content = "Ibuku dan aku pindah rumah beberapa kali. Saya tidak ingat alamat lama saya.",
  ui_story_5046_50460901_4_dialog_content = "Tapi saya masih ingat rumah yang saya bakar. Itu dekat Umbraton.",
  ui_story_5046_50460901_5_dialog_content = "Anda tidak membakarnya. Anda pasti salah dalam bagian itu.",
  ui_story_5046_50460901_6_dialog_content = "Mari kita pergi ke sana dan melihat-lihat. Mungkin Anda akan mengingat sesuatu.",
  ui_story_5046_50460901_7_dialog_content = "Ini dia.",
  ui_story_5046_50460901_8_dialog_content = "Semua rumah yang kami lewati sepanjang jalan sepi. Sepertinya sudah lama tidak ada yang tinggal di sini.",
  ui_story_5046_50460901_9_dialog_content = "Ini adalah satu-satunya rumah yang telah terbakar habis. Hanya satu pandangan yang diperlukan untuk melihatnya.",
  ui_story_5046_50460901_10_option_content = "Mengapa tempat ini ditinggalkan?",
  ui_story_5046_50460901_11_dialog_content = "Aku tidak tahu.",
  ui_story_5046_50460901_12_dialog_content = "Yang saya ingat adalah, ketika saya bangun setelah kebakaran, saya sudah berada di panti asuhan.",
  ui_story_5046_50460901_13_dialog_content = "Tak lama, panti asuhan terbakar, dan saya dikirim ke Shadowlord.",
  ui_story_5046_50460901_14_dialog_content = "Hari ini adalah pertama kalinya aku kembali ke sini setelah sekian lama.",
  ui_story_5046_50460901_15_dialog_content = "Tunjukkan padaku di sekitar rumahmu.",
  ui_story_5046_50460901_16_option_content = "Mengapa kamu dan ibumu sering berpindah-pindah?",
  ui_story_5046_50460901_17_dialog_content = "Karena orang jahat selalu mengejar kita.",
  ui_story_5046_50460901_18_dialog_content = "Ibu saya pernah mengatakan kepada saya bahwa ayah saya sangat kuat dan seseorang ingin membawanya pergi dan melakukan percobaan padanya.",
  ui_story_5046_50460901_19_dialog_content = "Kemudian suatu hari, orang jahat masuk ke rumah kami dan mencoba menangkap ayah saya. Setelah itu, ayah saya tetap tinggal untuk melindungi ibu saya.",
  ui_story_5046_50460901_20_dialog_content = "Ibu lari dan melahirkanku.",
  ui_story_5046_50460901_21_dialog_content = "Saya ingat bertanya kepada ibu saya mengapa saya tidak pernah melihat ayah saya. Ibu memberi tahu saya bahwa ayah saya ada di suatu tempat yang jauh.",
  ui_story_5046_50460901_22_dialog_content = "Ketika saya besar nanti, ibu saya memberi tahu saya bahwa organisasi yang menakutkan ingin menangkap ayah saya untuk menggunakannya dalam eksperimen mereka.",
  ui_story_5046_50460901_23_dialog_content = "Organisasi ini tidak menyerah mengejar kami, jadi ibuku selalu menyeretku ke tempat baru.",
  ui_story_5046_50460901_24_dialog_content = "Tunjukkan padaku di sekitar rumahmu.",
  ui_story_5046_50460901_25_option_content = "Tunjukkan padaku di sekitar rumahmu.",
  ui_story_5046_50460901_26_dialog_content = "Saya tahu semuanya sudah habis terbakar sekarang, tetapi Anda harus tetap ingat seperti apa kehidupan di sana.",
  ui_story_5046_50460901_27_dialog_content = "Itu mungkin membuat Anda sedih, tetapi detail kecil apa pun dapat memicu ingatan Anda yang hilang.",
  ui_story_5046_50460901_28_dialog_content = "Aku sebenarnya takut untuk kembali ke sini... Takut mengingat sisa-sisa kecil kenanganku tinggal bersama Ibu.",
  ui_story_5046_50460901_29_dialog_content = "Saya juga takut untuk mengingat ingatan lain yang hilang itu...",
  ui_story_5046_50460901_30_dialog_content = "Jika saya mengetahui bahwa Ibu melemparkan saya ke perapian karena dia takut akan kekuatan saya...",
  ui_story_5046_50460901_31_dialog_content = "Mustahil. Ibumu pasti melakukannya karena alasan lain.",
  ui_story_5046_50460901_32_dialog_content = "Api tidak bisa menyakitimu. Ibumu pasti sudah mengetahui hal ini.",
  ui_story_5046_50460901_33_dialog_content = "Mungkin saat itu kau dalam bahaya, dan ibumu ingin melindungimu, jadi dia menaruhmu di perapian.",
  ui_story_5046_50460901_34_dialog_content = "Sama seperti bagaimana ayahmu tetap tinggal untuk melindunginya.",
  ui_story_5046_50460901_35_dialog_content = "...",
  ui_story_5046_50460901_36_dialog_content = "Ayo pergi. Saya akan menunjukkan kepada Anda di mana saya dulu tinggal.",
  ui_story_5046_50460901_37_dialog_content = "Oke!",
  ui_story_5046_50460901_38_dialog_content = "Anda dapat melihat ruang tamu dari sini begitu Anda berjalan melewati pintu. Ibuku biasa membawakanku makanan enak dan buku bergambar.",
  ui_story_5046_50460901_39_dialog_content = "Ada jendela di sini, yang selalu tertutup tirai tebal. Cahaya tidak bisa menembusnya, dan saya tidak bisa melihat ke luar.",
  ui_story_5046_50460901_40_dialog_content = "Tapi aku bisa mendengar anak-anak bermain di luar sana.",
  ui_story_5046_50460901_41_dialog_content = "Saya ingat suatu kali saya ingin membuka jendela untuk melihat apa yang sedang dimainkan anak-anak, tetapi ibu saya segera menghentikan saya.",
  ui_story_5046_50460901_42_dialog_content = "\"Tutup jendelanya! Sekarang juga!\"",
  ui_story_5046_50460901_43_dialog_content = "Ruangan itu pasti selalu gelap jika cahaya tidak bisa masuk.",
  ui_story_5046_50460901_44_dialog_content = "Ibu menyalakan banyak lilin di sekitar rumah. Itulah yang kami gunakan untuk penerangan.",
  ui_story_5046_50460901_45_dialog_content = "Aneh sekali…",
  ui_story_5046_50460901_46_dialog_content = "Saya lahir dengan Lumina api yang kuat. Ibu bilang aku mewarisinya dari ayahku.",
  ui_story_5046_50460901_47_dialog_content = "Ketika saya masih kecil, saya sering tidak sengaja membakar selimut dan buku bergambar, dan ibu saya juga memberi tahu saya bahwa saya tidak diizinkan menggunakan api saya.",
  ui_story_5046_50460901_48_dialog_content = "Saya kira ibu saya takut dengan kekuatan saya, jadi dia tidak membiarkan saya bermain dengan anak-anak lain... dan kemudian dia melemparkan saya ke perapian.",
  ui_story_5046_50460901_49_dialog_content = "(Ibu Hati tidak mengizinkannya keluar, dan dia menyegel rumah itu dengan aman sehingga orang tidak bisa melihat ke dalam...)",
  ui_story_5046_50460901_50_dialog_content = "(Juga, orang memburu mereka. Mungkin ibu Hati berusaha menyembunyikan sesuatu dari dunia luar.)",
  ui_story_5046_50460901_51_dialog_content = "Lihat, ini adalah perapian.",
  ui_story_5046_50460901_52_dialog_content = "...",
  ui_story_5046_50460901_53_dialog_content = "PlayerName, Saya... Saya ingin pergi ke perapian.",
  ui_story_5046_50460901_54_dialog_content = "Hah?",
  ui_story_5046_50460901_55_dialog_content = "Dengan cara yang sama Anda membuat saya mengingat hidup saya di rumah ini, saya ingin mengingat bagaimana rasanya dilemparkan ke sana.",
  ui_story_5046_50460901_56_dialog_content = "Mungkin aku akan mengingat sesuatu.",
  ui_story_5046_50460901_57_dialog_content = "Kedengarannya seperti ide yang masuk akal ...",
  ui_story_5046_50460901_58_dialog_content = "Oke!",
  ui_story_5046_50460901_59_dialog_content = "Jika Anda memiliki masalah di sana, saya akan menggunakan kemampuan psikis saya untuk memasuki ingatan Anda dan membantu Anda!",
  ui_story_5046_50460901_60_dialog_content = "Terima kasih... tapi saya ingin mencoba mengingat sendiri.",
  ui_story_5046_50460901_61_dialog_content = "Oke, tapi beri tahu saya jika Anda butuh bantuan!",
  ui_story_5046_50460901_62_dialog_content = "<color=#e8d9bb>Umbraton pedesaan</color>",
  ui_story_5046_50460901_63_dialog_content = "Tempat Hati digunakan untuk hidup hanya di depan.",
  ui_story_5046_50460901_64_dialog_content = "Manor liburan Umbraton ayahku juga dekat.",
  ui_story_5046_50460901_65_dialog_content = "Kiri di persimpangan ini, dan sedikit lebih jauh, saya seharusnya bisa melihat gerbangnya.",
  ui_story_5046_50460901_66_dialog_content = "Terakhir kali saya datang ke manor ini, saya sedang berlibur bersama orang tua saya. Tempat Pak Zenas menyelamatkanku juga ada di sekitar sini...",
  ui_story_5046_50460901_67_dialog_content = "Itu... PlayerName!",
  ui_story_5046_50460901_68_dialog_content = "Apakah Anda ingat sesuatu?",
  ui_story_5046_50460901_69_dialog_content = "Belum.",
  ui_story_5046_50460901_70_dialog_content = "Dapatkah saya benar-benar ... tidak ingat?",
  ui_story_5046_50460901_71_dialog_content = "PlayerName! Hati!",
  ui_story_5046_50460901_72_dialog_content = "Kristen!?",
  ui_story_5046_50460901_73_dialog_content = "Hati, menurut hukum, Anda ditahan karena dicurigai melakukan beberapa kejahatan serius, termasuk pembunuhan dan pembakaran yang disengaja!",
  ui_story_5046_50460901_74_dialog_content = "S-Sebentar!",
  ui_story_5046_50460901_75_dialog_content = "Dia tidak melakukan semua itu! Kenapa kau mencoba menangkapnya!?",
  ui_story_5046_50460901_76_dialog_content = "Penjahat mana yang mau mengakui kesalahannya?",
  ui_story_5046_50460901_77_dialog_content = "Y-Nah, jika Anda ingin menangkap seseorang, bukankah Anda membutuhkan bukti?",
  ui_story_5046_50460901_78_dialog_content = "... Bukti?",
  ui_story_5046_50460901_79_dialog_content = "PlayerName, apakah kamu tidak melihatnya juga? Hati membunuh Hamell di depan mata kita.",
  ui_story_5046_50460901_80_dialog_content = "Kristen, percaya saya, Hati tidak membunuh Hamell!",
  ui_story_5046_50460901_81_dialog_content = "Orang lain pasti telah membunuh Hamell dari bayang-bayang.",
  ui_story_5046_50460901_82_dialog_content = "Bagaimanapun, Hati ada di sana ketika Hamell meninggal.",
  ui_story_5046_50460901_83_dialog_content = "Bahkan jika dia tidak membunuhnya, dia wajib bekerja sama dalam penyelidikan.",
  ui_story_5046_50460901_84_dialog_content = "Ikutlah denganku.",
  ui_story_5046_50460901_85_dialog_content = "Aku harus menemukan ingatanku yang hilang bersama ibuku.",
  ui_story_5046_50460901_86_dialog_content = "Itu saja yang saya pedulikan saat ini.",
  ui_story_5046_50460901_87_dialog_content = "Jadi, apakah Anda menolak penangkapan?",
  ui_story_5046_50460901_88_dialog_content = "Sebut saja apa pun yang Anda suka.",
  ui_story_5046_50460901_89_dialog_content = "Sepertinya aku harus menggunakan kekerasan.",
  ui_story_5046_50460901_90_dialog_content = "Kristen, dapatkah kamu membiarkan Hati mencoba mendapatkan ingatannya kembali sebelum Anda membawanya pergi?",
  ui_story_5046_50460901_91_dialog_content = "Menyingkir, PlayerName.",
  ui_story_5046_50460901_92_dialog_content = "Saya harus menangkap Anda sebagai kaki tangan jika Anda menghalangi tersangka lagi.",
  ui_story_5046_50460901_93_dialog_content = "Kenangan ibu... sangat penting.",
  ui_story_5046_50460901_94_dialog_content = "Saya dapat memahami pentingnya kenangan ini Hati.",
  ui_story_5046_50460901_95_dialog_content = "Dan aku berjanji padanya aku akan membantu menemukan ingatan yang hilang ini...",
  ui_story_5046_50460901_96_dialog_content = "Jadi, tidak... Tidak mungkin aku pergi kemana-mana.",
  ui_story_5046_50460901_97_dialog_content = "Aku akan melindungi Hati sampai dia menemukan ingatannya yang hilang.",
  ui_story_5046_50460901_98_dialog_content = "Anda ingin melindungi Hati... tapi aku juga ingin melindungi Kapten Zenas!",
  ui_story_5046_50460901_99_dialog_content = "Hati membakar panti asuhan dan menyanderamu...",
  ui_story_5046_50460901_100_dialog_content = "Andalah yang membayangi ksatria Tuan Zenas!",
  ui_story_5046_50460901_101_dialog_content = "Dia telah menanggung begitu banyak untuk menemukan Anda dan Hati!",
  ui_story_5046_50460901_102_dialog_content = "Jika aku membawamu kembali dan menjelaskan semuanya pada Shadowlord dan seluruh Umbraton...",
  ui_story_5046_50460901_103_dialog_content = "Jika saya melakukan ini saja, Tuan Zenas akan baik-baik saja!",
  ui_story_5046_50460901_104_dialog_content = "Aku akan mengatakannya sekali lagi!",
  ui_story_5046_50460901_105_dialog_content = "Menyingkir, PlayerName!",
  ui_story_5046_50460901_106_dialog_content = "TIDAK! Aku tidak akan pernah minggir!",
  ui_story_5046_50460901_107_dialog_content = "Hati... melindungi ... liontin ...",
  ui_story_5046_50460901_108_dialog_content = "Ibu... Apa yang ibuku ingin aku lindungi...?",
  ui_story_5046_50460901_109_dialog_content = "Katakan padaku, Ibu...",
  ui_story_5046_50460901_110_dialog_content = "Apa yang terjadi hari itu? Anda mendorong saya ke perapian begitu kejam ...",
  ui_story_5046_50460901_111_dialog_content = "Saya akan mengatakannya lagi, untuk terakhir kalinya! Menyingkir, PlayerName!",
  ui_story_5046_50460901_112_dialog_content = "Berikan padaku... mati...",
  ui_story_5046_50460901_113_dialog_content = "Urgh! Kepala saya sakit! Ini seperti ada sesuatu yang menggali ke dalam otakku!",
  ui_story_5046_50460901_114_dialog_content = "Dia di sini.",
  ui_story_5046_50460901_115_dialog_content = "Hari ini... Akhirnya tiba.",
  ui_story_5046_50460901_116_dialog_content = "Ibu?",
  ui_story_5046_50460901_117_dialog_content = "Hati, apapun yang terjadi, baik Ibu bersamamu atau tidak, Ibu akan selalu mencintaimu.",
  ui_story_5046_50460901_118_dialog_content = "Kenapa kamu tidak mau bersamaku, Bu?",
  ui_story_5046_50460901_119_dialog_content = "Aku tidak paham.",
  ui_story_5046_50460901_120_dialog_content = "Sudah terlambat...",
  ui_story_5046_50460901_121_dialog_content = "Hati, pastikan Anda melindungi separuh liontin ini.",
  ui_story_5046_50460901_122_dialog_content = "Liontin ini melambangkan betapa ayahmu dan aku mencintaimu. Kami akan selalu melindungimu, Hati.",
  ui_story_5046_50460901_123_dialog_content = "Jalani hidup yang baik. Ibu mencintaimu...",
  ui_story_5046_50460901_124_dialog_content = "Mama!?",
  ui_story_5046_50460901_125_dialog_content = "Argh!",
  ui_story_5046_50460901_126_dialog_content = "(Kenapa Ibu mendorongku ke perapian!?)",
  ui_story_5046_50460901_127_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5046_50460901_128_dialog_content = "(Apakah ada orang di sini!? Siapa itu? Belum pernah ada yang masuk ke rumah sebelumnya!)",
  ui_story_5046_50460901_129_dialog_content = "Tidak mudah melacakmu, Catherine Kelp. Apakah Anda benar-benar berpikir Anda dapat melarikan diri?",
  ui_story_5046_50460901_130_dialog_content = "... Zenas.",
  ui_story_5046_50460901_131_dialog_content = "Tsk, rumah ini sangat gelap. Mengapa tidak ada cahaya di sini?",
  ui_story_5046_50460901_132_dialog_content = "Seorang wanita mewah tinggal di rumah seperti ini? Sepertinya hidup tidak terlalu baik untukmu akhir-akhir ini.",
  ui_story_5046_50460901_133_dialog_content = "Betapapun lusuhnya rumah yang kutinggali, selama kau mati, aku akan hidup dengan sangat baik.",
  ui_story_5046_50460901_134_dialog_content = "Shh — seorang wanita baik tidak pernah berbicara hal-hal kotor seperti itu.",
  ui_story_5046_50460901_135_dialog_content = "Cukup omong kosong.",
  ui_story_5046_50460901_136_dialog_content = "Aku harus membunuhmu hari ini... untuk membalaskan dendam Fenrir.",
  ui_story_5046_50460901_137_dialog_content = "(Fenrir? Itu nama ayahku! Apakah pria ini membunuh ayahku!?)",
  ui_story_5046_50460901_138_dialog_content = "Anda melebih-lebihkan kemampuan Anda.",
  ui_story_5046_50460901_139_dialog_content = "Terkesiap... terkesiap...",
  ui_story_5046_50460901_140_dialog_content = "Catherine, serahkan saja liontinnya dan aku akan menyelamatkan hidupmu.",
  ui_story_5046_50460901_141_dialog_content = "Langkahi dulu mayatku...",
  ui_story_5046_50460901_142_dialog_content = "Betapa keras kepala. Jika Anda benar-benar ingin mati, saya akan membantu Anda.",
  ui_story_5046_50460901_143_dialog_content = "(Mama!)",
  ui_story_5046_50460901_144_dialog_content = "Hya—!",
  ui_story_5046_50460901_145_dialog_content = "(Api!? Ibu yang memulainya?)",
  ui_story_5046_50460901_146_dialog_content = "Aduh! Bagaimana api ini menyebar begitu cepat?",
  ui_story_5046_50460901_147_dialog_content = "Ini rencanamu, Catherine?",
  ui_story_5046_50460901_148_dialog_content = "Anda tidak akan pergi dari sini hidup-hidup...",
  ui_story_5046_50460901_149_dialog_content = "Biarkan aku pergi! Kau ingin aku dibakar sampai garing di sini bersamamu!?",
  ui_story_5046_50460901_150_dialog_content = "Selama aku membalaskan dendam Fenrir...",
  ui_story_5046_50460901_151_dialog_content = "Aaaaah!",
  ui_story_5046_50460901_152_dialog_content = "(Bu! Ibu masih menatapku...)",
  ui_story_5046_50460901_153_dialog_content = "...",
  ui_story_5046_50460901_154_dialog_content = "(Kata ibu... jangan keluar?)",
  ui_story_5046_50460901_155_dialog_content = "(Bu!? Ibu tidak bergerak!?)",
  ui_story_5046_50460901_156_dialog_content = "(Mama-!)",
  ui_story_5046_50460901_157_dialog_content = "Hmph, bahkan tidak berkeringat.",
  ui_story_5046_50460901_158_dialog_content = "(Waaaah... Ibu...)",
  ui_story_5046_50460901_159_dialog_content = "(Pria itu sedang mencari ibu untuk sesuatu...)",
  ui_story_5046_50460901_160_dialog_content = "(Saya harus pergi ke sana dan membunuhnya... untuk membalaskan dendam ibu saya!)",
  ui_story_5046_50460901_161_dialog_content = "(Tidak, Ibu hanya menyuruhku untuk tidak keluar...)",
  ui_story_5046_50460901_162_dialog_content = "Di sini sangat panas... Di mana dia menyembunyikan benda itu!?",
  ui_story_5046_50460901_163_dialog_content = "...",
  ui_story_5046_50460901_164_dialog_content = "Akhirnya menemukannya. Wajahku perih, apakah terbakar?",
  ui_story_5046_50460901_165_dialog_content = "Api! Api!",
  ui_story_5046_50460901_166_dialog_content = "Aku tidak bisa membiarkan siapa pun melihatku.",
  ui_story_5046_50460901_167_dialog_content = "(Dia sudah pergi... Ibu tidak bergerak lagi...)",
  ui_story_5046_50460901_168_dialog_content = "(Mama...)",
  ui_story_5046_50460901_169_dialog_content = "Api itu sudah tidak terkendali, tapi akhirnya kami berhasil memadamkannya...",
  ui_story_5046_50460901_170_dialog_content = "Mereka menemukan Catherine, tapi dia sudah berhenti bernapas...",
  ui_story_5046_50460901_171_dialog_content = "Api seperti itu akan mencekikmu sampai mati, meski apinya tidak pernah menyentuhmu...",
  ui_story_5046_50460901_172_dialog_content = "Jika Anda tidak memiliki sesuatu yang baik untuk dikatakan, katakan saja tidak apa-apa.",
  ui_story_5046_50460901_173_dialog_content = "Hmph.",
  ui_story_5046_50460901_174_dialog_content = "Bantu bersihkan tempat ini jika tidak ada yang harus dilakukan.",
  ui_story_5046_50460901_175_dialog_content = "Aku tahu, aku tahu.",
  ui_story_5046_50460901_176_dialog_content = "Kesini! Ada seorang anak di perapian!",
  ui_story_5046_50460901_177_dialog_content = "Aku belum pernah mendengar Catherine menyebutkan dia punya anak...",
  ui_story_5046_50460901_178_dialog_content = "Dan anak itu tidak terluka sedikit pun, meskipun kobaran api itu...",
  ui_story_5046_50460901_179_dialog_content = "Sigh... Dia memblokir jendela dan menyalakan lilin di kamar pada siang hari.",
  ui_story_5046_50460901_180_dialog_content = "Hanya masalah waktu sebelum ini terjadi. Melihat?",
  ui_story_5046_50460901_181_dialog_content = "Ayo, berhenti bersikap tidak wajar. Pertanyaan terpenting saat ini adalah — apa yang kita lakukan dengan anak ini?",
  ui_story_5046_50460901_182_dialog_content = "Membawanya ke panti asuhan?",
  ui_story_5046_50460901_183_dialog_content = "Saya kira hanya itu yang bisa kita lakukan.",
  ui_story_5046_50460901_184_dialog_content = "Saya punya pertanyaan lain.",
  ui_story_5046_50461001_1_dialog_content = "Dia tampaknya mulai tenang.",
  ui_story_5046_50461001_2_dialog_content = "Terima kasih, Kristen.",
  ui_story_5046_50461001_3_dialog_content = "Untuk apa?",
  ui_story_5046_50461001_4_dialog_content = "Terima kasih, yang Anda tunggu Hati untuk mendapatkan kembali ingatannya.",
  ui_story_5046_50461001_5_dialog_content = "Anda tidak berpikir Hati apakah pelakunya juga, kan?",
  ui_story_5046_50461001_6_dialog_content = "Setelah melakukan penyelidikan menyeluruh, saya tentu curiga Hati lebih sedikit.",
  ui_story_5046_50461001_7_dialog_content = "Meskipun semua kasus ini terkait dengan Hati, dan setiap petunjuk menunjuk padanya.",
  ui_story_5046_50461001_8_dialog_content = "Namun masih banyak kontradiksi yang belum terselesaikan.",
  ui_story_5046_50461001_9_dialog_content = "Anda benar-benar mengerahkan segalanya untuk kasus ini, Kristen.",
  ui_story_5046_50461001_10_dialog_content = "Pak Zenas mengajari saya bahwa kita harus menangani setiap kasus dengan serius dan tidak pernah meninggalkan satu petunjuk pun.",
  ui_story_5046_50461001_11_dialog_content = "Tapi dia masih tidak mau membiarkan saya mengambil kasus ini ...",
  ui_story_5046_50461001_12_dialog_content = "Jadi, Kristen, Anda telah menyelidiki kasus ini secara rahasia?",
  ui_story_5046_50461001_13_dialog_content = "Ya…",
  ui_story_5046_50461001_14_dialog_content = "Ngomong-ngomong soal, PlayerName, kenapa kamu lari dengan Hati? Dia telah menahanmu bertentangan dengan keinginanmu.",
  ui_story_5046_50461001_15_dialog_content = "Saya percaya dia tidak bersalah, dan dengan semua yang terjadi, emosinya sangat tidak stabil.",
  ui_story_5046_50461001_16_dialog_content = "Dia membutuhkan bantuan saya, jadi saya memintanya untuk membawa saya bersamanya.",
  ui_story_5046_50461001_17_dialog_content = "Anda membangun ikatan kepercayaan yang kuat satu sama lain dalam waktu singkat ...?",
  ui_story_5046_50461001_18_dialog_content = "<size=30>Andai saja Tuan Zenas bisa sangat mempercayaiku...</size>",
  ui_story_5046_50461001_19_dialog_content = "Bagaimana Anda menemukan tempat ini?",
  ui_story_5046_50461001_20_dialog_content = "Seorang lokal menunjukkan jalannya.",
  ui_story_5046_50461001_21_dialog_content = "Letaknya tidak jauh dari panti asuhan, tapi masih bagian dari Umbraton. Bertahun-tahun yang lalu, penduduk setempat di sini hidup sangat keras.",
  ui_story_5046_50461001_22_dialog_content = "Tahun kebakaran panti asuhan, Istvan memenangkan hati banyak orang setelah dia mengambilnya sendiri untuk memperbaiki situasi.",
  ui_story_5046_50461001_23_dialog_content = "Setelah menjadi Shadowlord, Istvan meminta orang-orang di sini untuk pindah ke Umbraton.",
  ui_story_5046_50461001_24_dialog_content = "Sebenarnya orang yang sama yang mengantarkan Hati ke panti asuhan, yang membawaku ke sini.",
  ui_story_5046_50461001_25_dialog_content = "Dia mengatakan kebakaran terjadi di kota ini sebelumnya, dan Hati ditemukan di reruntuhan setelah api padam.",
  ui_story_5046_50461001_26_dialog_content = "Wanita yang tinggal di sini meninggal.",
  ui_story_5046_50461001_27_dialog_content = "Tetapi penduduk setempat tidak pernah mendengar wanita itu menyebutkan bahwa dia punya anak, jadi mereka tidak tahu harus berbuat apa.",
  ui_story_5046_50461001_28_dialog_content = "Akhirnya, mereka memutuskan untuk menyekolahkan anak tersebut ke panti asuhan. Anak itu Hati.",
  ui_story_5046_50461001_29_dialog_content = "Jadi, begitu, ya…",
  ui_story_5046_50461001_30_dialog_content = "Pekerjaan yang luar biasa, Kristen. Anda menemukan begitu banyak hanya dengan beberapa petunjuk untuk melanjutkan.",
  ui_story_5046_50461001_31_dialog_content = "Ahem! Tidak masalah seberapa banyak Anda memuji saya, saya akan membawa Anda kembali bersama saya untuk bekerja sama dalam penyelidikan.",
  ui_story_5046_50461001_32_dialog_content = "Saya percaya dari lubuk hati saya bahwa Anda benar-benar luar biasa! Saya tahu Anda akan menjadi hakim yang hebat di masa depan!",
  ui_story_5046_50461001_33_dialog_content = "Andai saja dia berpikiran sama...",
  ui_story_5046_50461001_34_dialog_content = "Pak Zenas?",
  ui_story_5046_50461001_35_dialog_content = "Ya... Tuan Zenas terluka menggunakan Luminatics untuk memadamkan api, tapi bahkan setelah ini, Tuan Hamell terbunuh...",
  ui_story_5046_50461001_36_dialog_content = "Dia tidak lagi percaya padaku.",
  ui_story_5046_50461001_37_dialog_content = "Saya pikir Anda telah melakukannya dengan sangat baik, Kristen.",
  ui_story_5046_50461001_38_dialog_content = "Meskipun kita hanya memiliki kesempatan untuk bertemu satu sama lain beberapa kali, saya dapat merasakan bahwa Anda adalah seorang hakim yang teliti, sabar, dan baik hati.",
  ui_story_5046_50461001_39_dialog_content = "J-Jangan berpikir kata-kata manismu bisa mengubahku...",
  ui_story_5046_50461001_40_dialog_content = "Saya menerima pelatihan profesional ekstensif dari Lumo Hall of Justice! Keyakinan saya pada keadilan tidak akan pernah tergoyahkan oleh orang-orang seperti Anda!",
  ui_story_5046_50461001_41_dialog_content = "Saya hanya mengatakan apa yang ingin saya katakan! Saya tidak bermaksud apa-apa lagi dengan itu!",
  ui_story_5046_50461001_42_dialog_content = "Jika Hati benar-benar melakukan hal-hal itu, aku akan membuatnya mengaku.",
  ui_story_5046_50461001_43_dialog_content = "Tetapi jika dia tidak melakukan apa-apa, Anda tidak bisa menjebaknya begitu saja!",
  ui_story_5046_50461001_44_dialog_content = "B-Benar! Itulah arti keadilan!",
  ui_story_5046_50461001_45_dialog_content = "Anda harus mencoba untuk percaya pada diri sendiri dan berhenti mengkhawatirkan apa yang dipikirkan orang lain.",
  ui_story_5046_50461001_46_dialog_content = "Terutama mengingat betapa menakjubkannya Anda!",
  ui_story_5046_50461001_47_dialog_content = "...",
  ui_story_5046_50461001_48_dialog_content = "Adakah yang pernah memberitahumu bahwa kamu cukup pandai membuat gadis bahagia?",
  ui_story_5046_50461001_49_dialog_content = "Hah? Saya membuat gadis-gadis bahagia?",
  ui_story_5046_50461001_50_dialog_content = "Vice selalu membenciku karena membelanjakan uang dan membuatnya khawatir tentang pengeluaran Colossus setiap hari.",
  ui_story_5046_50461001_51_dialog_content = "Anda akan lebih baik mengatakan saya selalu menimbulkan masalah bagi para gadis.",
  ui_story_5046_50461001_52_dialog_content = "<size=45>Graaaaaah—</size>",
  ui_story_5046_50461001_53_dialog_content = "Apakah itu Eclipsite? Sepertinya ada lebih dari satu.",
  ui_story_5046_50461001_54_dialog_content = "Tempat ini sudah lama ditinggalkan. Itu hanya diharapkan bahwa Eclipsites akan menghantui daerah ini.",
  ui_story_5046_50461001_55_dialog_content = "Tetapi Hati belum bangun. Saya khawatir mungkin berbahaya untuk membawanya ke sini sekarang.",
  ui_story_5046_50461001_56_dialog_content = "Jangan khawatir, itu hanya beberapa Eclipsites. Saya akan menilai mereka di tempat!",
  ui_story_5046_50461002_1_dialog_content = "Fiuh—",
  ui_story_5046_50461002_2_dialog_content = "Aura Eclipsite di sekitar sini akhirnya menghilang.",
  ui_story_5046_50461002_3_dialog_content = "Terima kasih, Kristen.",
  ui_story_5046_50461002_4_dialog_content = "Saya melihat sekarang betapa kuatnya Caelestites.",
  ui_story_5046_50461002_5_dialog_content = "Jika bukan karena Anda, serangan diam-diam Eclipsites itu mungkin berhasil.",
  ui_story_5046_50461002_6_dialog_content = "PlayerName…",
  ui_story_5046_50461002_7_dialog_content = "Hati! Hati sudah bangun!",
  ui_story_5046_50461002_8_dialog_content = "Sekarang setelah Anda bangun, Anda harus kembali bersama saya untuk diinterogasi. Sebelum hasil investigasi keluar...",
  ui_story_5046_50461002_9_dialog_content = "Itu Zena...",
  ui_story_5046_50461002_10_dialog_content = "Mentor Saya?",
  ui_story_5046_50461002_11_dialog_content = "PlayerName... Saya ingat semuanya.",
  ui_story_5046_50461002_12_dialog_content = "Malam itu, ibuku mendorongku ke perapian untuk melindungiku.",
  ui_story_5046_50461002_13_dialog_content = "Dia menghadapi Zenas sendirian... Ya, pria itu bernama Zenas.",
  ui_story_5046_50461002_14_dialog_content = "Dia membunuh ibuku dan mencuri liontinnya darinya.",
  ui_story_5046_50461002_15_dialog_content = "Aku harus mengambil liontin itu.",
  ui_story_5046_50461002_16_dialog_content = "Mentor Saya? Apa hubungannya ini dengan mentor saya?",
  ui_story_5046_50461002_17_dialog_content = "Zenas adalah pembunuhnya.",
  ui_story_5046_50461002_18_dialog_content = "Omong kosong!",
  ui_story_5046_50461002_19_dialog_content = "Jika Anda berani tidak menghormati Tuan Zenas lagi, jangan salahkan saya atas apa yang saya lakukan selanjutnya!",
  ui_story_5046_50461002_20_dialog_content = "Pembunuh adalah pembunuh, dan dialah orangnya.",
  ui_story_5046_50461002_21_dialog_content = "Zenas masuk ke rumahku malam itu, membunuh ibuku, dan mencuri liontinku.",
  ui_story_5046_50461002_22_dialog_content = "Saya melihat semuanya dengan mata kepala sendiri! Aku harus membunuhnya untuk membalaskan dendam ibuku!",
  ui_story_5046_50461002_23_dialog_content = "Bagaimana Anda bisa mengatakan mentor saya membunuh ibumu !?",
  ui_story_5046_50461002_24_dialog_content = "Anda baru saja mengingat kejadian ini, dan sudah begitu lama.",
  ui_story_5046_50461002_25_dialog_content = "Bagaimana Anda bisa yakin bahwa ingatan Anda tidak salah? Dan bagaimana aku tahu kau tidak berbohong?",
  ui_story_5046_50461002_26_dialog_content = "aku tahu aku tidak salah...",
  ui_story_5046_50461002_27_dialog_content = "Dengan luka bakar di wajahnya dan liontin ibuku...",
  ui_story_5046_50461002_28_dialog_content = "Aku yakin dia pembunuhnya!",
  ui_story_5046_50461002_29_dialog_content = "Maaf, tapi mentorku mengalami luka bakar di wajahnya saat dia menyelamatkanku.",
  ui_story_5046_50461002_30_dialog_content = "Malam itu, orang tua saya pergi ke perjamuan.",
  ui_story_5046_50461002_31_dialog_content = "Saya ingat hari itu menjadi gelap sangat awal hari itu... Segera setelah saya melihat orang tua saya pergi, hari menjadi gelap.",
  ui_story_5046_50461002_32_dialog_content = "Aku kembali ke kamarku untuk membaca sendiri.",
  ui_story_5046_50461002_33_dialog_content = "Tiba-tiba, kebakaran besar terjadi di suatu tempat. Orang tua saya tidak ada di rumah, dan asap semakin tebal, saya hanya berdiri di sana menangis dengan keras.",
  ui_story_5046_50461002_34_dialog_content = "Untungnya, Pak Zenas meneriakkan nama saya dan mengikuti isak tangis saya untuk menemukan saya...",
  ui_story_5046_50461002_35_dialog_content = "Saat kami melarikan diri, Pak Zenas memelukku erat-erat, dan aku tidak menderita luka apa pun kecuali tercekik oleh asap tebal.",
  ui_story_5046_50461002_36_dialog_content = "Tapi Pak Zenas... Separuh wajahnya terbakar.",
  ui_story_5046_50461002_37_dialog_content = "Jadi, wajah Zenas terbakar saat menyelamatkan Kristen.",
  ui_story_5046_50461002_38_dialog_content = "...",
  ui_story_5046_50461002_39_dialog_content = "Hati, apakah Anda ingat hari ketika Zenas menyerang?",
  ui_story_5046_50461002_40_dialog_content = "26 Agustus. Itu adalah ... ulang tahunku.",
  ui_story_5046_50461002_41_dialog_content = "26 Agustus!?",
  ui_story_5046_50461002_42_dialog_content = "Hari dimana Tuan Zenas menyelamatkanku juga tanggal 26 Agustus.",
  ui_story_5046_50461002_43_dialog_content = "Hari itu... Aku mengingatnya dengan sangat jelas.",
  ui_story_5046_50461002_44_dialog_content = "Tampaknya kedua peristiwa ini terjadi pada hari yang sama ...",
  ui_story_5046_50461002_45_dialog_content = "Baru saja, Kristen mengatakan bahwa rumahnya terbakar malam itu, yang berarti Zenas muncul di rumah Kristen pada malam hari.",
  ui_story_5046_50461002_46_dialog_content = "Tetapi Hati juga mengatakan Zenas menyerang pada malam hari.",
  ui_story_5046_50461002_47_dialog_content = "Dengan kata lain, Zenas muncul di dua tempat berbeda pada waktu yang sama di hari yang sama.",
  ui_story_5046_50461002_48_dialog_content = "Ketika Anda melihatnya seperti itu, itu tidak mungkin. Anda pasti salah, Hati.",
  ui_story_5046_50461002_49_dialog_content = "Bagaimana Anda menjelaskan liontin itu?",
  ui_story_5046_50461002_50_dialog_content = "Mengapa liontin yang diminta ibu saya untuk saya rawat ada di tangannya?",
  ui_story_5046_50461002_51_dialog_content = "Justru karena liontin inilah saya mengenalinya.",
  ui_story_5046_50461002_52_dialog_content = "Liontin yang Anda sebutkan adalah pusaka keluarga mentor saya.",
  ui_story_5046_50461002_53_dialog_content = "Pola pada liontin itu adalah lambang keluarga dari keluarga bangsawan Lumopolis yang sayangnya jatuh lebih dari satu dekade lalu.",
  ui_story_5046_50461002_54_dialog_content = "Pada hari mentor saya menyelamatkan saya dari api, ayah saya ingin mengungkapkan rasa terima kasihnya karena telah menyelamatkan hidup saya dan dia bertanya tentang latar belakangnya.",
  ui_story_5046_50461002_55_dialog_content = "Mentor saya mengeluarkan liontin itu dan mengatakan bahwa dia awalnya seorang bangsawan, tetapi dia harus berkeliaran tanpa harapan karena keluarganya menolak.",
  ui_story_5046_50461002_56_dialog_content = "Ayah saya bersimpati padanya, sebagai sesama bangsawan, dan meminta mentor saya untuk tetap tinggal dan melayani keluarga kami.",
  ui_story_5046_50461002_57_dialog_content = "Saya ingat dengan jelas bahwa liontin itu milik ibu saya.",
  ui_story_5046_50461002_58_dialog_content = "Dia pasti telah mengambil liontin ibuku dan memberikannya sebagai miliknya!",
  ui_story_5046_50461002_59_dialog_content = "Anda! Kesimpulan Anda tidak dapat dianggap benar sampai Anda memiliki bukti.",
  ui_story_5046_50461002_60_dialog_content = "(Hati disebutkan sebelumnya bahwa ibunya menjaga rumahnya dengan ketat dari sinar matahari dan menyalakannya dengan lilin.)",
  ui_story_5046_50461002_61_dialog_content = "(Jadi, mungkin Hati tidak yakin apakah itu siang atau malam ketika insiden itu terjadi!)",
  ui_story_5046_50461002_62_dialog_content = "Hati, dapatkah Anda yakin pembunuhnya masuk ke rumah Anda pada malam hari?",
  ui_story_5046_50461002_63_dialog_content = "Aku ingat lilin menyalakan ruangan. Seharusnya sudah malam.",
  ui_story_5046_50461002_64_dialog_content = "Itulah masalahnya.",
  ui_story_5046_50461002_65_dialog_content = "Karena lilin sering menerangi rumah Anda, tentu Anda akan berpikir—",
  ui_story_5046_50461002_66_dialog_content = "\"Karena saya melihat lilin yang menyala, kejadian itu terjadi pada malam hari.\"",
  ui_story_5046_50461002_67_dialog_content = "Namun nyatanya, lilin dinyalakan di rumah Anda baik siang maupun malam, jadi salah jika menggunakan lilin yang menyala untuk menilai waktu.",
  ui_story_5046_50461002_68_dialog_content = "Saya mengusulkan bahwa saat rumah Hati diserang sebenarnya adalah siang hari.",
  ui_story_5046_50461002_69_dialog_content = "Jadi, begitulah...",
  ui_story_5046_50461002_70_dialog_content = "Kristen dapat secara akurat mengingat orang tuanya menghadiri perjamuan di malam hari dan ingat bahwa hari mulai gelap hari itu.",
  ui_story_5046_50461002_71_dialog_content = "Jadi kebakaran di rumah Kristen memang terjadi pada malam hari.",
  ui_story_5046_50461002_72_dialog_content = "Berdasarkan deduksi tersebut, tersangka menyerang rumah Hati pada siang hari dan bergegas ke rumah Kristen pada malam hari untuk memadamkan api.",
  ui_story_5046_50461002_73_dialog_content = "Oleh karena itu, tidak ada kejadian satu orang muncul di dua tempat berbeda pada waktu yang bersamaan.",
  ui_story_5046_50461002_74_dialog_content = "Alasan brilian...",
  ui_story_5046_50461002_75_dialog_content = "Tetapi kami masih membutuhkan beberapa informasi lebih lanjut. Berapa lama waktu yang dibutuhkan untuk pergi dari sini ke manor liburan Anda?",
  ui_story_5046_50461002_76_dialog_content = "Saya mencatat ini dalam perjalanan saya ke sini. Itu tidak jauh dari rumahku.",
  ui_story_5046_50461002_77_dialog_content = "Apakah itu benar-benar ... mentor saya? Tidak, itu tidak mungkin...",
  ui_story_5046_50461002_78_dialog_content = "Jika Anda ingin menentukan apakah Zenas adalah penyerangnya, minta saja dia untuk menunjukkan liontinnya kepada Anda.",
  ui_story_5046_50461002_79_dialog_content = "Hati mengatakan bahwa kedua liontin ini adalah pasangan yang serasi.",
  ui_story_5046_50461002_80_dialog_content = "Jika Zenas tidak menyerang keluarga Hati dan, seperti yang dia katakan, dia memang bangsawan yang jatuh...",
  ui_story_5046_50461002_81_dialog_content = "Maka liontinnya tidak akan cocok dengan yang ada di tangan Hati.",
  ui_story_5046_50461002_82_dialog_content = "Tapi jika kedua liontin ini sangat cocok...",
  ui_story_5046_50461002_83_dialog_content = "Maka dia pasti pelakunya.",
  ui_story_5046_50461002_84_dialog_content = "Tidak, mentorku tidak mungkin seorang pembunuh!",
  ui_story_5046_50461002_85_dialog_content = "Oh ya, itu benar! Motif!",
  ui_story_5046_50461002_86_dialog_content = "Tidak ada permusuhan antara keluargamu dan mentorku, jadi mengapa dia memburu dan membunuh orang tuamu?",
  ui_story_5046_50461002_87_dialog_content = "Ibuku memberitahuku bahwa sebuah organisasi misterius menginginkan kekuatan ayahku, dan mereka ingin menangkapnya untuk digunakan dalam eksperimen mereka.",
  ui_story_5046_50461002_88_dialog_content = "Dalam ingatanku, ibuku ingin membalaskan dendam ayahku, dan kehilangan nyawanya saat mencoba membunuh Zenas...",
  ui_story_5046_50461002_89_dialog_content = "Jadi, Zenas adalah anggota dari organisasi misterius itu.",
  ui_story_5046_50461002_90_dialog_content = "Aku tak percaya!",
  ui_story_5046_50461002_91_dialog_content = "Tidak, tidak mungkin!",
  ui_story_5046_50461002_92_dialog_content = "Kristen, tenang.",
  ui_story_5046_50461002_93_dialog_content = "Apakah Zenas pelakunya atau tidak dapat ditentukan hanya dengan menyatukan liontinnya dan Hati.",
  ui_story_5046_50461002_94_dialog_content = "Minta dia untuk menyerahkan liontinnya.",
  ui_story_5046_50461002_95_dialog_content = "Jika dia menolak untuk menyerahkannya, saya akan menghajarnya sampai habis dan mengambilnya darinya.",
  ui_story_5046_50461002_96_dialog_content = "Kita tidak bisa menggunakan kekerasan! Umbraton penuh dengan tentara yang mencarimu. Akan sulit bagi kami untuk menghadapi Zenas dan membicarakan hal ini dengannya.",
  ui_story_5046_50461002_97_dialog_content = "...",
  ui_story_5046_50461002_98_dialog_content = "Saya bisa bantu anda.",
  ui_story_5046_50461002_99_dialog_content = "Sebagai PlayerName berkata, memastikan apakah liontin itu cocok satu sama lain adalah cara termudah untuk membuktikan ketidakbersalahan mentorku.",
  ui_story_5046_50461002_100_dialog_content = "Jadi saya akan membantu Anda untuk bertemu mentor saya tanpa tentara lain.",
  ui_story_5046_50461002_101_dialog_content = "Namun, Anda juga harus berjanji kepada saya bahwa jika liontin tidak cocok satu sama lain, Anda akan bekerja sama sepenuhnya dalam penyelidikan.",
  ui_story_5046_50461002_102_dialog_content = "Jadi, Anda percaya kami?",
  ui_story_5046_50461002_103_dialog_content = "Aku tidak bilang begitu, kok.",
  ui_story_5046_50461002_104_dialog_content = "Tapi saya telah belajar banyak dari sikap investigasi yang serius PlayerName memiliki terhadap kejadian ini.",
  ui_story_5046_50461002_105_dialog_content = "Saya ingin memeriksa kembali kasus ini dengan lebih hati-hati.",
  ui_story_5046_50461002_106_dialog_content = "Sudah larut. Ayo cepat kembali ke Umbraton.",
  ui_story_5046_50461101_1_dialog_content = "Merindukan Kristen, kamu kembali.",
  ui_story_5046_50461101_2_dialog_content = "Telepon saya saja Kristen.",
  ui_story_5046_50461101_3_dialog_content = "Di mana Kapten Zenas? Kenapa aku tidak bisa menemukannya?",
  ui_story_5046_50461101_4_dialog_content = "Kapten Zenas membawa beberapa orang ke panti asuhan.",
  ui_story_5046_50461101_5_dialog_content = "Panti asuhan? Apa yang kapten lakukan di sana?",
  ui_story_5046_50461101_6_dialog_content = "Erm... Dia tidak bilang.",
  ui_story_5046_50461101_7_dialog_content = "Baiklah, lanjutkan.",
  ui_story_5046_50461101_8_dialog_content = "Kami tidak dapat menemukan apa pun, Pak.",
  ui_story_5046_50461101_9_dialog_content = "Tetap mencari. Apa pun yang Anda temukan, berikan langsung kepada saya, mengerti?",
  ui_story_5046_50461101_10_dialog_content = "Lapor!",
  ui_story_5046_50461101_11_dialog_content = "Apakah kamu menemukan sesuatu?",
  ui_story_5046_50461101_12_dialog_content = "Tidak, tapi Nona Kristen di sini. Dia ingin melihatmu.",
  ui_story_5046_50461101_13_dialog_content = "Apa yang dia lakukan di sini?",
  ui_story_5046_50461101_14_dialog_content = "Pak.",
  ui_story_5046_50461101_15_dialog_content = "Ayo pergi keluar. Saya ingin berbicara dengan Anda sendirian.",
  ui_story_5046_50461101_16_dialog_content = "Oke.",
  ui_story_5046_50461101_17_dialog_content = "Kristen? Apa yang kamu lakukan di sini?",
  ui_story_5046_50461101_18_dialog_content = "Bukankah Anda seharusnya mempresentasikan kasus ini di Lumo Hall of Justice?",
  ui_story_5046_50461101_19_dialog_content = "Sebelum kembali ke Lumopolis, saya ingin menanyakan sesuatu.",
  ui_story_5046_50461101_20_dialog_content = "Bisakah saya meminjam liontin Anda?",
  ui_story_5046_50461101_21_dialog_content = "liontin saya?",
  ui_story_5046_50461101_22_dialog_content = "Anda pernah menunjukkan kepada saya sebuah liontin dengan lambang keluarga Anda di atasnya.",
  ui_story_5046_50461101_23_dialog_content = "Mengapa Anda ingin melihatnya?",
  ui_story_5046_50461101_24_dialog_content = "Hmm…",
  ui_story_5046_50461101_25_dialog_content = "Saya melihat pola yang mirip dengan lambang keluarga Anda saat membaca file saya, jadi saya ingin melihat lagi liontin Anda, hanya untuk memastikan.",
  ui_story_5046_50461101_26_dialog_content = "...",
  ui_story_5046_50461101_27_dialog_content = "Kristen, Saya melihat Anda tumbuh dewasa. Aku bisa tahu dalam sekejap saat kau berbohong.",
  ui_story_5046_50461101_28_dialog_content = "Pak…",
  ui_story_5046_50461101_29_dialog_content = "Ayo, apa alasannya?",
  ui_story_5046_50461101_30_dialog_content = "Yah, sebenarnya... Aku sebenarnya ingin membuktikan ketidakbersalahanmu dengan liontin itu.",
  ui_story_5046_50461101_31_dialog_content = "Buktikan saya tidak bersalah?",
  ui_story_5046_50461101_32_dialog_content = "Saya mengetahui bahwa Anda mungkin terkait dengan kasus pembakaran bertahun-tahun yang lalu.",
  ui_story_5046_50461101_33_dialog_content = "Liontin yang selalu Anda kenakan adalah kunci untuk menghilangkan semua kecurigaan di sekitar Anda.",
  ui_story_5046_50461101_34_dialog_content = "Apa hubungan antara liontin saya dan kasus pembakaran ini?",
  ui_story_5046_50461101_35_dialog_content = "Saya diberi tahu bahwa liontin Anda adalah bagian dari pasangan dan cocok dengan liontin yang saya miliki di tangan saya.",
  ui_story_5046_50461101_36_dialog_content = "Yang saya butuhkan hanyalah Anda meminjamkan saya liontin itu dan biarkan saya mengkonfirmasi apakah kedua liontin itu dapat digabungkan ...",
  ui_story_5046_50461101_37_dialog_content = "Jika Anda memegang sesuatu yang berkaitan dengan kasus ini, Anda harus menyerahkannya kepada personel yang relevan untuk pemeriksaan lebih lanjut.",
  ui_story_5046_50461101_38_dialog_content = "Langsung menanyai atasanmu dengan bukti... Kristen, apakah saya tidak mengajari Anda apa pun selama ini?",
  ui_story_5046_50461101_39_dialog_content = "Jika Anda tidak ingin menyerahkannya, kami memiliki cara lain untuk membuat Anda bekerja sama.",
  ui_story_5046_50461101_40_dialog_content = "Hati?",
  ui_story_5046_50461101_41_dialog_content = "Kristen, karena Anda telah menangkap tersangka, mengapa Anda tidak memenjarakannya saja?",
  ui_story_5046_50461101_42_dialog_content = "Karena Hati bukan tersangka, kasus pembakaran di Umbraton dan kematian Mr. Hamell tidak ada hubungannya dengan dia.",
  ui_story_5046_50461101_43_dialog_content = "Begitu... Jadi, begitu.",
  ui_story_5046_50461101_44_dialog_content = "Kristen, Anda benar-benar menyembunyikan tersangka dan bersekongkol dengannya untuk menipu atasan Anda!?",
  ui_story_5046_50461101_45_dialog_content = "Aku... aku tidak...",
  ui_story_5046_50461101_46_dialog_content = "Dia hanya ingin meminjam liontinmu... Tidakkah menurutmu reaksimu terlalu ekstrem?",
  ui_story_5046_50461101_47_dialog_content = "Mungkinkah karena... kau bersalah?",
  ui_story_5046_50461101_48_dialog_content = "Anda memanfaatkan fakta bahwa lilin dinyalakan di rumah Hati siang dan malam untuk membuat alibi bagi diri Anda sendiri, dan Anda menggunakan Kristen sebagai saksimu!",
  ui_story_5046_50461101_49_dialog_content = "Setelah Anda melakukan pembunuhan di rumah Hati, Anda membakar manor Kristen tidak jauh dari sana.",
  ui_story_5046_50461101_50_dialog_content = "Anda berpura-pura lewat dan berlari untuk menyelamatkan siapa pun yang ada di dalam, menciptakan ilusi bahwa luka bakar di wajah Anda diakibatkan oleh kepahlawanan Anda!",
  ui_story_5046_50461101_51_dialog_content = "Namun kenyataannya, kebenaran yang buruk adalah bahwa luka bakar di wajah Anda diakibatkan oleh pertengkaran dengan ibu Hati, yang menyalakan api untuk memastikan Anda binasa bersamanya!",
  ui_story_5046_50461101_52_dialog_content = "Hmph. Inikah cerita yang kau buat untuk menjebakku? Ini sangat menarik.",
  ui_story_5046_50461101_53_dialog_content = "Ini adalah pendapat saya tentang kasus ini berdasarkan informasi yang tersedia.",
  ui_story_5046_50461101_54_dialog_content = "Kristen, apakah ini yang juga kamu percayai?",
  ui_story_5046_50461101_55_dialog_content = "Pak... saya...",
  ui_story_5046_50461101_56_dialog_content = "PlayerNamededuksi...",
  ui_story_5046_50461101_57_dialog_content = "Aku…",
  ui_story_5046_50461101_58_dialog_content = "...",
  ui_story_5046_50461101_59_dialog_content = "Hahahahahaha!",
  ui_story_5046_50461101_60_dialog_content = "Kristen, nona... Anda benar-benar sesuatu yang lain.",
  ui_story_5046_50461101_61_dialog_content = "Anda lebih suka mempercayai Caelestite yang baru Anda kenal sehari daripada mentor Anda sendiri.",
  ui_story_5046_50461101_62_dialog_content = "Mengapa Anda tidak membiarkan kami melihat liontin itu...?",
  ui_story_5046_50461101_63_dialog_content = "Jelas, yang perlu Anda lakukan hanyalah menunjukkannya kepada saya untuk menghilangkan keraguan saya ...",
  ui_story_5046_50461101_64_dialog_content = "Karena benih keraguan telah ditabur di dalam hatimu, apa gunanya?",
  ui_story_5046_50461101_65_dialog_content = "Apakah saya memberikannya kepada Anda atau tidak, Anda telah mencapai keputusan.",
  ui_story_5046_50461101_66_dialog_content = "Tidak, itu tidak benar sama sekali! Semua deduksi membutuhkan bukti untuk membuktikan kebenarannya...",
  ui_story_5046_50461101_67_dialog_content = "Oke, jangan katakan lagi.",
  ui_story_5046_50461101_68_dialog_content = "Di masa depan, jangan merujuk saya sebagai mentor Anda.",
  ui_story_5046_50461101_69_dialog_content = "Karena Anda telah memilih untuk bergaul dengan tersangka ini, ujung pedang saya sekarang menunjuk ke arah Anda.",
  ui_story_5046_50461101_70_dialog_content = "Pak... Apa artinya ini?",
  ui_story_5046_50461101_71_dialog_content = "Kristen, Anda harus memercayai penilaian Anda sendiri!",
  ui_story_5046_50461101_72_dialog_content = "Dia mencoba memeras Anda secara emosional! Tidak masalah apakah dia mentor Anda atau bukan—Anda harus memegang rasa keadilan di hati Anda!",
  ui_story_5046_50461101_73_dialog_content = "Inilah dirimu, Kristen—seorang hakim percobaan di Lumopolis!",
  ui_story_5046_50461101_74_dialog_content = "Aku…",
  ui_story_5046_50461101_75_dialog_content = "Penjaga! Kristen telah berkolusi dengan Caelestite untuk menampung tersangka, Hati. Tangkap mereka semua!",
  ui_story_5046_50461101_76_dialog_content = "Pak!",
  ui_story_5046_50461102_1_dialog_content = "Terkesiap... terkesiap...",
  ui_story_5046_50461102_2_dialog_content = "Aku tidak percaya kau mengalahkan semua pengawalku...",
  ui_story_5046_50461102_3_dialog_content = "Menurut hukum Balai Kehakiman, apa yang kita lakukan terhadap mereka yang menentang penangkapan dan penyerangan Penjaga Lumo?",
  ui_story_5046_50461102_4_dialog_content = "Dengan baik, Kristen?",
  ui_story_5046_50461102_5_dialog_content = "Pak, mohon kerjasamanya dengan investigasi...",
  ui_story_5046_50461102_6_dialog_content = "Setelah penyelidikan selesai, ketidakbersalahanmu akan terbukti dan semuanya bisa kembali seperti semula...",
  ui_story_5046_50461102_7_dialog_content = "Baiklah.",
  ui_story_5046_50461102_8_dialog_content = "Hah!? Anda setuju!?",
  ui_story_5046_50461102_9_dialog_content = "(Dia sangat bersikeras untuk tidak menyerah beberapa saat yang lalu... Kenapa dia tiba-tiba setuju?)",
  ui_story_5046_50461102_10_dialog_content = "Serahkan liontin itu, cepat!",
  ui_story_5046_50461102_11_dialog_content = "Dia membunuh ibuku... Dia harus membayar perbuatannya!",
  ui_story_5046_50461102_12_dialog_content = "Aku akan membalaskan dendam orang tuaku! Aku akan membunuhnya!",
  ui_story_5046_50461102_13_dialog_content = "Tenang, Hati!",
  ui_story_5046_50461102_14_dialog_content = "Anda dapat mengandalkan Kristen untuk menyelidiki seluruh masalah ini.",
  ui_story_5046_50461102_15_dialog_content = "Jika Anda menggunakan kekerasan untuk menyelesaikan masalah, Anda benar-benar akan menjadi pembunuh!",
  ui_story_5046_50461102_16_dialog_content = "Itu Hati Saya tahu adalah anak yang lembut dan baik hati yang orang tuanya mencintainya!",
  ui_story_5046_50461102_17_dialog_content = "Orang tuamu tidak ingin kamu membalaskan dendam mereka dengan cara ini!",
  ui_story_5046_50461102_18_dialog_content = "Sungguh... Ibu dan Ayah tidak ingin aku...?",
  ui_story_5046_50461102_19_dialog_content = "... Hmn.",
  ui_story_5046_50461102_20_dialog_content = "Aku bisa menyerahkan liontin itu, tapi aku harus kembali ke Umbraton dulu dan membuktikan ketidakbersalahanku di depan semua orang.",
  ui_story_5046_50461102_21_dialog_content = "Ayo pergi, Kristen.",
  ui_story_5046_50461102_22_dialog_content = "Saat kita kembali ke Umbraton, aku akan membuktikan ketidakbersalahanku, lalu kita bisa kembali ke keadaan semula...",
  ui_story_5046_50461102_23_dialog_content = "Hm...",
  ui_story_5046_50461102_24_dialog_content = "Jangan ada di antara kalian yang bergerak, atau aku akan mematahkan lehernya.",
  ui_story_5046_50461102_25_dialog_content = "Pak!? Mengapa...",
  ui_story_5046_50461102_26_dialog_content = "Apa yang Anda pikir Anda lakukan? Biarkan pergi Kristen!",
  ui_story_5046_50461102_27_dialog_content = "Saat mengejar tersangka Hati, tersangka menolak penangkapan, dan Kristen, sayangnya, meninggal dalam menjalankan tugas ...",
  ui_story_5046_50461102_28_dialog_content = "Kamu gila!",
  ui_story_5046_50461102_29_dialog_content = "Selama Kristen mati, aku akan menjadi satu-satunya yang tahu apa yang sebenarnya terjadi di sini hari ini.",
  ui_story_5046_50461102_30_dialog_content = "Aku akan menyerahkan laporan ke Hall of Justice, dan Hati akan dicap sebagai pembunuh dan pembakar yang kejam!",
  ui_story_5046_50461102_31_dialog_content = "Dan kamu, Caelestite, kamu akan menjadi komplotannya!",
  ui_story_5046_50461102_32_dialog_content = "Pada saat itu, tidak ada yang akan percaya satu hal pun yang Anda katakan.",
  ui_story_5046_50461102_33_dialog_content = "Apakah Anda benar-benar berpikir Anda dapat menutupi kebenaran !?",
  ui_story_5046_50461102_34_dialog_content = "Kamu benar-benar berpikir kamu sendiri yang bisa menjebak kami dengan kebohonganmu!?",
  ui_story_5046_50461102_35_dialog_content = "Kebenaran, kebohongan... Apa bedanya pada akhirnya?",
  ui_story_5046_50461102_36_dialog_content = "Yang penting aku melanjutkan hidupku sebagai ksatria, aman di Lumopolis, tanpa insiden lebih lanjut...",
  ui_story_5046_50461102_37_dialog_content = "Adapun kebenaran... itu akan terkubur dengan tulangmu, jauh di dalam bumi selamanya!",
  ui_story_5046_50461102_38_dialog_content = "Pak... Bagaimana Anda bisa mengatakan itu?",
  ui_story_5046_50461102_39_dialog_content = "Bukankah Anda selalu mengajari saya untuk menegakkan keadilan dan memperjuangkan kebenaran? Mengapa? Mengapa Anda mengatakan hal seperti itu ...?",
  ui_story_5046_50461102_40_dialog_content = "Kristen, apakah Anda menganggap saya orang penting di hati Anda?",
  ui_story_5046_50461102_41_dialog_content = "Ahh!",
  ui_story_5046_50461102_42_dialog_content = "Karena saya sangat berarti bagi Anda, tidakkah Anda akan berusaha keras untuk mempertahankan reputasi dan posisi saya, bahkan jika itu berarti mati untuk saya?",
  ui_story_5046_50461102_43_dialog_content = "Pak... Pak, apa yang kamu katakan...?",
  ui_story_5046_50461102_44_dialog_content = "Anda mempertaruhkan hidup Anda untuk menyelamatkan Kristen bertahun-tahun yang lalu! Bagaimana Anda bisa begitu kejam dengan mengancam akan membunuhnya ?!",
  ui_story_5046_50461102_45_dialog_content = "(Hati! Saya berbicara dengan Anda menggunakan kemampuan psikis saya! Kita perlu menemukan cara untuk menyelamatkan Kristen!)",
  ui_story_5046_50461102_46_dialog_content = "PlayerName?",
  ui_story_5046_50461102_47_dialog_content = "(Saya akan mengalihkan perhatian Zenas, Anda menemukan kesempatan untuk menyelinap ke arahnya!)",
  ui_story_5046_50461102_48_dialog_content = "Aku paham.",
  ui_story_5046_50461102_49_dialog_content = "Aku menyelamatkannya? Maksudmu api itu? Kurasa dia berutang lebih banyak padaku, kalau begitu. Sekarang dia memiliki kesempatan untuk membayar saya.",
  ui_story_5046_50461102_50_dialog_content = "Kecuali deduksi saya sebelumnya semuanya salah, Anda mempertaruhkan hidup Anda untuk bergegas ke dalam api dan menyelamatkan Kristen...",
  ui_story_5046_50461102_51_dialog_content = "Jadi bagaimana bisa kau berpikir untuk menyakitinya sekarang!?",
  ui_story_5046_50461102_52_dialog_content = "Ya, gadis kecil yang kukorbankan untuk diselamatkan dan diajar selama bertahun-tahun...",
  ui_story_5046_50461102_53_dialog_content = "Bagaimana mungkin aku memaksa diriku untuk menyakitinya?",
  ui_story_5046_50461102_54_dialog_content = "Pak…",
  ui_story_5046_50461102_55_dialog_content = "Tetapi Kristen, nona muda...",
  ui_story_5046_50461102_56_dialog_content = "Sejak awal, Anda hanyalah pion bagi saya.",
  ui_story_5046_50461102_57_dialog_content = "Dan itu termasuk api. Itu semua adalah bagian dari rencanaku.",
  ui_story_5046_50461102_58_dialog_content = "Apa!?",
  ui_story_5046_50461102_59_dialog_content = "Saya sudah lama ingin naik ke punggung bangsawan yang kuat dan memasuki masyarakat Lumopolis. Manor Anda kebetulan berada di dekatnya.",
  ui_story_5046_50461102_60_dialog_content = "Saya segera mengetahui bahwa semua orang yang bekerja di manor hari itu adalah orang bodoh yang lemah, jadi saya menyuap bantuan dan membakar tempat itu.",
  ui_story_5046_50461102_61_dialog_content = "Aku berpura-pura lewat dan berpura-pura seolah-olah aku mati-matian mempertaruhkan nyawa dan anggota badan untuk menyelamatkan wanita bangsawan Lumopolis yang malang ini.",
  ui_story_5046_50461102_62_dialog_content = "Benar saja, keluarganya sangat berterima kasih kepada saya, mengizinkan saya untuk dengan lancar memasuki masyarakat Lumopolis dan menjalani kehidupan yang selalu saya impikan.",
  ui_story_5046_50461102_63_dialog_content = "Itu semua berkat Anda, saya ... tidak, Kristen.",
  ui_story_5046_50461102_X63_dialog_content = "Dengar, wajahku terbakar untuk menyelamatkanmu!",
  ui_story_5046_50461102_64_dialog_content = "Kamu... Kamu menjijikkan! Aku tidak akan membiarkanmu!",
  ui_story_5046_50461102_65_dialog_content = "Apakah layak menjelek-jelekkan diri sendiri hanya untuk mengambil hati bangsawan Lumopolis?",
  ui_story_5046_50461102_66_dialog_content = "Pernahkah Anda merasakan kekuatan, Caelestite?",
  ui_story_5046_50461102_67_dialog_content = "Kekuasaan dapat ditukar dengan uang, tetapi uang tidak selalu dapat membeli kekuasaan.",
  ui_story_5046_50461102_68_dialog_content = "Selama Anda memiliki kekuatan, tidak ada yang berada di luar jangkauan Anda, dan tidak ada yang dapat menghalangi Anda!",
  ui_story_5046_50461102_69_dialog_content = "Bukankah itu benar, Kristen?",
  ui_story_5046_50461102_70_dialog_content = "Anda terlahir sebagai bangsawan Lumopolis. Itu pasti perasaan yang luar biasa, bukan?",
  ui_story_5046_50461102_71_dialog_content = "Gelisah terletak kepala yang bermahkota...",
  ui_story_5046_50461102_72_dialog_content = "Bangsawan harus memiliki karakter yang mulia.",
  ui_story_5046_50461102_73_dialog_content = "Mereka yang menggunakan status bangsawan untuk keuntungan pribadi tidak layak disebut bangsawan.",
  ui_story_5046_50461102_74_dialog_content = "Hahahahaha!",
  ui_story_5046_50461102_75_dialog_content = "Kristen, Anda benar-benar percaya setiap klise kosong yang saya ajarkan kepada Anda, bukan?",
  ui_story_5046_50461102_76_dialog_content = "Apakah Anda benar-benar percaya bahwa semua bangsawan seperti Anda, semurni dan semulia bunga bakung?",
  ui_story_5046_50461102_77_dialog_content = "Baiklah, cukup bicara.",
  ui_story_5046_50461102_78_dialog_content = "Hmm? Dimana Hati!?",
  ui_story_5046_50461102_79_dialog_content = "...",
  ui_story_5046_50461102_80_dialog_content = "(Sekarang, Hati!)",
  ui_story_5046_50461102_81_dialog_content = "Hya—!",
  ui_story_5046_50461102_82_dialog_content = "Ahh!",
  ui_story_5046_50461102_83_dialog_content = "Darimana asalmu!?",
  ui_story_5046_50461102_84_dialog_content = "Argh…",
  ui_story_5046_50461102_85_dialog_content = "Kristen, Apakah kamu baik-baik saja!?",
  ui_story_5046_50461102_86_dialog_content = "Biarkan saya membantu Anda ... Apakah Anda masih bisa berdiri?",
  ui_story_5046_50461102_87_dialog_content = "PlayerName... Huu huu...",
  ui_story_5046_50461102_88_dialog_content = "Datang ke sini.",
  ui_story_5046_50461102_89_dialog_content = "Tidak ada lagi sandera. Serahkan saja liontin itu.",
  ui_story_5046_50461102_90_dialog_content = "Atau apakah saya harus memberikan kejujuran kepada Anda?",
  ui_story_5046_50461102_91_dialog_content = "Baiklah... Ini, ini dia.",
  ui_story_5046_50461102_92_dialog_content = "Mau liontin...",
  ui_story_5046_50461102_93_dialog_content = "Anda dapat menukarnya dengan hidup Anda!",
  ui_story_5046_50461102_94_dialog_content = "<color=#e8d9bb>ding—</color>",
  ui_story_5046_50461102_95_dialog_content = "!!!",
  ui_story_5046_50461102_96_dialog_content = "Ahh!",
  ui_story_5046_50461102_97_dialog_content = "Berpura-pura menyerahkan liontin dan meluncurkan serangan diam-diam... Hmph!",
  ui_story_5046_50461102_98_dialog_content = "Sekarang kita tanpa senjata, siapa yang tahu siapa yang akan menang?",
  ui_story_5046_50461102_99_dialog_content = "Kristen dan Caelestite memiliki sedikit kekuatan tempur untuk dibicarakan, jadi sekarang...",
  ui_story_5046_50461102_100_dialog_content = "Hanya kamu dan aku.",
  ui_story_5046_50461102_101_dialog_content = "Setelah aku berurusan denganmu, aku akan mengurus mereka berdua...",
  ui_story_5046_50461102_102_dialog_content = "Hahahahaha!",
  ui_story_5046_50461102_103_dialog_content = "...",
  ui_story_5046_50461102_104_dialog_content = "Pedangku!",
  ui_story_5046_50461102_105_dialog_content = "Hmph! Sudahlah, kapak ini akan baik-baik saja.",
  ui_story_5046_50461102_106_dialog_content = "Kau tidak layak untuk pedang itu dengan semua darah di tanganmu.",
  ui_story_5046_50461102_X106_dialog_content = "Pedang melambangkan keadilan, namun kau jahat.",
  ui_story_5046_50461102_107_dialog_content = "Apakah menurut Anda keadilan akan selalu menang melawan kejahatan?",
  ui_story_5046_50461102_108_dialog_content = "Tentu saja.",
  ui_story_5046_50461102_109_dialog_content = "Jangan terlalu yakin kau akan mengalahkanku.",
  ui_story_5046_50461102_110_dialog_content = "<color=#e8d9bb>Dentang-</color>",
  ui_story_5046_50461102_111_dialog_content = "Pergi ke neraka!!!",
  ui_story_5046_50461102_112_dialog_content = "Hya!",
  ui_story_5046_50461102_113_dialog_content = "Aaaaaah!",
  ui_story_5046_50461102_114_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5046_50461102_115_dialog_content = "...",
  ui_story_5046_50461102_116_dialog_content = "Rasakan itu? Itu pedangmu menempel di lehermu.",
  ui_story_5046_50461102_117_dialog_content = "Aku bisa menggorok lehermu dalam sekejap dan membalaskan dendam ibuku.",
  ui_story_5046_50461102_118_dialog_content = "!!!",
  ui_story_5046_50461102_119_dialog_content = "Tapi aku tidak akan melakukannya.",
  ui_story_5046_50461102_120_dialog_content = "Karena PlayerName tidak ingin aku.",
  ui_story_5046_50461102_121_dialog_content = "Mom dan Dad juga tidak ingin darahmu ada di tanganku.",
  ui_story_5046_50461102_122_dialog_content = "Hei kau. Dia Kristen, Kanan?",
  ui_story_5046_50461102_123_dialog_content = "Argh…",
  ui_story_5046_50461102_124_dialog_content = "Sudah berhenti menangis. Sebelum Anda membawanya pergi, bisakah saya mendapatkan liontinnya?",
  ui_story_5046_50461102_125_dialog_content = "Liontin? Liontin apa? Apakah Anda berencana merampok saya?",
  ui_story_5046_50461102_126_dialog_content = "Kenapa kau masih tidak mau mengakui kejahatanmu!?",
  ui_story_5046_50461102_127_dialog_content = "Saya tidak mengerti apa yang Anda bicarakan.",
  ui_story_5046_50461102_128_dialog_content = "Pak... Tidak, Zenas.",
  ui_story_5046_50461102_129_dialog_content = "Menurut hasil penyelidikan ini, Anda terkait dengan kasus pembunuhan dan dua kasus pembakaran beberapa tahun lalu. Mohon kerjasamanya dengan saya.",
  ui_story_5046_50461102_130_dialog_content = "(Kristen pulih begitu cepat. Dia baru saja menangis...)",
  ui_story_5046_50461102_131_dialog_content = "Hmmm...",
  ui_story_5046_50461102_132_dialog_content = "Kau masih gadis yang keras kepala dan kuat seperti dulu...",
  ui_story_5046_50461102_133_dialog_content = "Saya tidak ingin mendengarkan apa pun lagi dari Anda sekarang. Jika Anda memiliki sesuatu untuk dikatakan, simpan untuk Hall of Justice.",
  ui_story_5046_50461102_134_dialog_content = "Jika Anda harus tahu, saya tidak benar-benar ingin membunuh Anda sekarang. Saya menyelamatkan Anda saat itu, dan Anda telah menemani saya selama bertahun-tahun.",
  ui_story_5046_50461102_135_dialog_content = "Bagaimana aku bisa membunuhmu?",
  ui_story_5046_50461102_136_dialog_content = "Mengapa Anda masih mencoba menipu saya?",
  ui_story_5046_50461102_137_dialog_content = "Dengan semua yang telah saya katakan kepada Anda, dapatkah Anda membedakan mana yang benar dan mana yang salah?",
  ui_story_5046_50461102_138_dialog_content = "Hentikan!",
  ui_story_5046_50461102_139_dialog_content = "Pembohong! Anda tidak lagi memiliki hak untuk menguliahi saya!",
  ui_story_5046_50461102_140_dialog_content = "Mulai sekarang, saya akan menilai siapa yang harus dipercaya dan siapa yang tidak dipercaya untuk diri saya sendiri.",
  ui_story_5046_50461102_141_dialog_content = "Saya sudah dewasa. Saya bukan lagi gadis kecil terlindung yang membutuhkan bimbingan Anda.",
  ui_story_5046_50461102_142_dialog_content = "Adapun kejahatan Anda, Dewan Kehakiman akan mencapai vonis yang adil.",
  ui_story_5046_50461102_143_dialog_content = "Maaf, PlayerName. Maaf karena kehilangan ketenanganku di depanmu...",
  ui_story_5046_50461102_144_dialog_content = "Saya akan segera mengantar Zenas kembali ke Lumopolis dan memberi tahu Anda tentang hasil persidangan pada waktunya.",
  ui_story_5046_50461102_145_dialog_content = "liontin saya.",
  ui_story_5046_50461102_146_dialog_content = "Yakinlah, ketika saya menemukan liontin itu, saya akan mengirimkannya kepada Anda secara pribadi.",
  ui_story_5046_50461201_1_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian...</color>",
  ui_story_5046_50461201_2_dialog_content = "Kristen!",
  ui_story_5046_50461201_3_dialog_content = "Selamat siang, PlayerName.",
  ui_story_5046_50461201_4_dialog_content = "Sudah lama, PlayerName.",
  ui_story_5046_50461201_5_dialog_content = "Oh, Pittman!",
  ui_story_5046_50461201_6_dialog_content = "Omong-omong, adalah Hati Di Sini? Kudengar dia datang mengunjungi Colossus.",
  ui_story_5046_50461201_7_dialog_content = "Kristen.",
  ui_story_5046_50461201_8_dialog_content = "Ini dia. Ini liontinnya.",
  ui_story_5046_50461201_9_dialog_content = "liontin ibu...",
  ui_story_5046_50461201_10_dialog_content = "Zenas kini telah diserahkan kepada saya untuk diinterogasi lebih lanjut.",
  ui_story_5046_50461201_11_dialog_content = "Terima kasih untukmu, PlayerName, kami juga menemukan petunjuk lebih lanjut yang penting <color=#FFB400>kasus lain itu</color>.",
  ui_story_5046_50461201_12_dialog_content = "Haha... Aku senang bisa membantu.",
  ui_story_5046_50461201_13_dialog_content = "Siapa yang mengira saya diculik akan menyebabkan begitu banyak drama?",
  ui_story_5046_50461201_14_dialog_content = "Ehem...",
  ui_story_5046_50461201_15_dialog_content = "Oh ya. Ada beberapa pertanyaan yang ingin saya tanyakan...",
  ui_story_5046_50461201_16_option_content = "Siapa pelaku sebenarnya dalam kasus pembakaran selama dua bulan terakhir?",
  ui_story_5046_50461201_17_dialog_content = "Investigasi kami menunjukkan bahwa kasus pembakaran di Umbraton selama dua bulan terakhir semuanya menggunakan bahan bakar yang sama, termasuk gladi bersih di panti asuhan.",
  ui_story_5046_50461201_18_dialog_content = "Saya mengirim seseorang untuk menyelidiki bahan bakar ini, dan tampaknya hanya ada beberapa toko yang menjualnya.",
  ui_story_5046_50461201_19_dialog_content = "Pemilik toko mengidentifikasi Zenas telah membeli bahan bakar ini dalam jumlah besar dua bulan lalu.",
  ui_story_5046_50461201_20_dialog_content = "Zenas juga mengaku memulai semua kebakaran ini dengan tujuan membungkam para korban.",
  ui_story_5046_50461201_21_dialog_content = "Tapi kenapa dia membunuh orang-orang itu?",
  ui_story_5046_50461201_22_dialog_content = "Ini terkait dengan <color=#FFB400>kasus itu</color>.",
  ui_story_5046_50461201_23_dialog_content = "Saat itu, lima karyawan, termasuk Hamell, menggunakan panti asuhan sebagai kedok untuk mengirimkan anak-anak untuk diujicobakan.",
  ui_story_5046_50461201_24_dialog_content = "Kecuali Zenas dan Hamell, tiga anak yatim piatu lainnya yang selamat dari kebakaran di panti asuhan tidak begitu baik.",
  ui_story_5046_50461201_25_dialog_content = "Jadi mereka bertiga menggunakan masa lalu mereka untuk memeras Zenas, dan Zenas terpaksa membayar mereka karena diam.",
  ui_story_5046_50461201_26_dialog_content = "Tapi mereka menuntut lebih dan lebih...",
  ui_story_5046_50461201_27_dialog_content = "Dan kemudian Zenas membungkam mereka secara permanen.",
  ui_story_5046_50461201_28_dialog_content = "Benar.",
  ui_story_5046_50461201_29_dialog_content = "Siapa yang membunuh Tuan Hamell?",
  ui_story_5046_50461201_30_dialog_content = "Zenas mengaku memulai kebakaran dan membunuh tiga mantan karyawan panti asuhan.",
  ui_story_5046_50461201_31_dialog_content = "Ada lima orang pekerja panti asuhan yang terlibat dalam kasus tersebut, termasuk Zenas.",
  ui_story_5046_50461201_32_dialog_content = "Jadi, Zenas membunuh Tuan Hamell?",
  ui_story_5046_50461201_33_dialog_content = "Sangat dicurigai, tetapi saat ini tidak ada bukti, dan dia belum mengakuinya.",
  ui_story_5046_50461201_34_dialog_content = "Apakah dia benar-benar bertanggung jawab atas begitu banyak pembunuhan...?",
  ui_story_5046_50461201_35_dialog_content = "(Kristen sepertinya dia tidak menerima ini dengan baik ...)",
  ui_story_5046_50461201_36_dialog_content = "Kristen, Apakah kamu baik-baik saja?",
  ui_story_5046_50461201_37_dialog_content = "Apakah Anda benar-benar melihat saya begitu lemah, PlayerName?",
  ui_story_5046_50461201_38_dialog_content = "T-Tidak, bukan itu yang kumaksud! saya hanya...",
  ui_story_5046_50461201_39_dialog_content = "Aku baik-baik saja.",
  ui_story_5046_50461201_40_dialog_content = "Saya ingat semua yang Anda katakan kepada saya hari itu, PlayerName.",
  ui_story_5046_50461201_41_dialog_content = "PlayerName mengatakan kepada saya bahwa saya akan menjadi hakim yang hebat di masa depan.",
  ui_story_5046_50461201_42_dialog_content = "Dengan begitu banyak orang di sekitar saya, menyemangati dan mendukung saya sepanjang waktu, tidak mungkin saya merasa sedih sendirian.",
  ui_story_5046_50461201_43_dialog_content = "Meskipun saya masih memiliki jalan panjang sebelum mencapai tujuan saya, saya akan melakukan yang terbaik untuk terus maju.",
  ui_story_5046_50461201_44_dialog_content = "Karena aku benar-benar hebat! Bukankah aku, PlayerName?",
  ui_story_5046_50461201_45_dialog_content = "Kita sedang berbicara tentang Kristen di sini, kan? Tentu saja kamu!",
  ui_story_5046_50461201_46_dialog_content = "Aku setuju.",
  ui_story_5046_50461201_47_dialog_content = "Saya mendukung itu.",
  ui_story_5046_50461201_48_dialog_content = "Oh! saya lupa Pak. Pittman masih disini...",
  ui_story_5046_50461201_49_dialog_content = "Ehem... sudah saya berikan Hati liontinnya, jadi kecuali Anda memiliki hal lain untuk didiskusikan dengan saya, izinkan saya untuk pergi.",
  ui_story_5046_50461201_50_dialog_content = "Sampai jumpa.",
  ui_story_5046_50461201_51_dialog_content = "...",
  ui_story_5046_50461201_52_dialog_content = "Merasa gugup, Hati?",
  ui_story_5046_50461201_53_dialog_content = "Ya.",
  ui_story_5046_50461201_54_dialog_content = "Kedua liontin ini sepasang. Ibuku memberiku setengah saat itu.",
  ui_story_5046_50461201_55_dialog_content = "Ibu berkata bahwa selama saya menyatukan kedua bagian ini, keluarga kami akan selalu bersama ...",
  ui_story_5046_50461201_56_dialog_content = "Tapi Ibu dan aku sudah lama berpisah... boo-hoo...",
  ui_story_5046_50461201_57_dialog_content = "Ibu... *menangis*",
  ui_story_5046_50461201_58_dialog_content = "Di sana, di sana, jangan menangis...",
  ui_story_5046_50461201_59_dialog_content = "(Tidak apa-apa Hati, jangan menangis.)",
  ui_story_5046_50461201_60_dialog_content = "(Biarkan Ibu menyanyikanmu untuk tidur ...)",
  ui_story_5046_50461201_61_dialog_content = "(Lalala ♪ Lalala ♪)",
  ui_story_5046_50461201_62_dialog_content = "(Hati, melihatmu tidur begitu nyenyak, kuharap saat ini bisa berlangsung selamanya.)",
  ui_story_5046_50461201_63_dialog_content = "(Tapi aku juga ingin melihatmu tumbuh dewasa. Aku yakin kamu akan semakin terlihat seperti Fenrir.)",
  ui_story_5046_50461201_64_dialog_content = "(Kamu hanya bola kecil yang lembut ketika kamu lahir, tapi sekarang kamu hampir setinggi lututku.)",
  ui_story_5046_50461201_65_dialog_content = "(Kamu mungkin lebih tua sekarang, tapi kamu masih suka aku memelukmu dan menidurkanmu, dan ketika kamu bangun, kamu masih memintaku untuk menggendongmu ke meja untuk makan malam ...)",
  ui_story_5046_50461201_66_dialog_content = "(Aku hampir tidak bisa mengangkatmu sekarang, apalagi berjalan denganmu!)",
  ui_story_5046_50461201_67_dialog_content = "(Ketika saya sudah tua dan tidak bisa berjalan lagi, Anda akan membawa saya ke tempat tidur dan meletakkan saya di bangku saya...)",
  ui_story_5046_50461201_68_dialog_content = "(Hati... Ada begitu banyak yang ingin kukatakan padamu...)",
  ui_story_5046_50461201_69_dialog_content = "(Kuharap aku bisa melihatmu dan tumbuh bersamamu, selalu...)",
  ui_story_5046_50461201_70_dialog_content = "(...)",
  ui_story_5046_50461201_71_dialog_content = "(...)",
  ui_story_5046_50461201_72_dialog_content = "(...)",
  ui_story_5046_50461201_73_dialog_content = "...",
  ui_story_5046_50461201_74_dialog_content = "Aku tidak takut padamu lagi, aku juga tidak akan takut pada... kekuatan ini.",
  ui_story_5046_50461201_75_dialog_content = "Saya bisa menerima diri saya sepenuhnya sekarang.",
  ui_story_5046_50461201_76_dialog_content = "Apakah itu Hati yang dulu takut akan kekuatannya dan membenci dirinya sendiri.",
  ui_story_5046_50461201_77_dialog_content = "Atau Hati yang menggunakan apinya untuk melindungi orang-orang yang penting baginya.",
  ui_story_5046_50461201_78_dialog_content = "Tidak peduli yang mana Hati itu, mereka semua adalah aku.",
  ui_story_5046_50461201_79_dialog_content = "(Apakah saya... siap menerima diri saya sendiri...?)",
  ui_story_5046_50461201_80_dialog_content = "Aku siap.",
  ui_story_5046_50461202_1_dialog_content = "Saya menang?",
  ui_story_5046_50461202_2_dialog_content = "Anda...?",
  ui_story_5046_50461202_3_dialog_content = "(Anda dapat menerima diri Anda sepenuhnya sekarang.)",
  ui_story_5046_50461202_4_dialog_content = "(Anda telah mencapai rekonsiliasi dengan diri sendiri.)",
  ui_story_5046_50461202_5_dialog_content = "(Saya sangat senang melihat Anda dapat menggunakan kekuatan Anda dengan sangat baik.)",
  ui_story_5046_50461202_6_dialog_content = "(Saya harus pergi sekarang.)",
  ui_story_5046_50461202_7_dialog_content = "Aku bisa merasakan kekuatan api...",
  ui_story_5046_50461202_8_dialog_content = "Kekuatan ini terus membanjiri tubuhku...",
  ui_story_5046_50461202_9_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5046_50461202_10_dialog_content = "Nyala api... Nyala api yang diciptakan oleh pikiranku...",
  ui_story_5046_50461202_11_dialog_content = "Ini hangat.",
  ui_story_5046_50461202_12_dialog_content = "PlayerName?",
  ui_story_5046_50461202_13_dialog_content = "Apakah kamu bangun? Aku hanya menyenandungkan lagu saat kau tertidur.",
  ui_story_5046_50461202_14_dialog_content = "Kau tampak begitu damai, aku tidak ingin membangunkanmu.",
  ui_story_5046_50461202_15_dialog_content = "Saya bermimpi tentang ketika saya masih kecil. Saya tidak sengaja membakar sesuatu dengan api saya, dan ibu saya menyuruh saya pergi.",
  ui_story_5046_50461202_16_dialog_content = "Dia memelukku dan menyanyikan lagu pengantar tidur sambil menggoyangku untuk tidur.",
  ui_story_5046_50461202_17_dialog_content = "Setelah aku tertidur, aku melihat...",
  ui_story_5046_50461202_18_dialog_content = "Setan batinku.",
  ui_story_5046_50461202_19_dialog_content = "Saya mengatakan kepadanya bahwa saya tidak lagi takut padanya.",
  ui_story_5046_50461202_20_dialog_content = "Lalu?",
  ui_story_5046_50461202_21_dialog_content = "Aku... mengalahkannya.",
  ui_story_5046_50461202_22_dialog_content = "Saya tidak lagi takut dengan nyala api. Aku bisa merasakan kehangatan mereka mengelilingiku.",
  ui_story_5046_50461202_23_dialog_content = "Ini seperti dipegang oleh ibu dan ayahku.",
  ui_story_5046_50461202_24_dialog_content = "Itu pasti mimpi yang indah.",
  ui_story_5046_50461202_25_dialog_content = "Saya berani menghadapi apapun. Aku mendapatkannya dari ayah dan ibuku.",
  ui_story_5046_50461202_26_dialog_content = "Dan darimu, PlayerName.",
  ui_story_5046_50461202_27_dialog_content = "Terima kasih telah ada untukku.",
  ui_story_5046_50461202_28_dialog_content = "Anda tidak perlu berterima kasih kepada saya. Bagaimanapun, kami adalah teman.",
  ui_story_5046_50461202_29_dialog_content = "Saya ingin menyatukan kedua bagian liontin itu sekarang. PlayerName, Akankah kamu bergabung denganku?",
  ui_story_5046_50461202_30_dialog_content = "Tentu! Mari kita lakukan ini bersama!",
  ui_story_5046_50461202_31_dialog_content = "<color=#e8d9bb>Klik—</color>",
  ui_story_5046_50461202_32_dialog_content = "Sesuatu tampaknya muncul di bagian bawah setelah menyatukan kedua bagian ...",
  ui_story_5046_50461202_33_dialog_content = "<color=#e8d9bb>*kertas dibuka*</color>",
  ui_story_5046_50461202_34_dialog_content = "I-Ini...",
  ui_story_5046_50461202_35_dialog_content = "Begitu banyak foto...",
  ui_story_5046_50461202_36_dialog_content = "Ini adalah... foto keluarga saya yang saya gambar ketika saya masih kecil.",
  ui_story_5046_50461202_37_dialog_content = "Ini adalah hal terakhir yang saya harapkan untuk ditemukan di liontin itu.",
  ui_story_5046_50461202_38_dialog_content = "Beberapa foto masa kecil Anda juga ada di sini!",
  ui_story_5046_50461202_39_dialog_content = "Ada dua foto lagi di sini...",
  ui_story_5046_50461202_40_dialog_content = "Ini pasti ibumu. Jadi, kalau begitu, ini harus...",
  ui_story_5046_50461202_41_dialog_content = "Ayah...",
  ui_story_5046_50461202_42_dialog_content = "Hah? Apakah itu ayahmu?",
  ui_story_5046_50461202_43_dialog_content = "Sepertinya mereka ada di laboratorium...",
  ui_story_5046_50461202_44_dialog_content = "Aku…",
  ui_story_5046_50461202_45_dialog_content = "Saya tidak pernah bertemu ayah saya.",
  ui_story_5046_50461202_46_dialog_content = "Tapi melihat foto ini, saya pikir itu pasti dia ...",
  ui_story_5046_50461202_47_dialog_content = "\"Selama kamu menyatukan kedua bagian ini, keluarga kita akan selalu bersama ...\"",
  ui_story_5046_50461202_48_dialog_content = "Sekarang keluarga kita akan bersama selamanya.",
  ui_story_5046_50461202_49_dialog_content = "<color=#e8d9bb>Di suatu tempat di Umbraton</color>",
  ui_story_5046_50461202_50_dialog_content = "Setelah menyerahkan surat itu kepada Zenas, saya mengikutinya.",
  ui_story_5046_50461202_51_dialog_content = "Kalian tetap tinggal dan menyisir setiap inci tempat itu.",
  ui_story_5046_50461202_52_dialog_content = "Siap, Pak!",
  ui_story_5046_50461202_53_dialog_content = "...",
  ui_story_5046_50461202_54_dialog_content = "(Kenapa dia pergi ke sini...? Apakah dia menuju ke panti asuhan?)",
  ui_story_5046_50461202_55_dialog_content = "Sudah lama sekali, teman lama.",
  ui_story_5046_50461202_56_dialog_content = "Kamu rupanya.",
  ui_story_5046_50461202_57_dialog_content = "(Hamell? Mungkinkah benda di tangannya itu yang diinginkan Shadowlord?)",
  ui_story_5046_50461202_58_dialog_content = "Tidak senang melihat teman lama Anda?",
  ui_story_5046_50461202_59_dialog_content = "Saya hanya khawatir Anda tidak di sini karena Anda ingin melihat saya, tetapi lebih karena Anda menginginkan sesuatu dari saya.",
  ui_story_5046_50461202_60_dialog_content = "Jangan terlalu sinis. Kali ini saya di sini untuk membawakan Anda beberapa berita.",
  ui_story_5046_50461202_61_dialog_content = "Jadi, dia meminta untuk bertemu. Apa hubungannya dengan saya?",
  ui_story_5046_50461202_62_dialog_content = "Andre dan dua lainnya sudah mati. Cepat atau lambat, giliran kita.",
  ui_story_5046_50461202_63_dialog_content = "Daripada menunggu dia datang ke rumah kita, ayo keluar untuk menyambutnya.",
  ui_story_5046_50461202_64_dialog_content = "(Rasanya seperti Hamell terus melihat ke sana tanpa sadar.)",
  ui_story_5046_50461202_65_dialog_content = "Saya tahu Anda ingin bertanya mengapa saya tidak melakukan apa-apa.",
  ui_story_5046_50461202_66_dialog_content = "Dalam suratnya ini, dia memanggil saya dengan nama. Jika ada yang mengetahui hubungan di antara kami, itu bisa membuat segalanya menjadi lebih rumit.",
  ui_story_5046_50461202_67_dialog_content = "Jika itu terjadi, aku tidak akan bisa melindungimu lagi. Siapa bilang ... Anda bahkan mungkin ketahuan juga.",
  ui_story_5046_50461202_68_dialog_content = "Kau mengancamku...",
  ui_story_5046_50461202_69_dialog_content = "Kita semua perlu menjaga diri kita sendiri. Ini alamatnya.",
  ui_story_5046_50461202_70_dialog_content = "Baik, saya dapat membantu Anda dalam hal ini, tetapi Anda perlu menemukan beberapa orang untuk membantu saya.",
  ui_story_5046_50461202_71_dialog_content = "Setelah Zenas pergi, saya mencari-cari saat Hamell tertidur dan menemukannya.",
  ui_story_5046_50461202_72_dialog_content = "Catatan tanggal transaksi, harga, dan informasi pembeli mereka.",
  ui_story_5046_50461202_73_dialog_content = "Mengesankan.",
  ui_story_5046_50461202_74_dialog_content = "Bertahun-tahun yang lalu, Umbraton adalah tanah yang kacau dan tanpa hukum. Penduduk Lumopolis memperlakukannya sebagai tempat pembuangan sampah tempat mereka mengubur dosa-dosa mereka.",
  ui_story_5046_50461202_75_dialog_content = "Sekarang saya adalah penjaga Umbraton, saya tidak akan membiarkannya kembali seperti semula.",
  ui_story_5046_50461202_76_dialog_content = "Bayangan tahu semua rahasia.",
  ui_story_5046_50461202_77_dialog_content = "Dimengerti, Shadowlord.",
  ui_story_5046_50461202_78_dialog_content = "Anda telah melakukannya dengan baik beberapa hari terakhir ini.",
  ui_story_5046_50461202_79_dialog_content = "<color=#e8d9bb>Lumopolis Prison</color>",
  ui_story_5046_50461202_80_dialog_content = "...",
  ui_story_5046_50461202_81_dialog_content = "Ini dia wanita muda saya.",
  ui_story_5046_50461202_82_dialog_content = "Di sini sangat dingin dan suram. Ini bukan tempat untuk wanita kecil sepertimu.",
  ui_story_5046_50461202_83_dialog_content = "Aku datang untuk mengucapkan selamat tinggal padamu, dan masa laluku.",
  ui_story_5046_50461202_84_dialog_content = "Saya selalu mengikuti Anda secara membabi buta, maju ke arah yang Anda inginkan baik dalam pikiran maupun tindakan saya.",
  ui_story_5046_50461202_85_dialog_content = "Aku adalah bonekamu.",
  ui_story_5046_50461202_86_dialog_content = "Nona muda, saya tidak pernah memaksa Anda untuk melakukan apa pun yang tidak Anda inginkan. Apa yang sedang kamu pikirkan?",
  ui_story_5046_50461202_87_dialog_content = "Aku muak mengetahui bahwa kamu berada di balik semua ini, namun kamu tetap mempengaruhi sikap acuh tak acuh ini!",
  ui_story_5046_50461202_88_dialog_content = "Anda lengkap dan benar-benar sampah!",
  ui_story_5046_50461202_89_dialog_content = "...",
  ui_story_5046_50461202_90_dialog_content = "Maaf, saya lupa diri.",
  ui_story_5046_50461202_91_dialog_content = "Liontin itu.",
  ui_story_5046_50461202_92_dialog_content = "Apa yang ada di liontin itu?",
  ui_story_5046_50461202_93_dialog_content = "Hanya itu yang ingin Anda tanyakan?",
  ui_story_5046_50461202_94_dialog_content = "...",
  ui_story_5046_50461202_95_dialog_content = "Saya membayar begitu banyak untuk liontin ini.",
  ui_story_5046_50461202_96_dialog_content = "Saya ingin tahu apakah ada sesuatu yang tersembunyi di dalam... Hal yang saya cari.",
  ui_story_5046_50461202_97_dialog_content = "Hanya ada beberapa foto keluarga Hati di dalamnya.",
  ui_story_5046_50461202_98_dialog_content = "Hanya beberapa foto?",
  ui_story_5046_50461202_99_dialog_content = "Hanya beberapa foto.",
  ui_story_5046_50461202_100_dialog_content = "Hahahahahaha!",
  ui_story_5046_50461202_101_dialog_content = "Yah, aku tidak pernah...",
  ui_story_5046_50461202_102_dialog_content = "Saya tidak berharap hal-hal menjadi seperti ini ...",
  ui_story_5046_50461202_103_dialog_content = "Jika Anda tidak punya hal lain untuk dikatakan ...",
  ui_story_5046_50461202_104_dialog_content = "Aku akan pergi.",
  ui_story_5046_50461202_105_dialog_content = "...",
  ui_story_5046_50461202_106_dialog_content = "Ini terakhir kali kita akan bertemu satu sama lain.",
  ui_story_5046_50461202_107_dialog_content = "Selamat tinggal Pak.",
  ui_story_5046_50461202_108_dialog_content = "(Selamat tinggal... ke masa laluku.)",
  ui_story_5046_50461202_109_dialog_content = "<color=#e8d9bb>Upacara Hari Penyelesaian Panti Asuhan Umbraton</color>",
  ui_story_5046_50461202_110_dialog_content = "Penyelesaian panti asuhan ini melambangkan upaya telaten dari warga Umbraton yang tak terhitung jumlahnya. Izinkan saya menggunakan kesempatan ini untuk mengungkapkan rasa terima kasih saya kepada orang-orang ini sekali lagi!",
  ui_story_5046_50461202_111_dialog_content = "Dengan ini saya nyatakan Panti Asuhan Umbraton selesai secara resmi!",
  ui_story_5046_50461202_112_dialog_content = "Selamat!",
  ui_story_5046_50461202_113_dialog_content = "Kemenangan yang luar biasa! Luar biasa!",
  ui_story_5046_50461202_114_dialog_content = "Saya berharap panti asuhan ini menjadi sumber dari banyak kenangan indah, dan kesalahan masa lalu tidak akan terulang lagi.",
  ui_story_5046_50461202_115_dialog_content = "Panti asuhan ini sekarang berada di bawah pengawasan Shadowlord Umbraton, jadi Anda tidak perlu khawatir tentang itu, PlayerName.",
  ui_story_5046_50461202_116_dialog_content = "Grimme!?",
  ui_story_5046_50461202_117_dialog_content = "Pada hari Zenas ditangkap, Hati dan saya pergi ke Firefly Bar mencari Anda, tetapi Anda tidak ada di sana...",
  ui_story_5046_50461202_118_dialog_content = "Aku punya bisnis untuk diurus.",
  ui_story_5046_50461202_119_dialog_content = "Ngomong-ngomong, di mana Hati?",
  ui_story_5046_50461202_120_dialog_content = "dia...",
  ui_story_5046_50461202_121_dialog_content = "Sekarang mari kita sambut dengan hangat pahlawan pemadam kebakaran panti asuhan kita—Hati!",
  ui_story_5046_50461202_122_dialog_content = "...",
  ui_story_5046_50461202_123_dialog_content = "Kemampuan pemadam kebakaran Hati yang heroik telah mencegah bencana di Umbraton selama dua bulan terakhir, memadamkan api besar dan kecil.",
  ui_story_5046_50461202_124_dialog_content = "Beberapa hari yang lalu, seorang gadis kecil terjebak dalam api saat latihan untuk upacara ini...",
  ui_story_5046_50461202_125_dialog_content = "Hati bergegas masuk tanpa berpikir dua kali dan menyelamatkannya ...",
  ui_story_5046_50461202_126_dialog_content = "Jadi, dia bukan pembakar...",
  ui_story_5046_50461202_127_dialog_content = "Dia benar-benar ada di sana menyelamatkan seseorang?",
  ui_story_5046_50461202_128_dialog_content = "Dia begitu berani, seperti pahlawan besar...",
  ui_story_5046_50461202_129_dialog_content = "Merindukan Bethel sangat bijaksana. Sekarang tidak ada seorang pun di Umbraton yang akan mengobati Hati seperti penjahat.",
  ui_story_5046_50461202_130_dialog_content = "Dia pintar. Saya tidak bisa menangani semuanya dengan baik ini bahkan jika saya memiliki tiga otak.",
  ui_story_5046_50461202_131_dialog_content = "Hehe... Kamu punya kelebihan sendiri, PlayerName. Jangan lupa, tidak ada manusia yang sempurna.",
  ui_story_5046_50461202_132_dialog_content = "Ini sangat menjengkelkan.",
  ui_story_5046_50461202_133_dialog_content = "Hei... Kamu lari dari panggung begitu cepat.",
  ui_story_5046_50461202_134_dialog_content = "Rambutku berdiri saat aku di atas sana.",
  ui_story_5046_50461202_135_dialog_content = "Anda akan terbiasa dengan itu. Lagipula, kamu belum lama berada di dunia luar, dan masih banyak hal yang bisa kamu pelajari di sini.",
  ui_story_5046_50461202_136_dialog_content = "Hmm…",
  ui_story_5046_50461202_137_dialog_content = "Hati, Apa rencanamu untuk masa depan?",
  ui_story_5046_50461202_138_dialog_content = "Aku…",
  ui_story_5046_50461202_139_dialog_content = "Aku tidak tahu.",
  ui_story_5046_50461202_140_dialog_content = "Menemukan ingatan saya yang hilang tentang ibu saya dulu adalah tujuan saya.",
  ui_story_5046_50461202_141_dialog_content = "Tapi sekarang tujuan itu telah tercapai...",
  ui_story_5046_50461202_142_dialog_content = "Saya tidak tahu apa lagi yang harus saya lakukan.",
  ui_story_5046_50461202_143_dialog_content = "Itu tidak masalah. Hidup pada dasarnya hanya satu tujuan demi satu!",
  ui_story_5046_50461202_144_dialog_content = "Anda harus selalu istirahat sebelum menemukan tujuan Anda berikutnya.",
  ui_story_5046_50461202_145_dialog_content = "Lagi pula, Anda sudah melakukannya dengan sangat baik dalam mencapai tujuan terakhir Anda.",
  ui_story_5046_50461202_146_dialog_content = "Tujuan saya selanjutnya?",
  ui_story_5046_50461202_147_dialog_content = "Saya tidak tahu apa tujuan saya selanjutnya.",
  ui_story_5046_50461202_148_dialog_content = "Anda akan menemukannya.",
  ui_story_5046_50461202_149_dialog_content = "Hidupmu baru saja dimulai!",
  ui_story_5046_50461202_150_dialog_content = "Seperti yang saya katakan sebelumnya, banyak hal baru dan menarik yang menunggu untuk Anda temukan di dunia ini!",
  ui_story_5046_50461202_151_dialog_content = "Untuk saat ini, nikmati saja waktu luang Anda selagi bisa!",
  ui_story_5046_50461202_152_dialog_content = "Ya.",
  ui_story_5046_50461202_153_dialog_content = "Terima kasih, PlayerName.",
  ui_story_5046_50461202_154_dialog_content = "Saya lebih khawatir tentang apakah Anda mungkin akan mengalami sakit kepala lagi segera ...",
  ui_story_5046_50461202_155_dialog_content = "Aku ingin tahu apa yang akan dikatakan oleh anjing besar yang mirip denganmu itu selanjutnya...",
  ui_story_5046_50461202_156_dialog_content = "Saya tidak keberatan.",
  ui_story_5046_50461202_157_dialog_content = "Kami sudah mencapai kesepakatan.",
  ui_story_5046_50461202_158_dialog_content = "Sekarang, kita adalah satu.",
  ui_story_5046_50461202_159_dialog_content = "Woah!",
  ui_story_5046_50461202_160_dialog_content = "Kamu terlihat seperti anjing besar itu!",
  ui_story_5046_50461202_161_dialog_content = "Ya.",
